using namespace std;

struct state {
  int x, y;
  int cost;
  bool operator>(const state& e) const {
    return cost > e.cost;
  }
};

int w, h;
char a[555][555];

int cost[555][555];
int prevx[555][555], prevy[555][555];
int done[555][555];

const int MAX_N = 555*555;
struct uni {
  int p[MAX_N];
  uni(){init();}
  void init(){ memset(p,-1,sizeof(p)); }
  int root(int a) {
    return p[a]<0?a:(p[a]=root(p[a]));
  }
  bool find(int a,int b){ return root(a) == root(b); }
  bool merge(int a,int b) {
    a = root(a);
    b = root(b);
    if( a == b ) return false;
    p[a] += p[b];
    p[b] = a;
    return true;
  }
  int size(int a){ return -p[root(a)]; }
};

uni u;
int ans1[555][555];
int ans2[555][555];

int main(void) {
  scanf("%d%d", &h, &w);
  int sx, sy;
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      scanf(" %c", a[i]+j);
      if (a[i][j] == '#') {
        sx = j;
        sy = i;
      }
    }
  }

  priority_queue<state, vector<state>, greater<state>> q;
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      cost[i][j] = 11111111;
      prevx[i][j] = -1;
      prevy[i][j] = -1;
    }
  }
  cost[sy][sx] = 0;
  q.push((state){sx, sy, 0});

  int dx[] = {0,1,0,-1}, dy[]={1,0,-1,0};
  int d = 1;
  while (!q.empty()) {
    state p = q.top(); q.pop();
    if (a[p.y][p.x] == '#' && !done[p.y][p.x]) {
      state pp = p;
      while (prevx[pp.y][pp.x] >= 0) {
        int yy = pp.y, xx = pp.x;
        pp.y = prevy[yy][xx];
        pp.x = prevx[yy][xx];
        if (done[pp.y][pp.x]) break;
        ans1[pp.y][pp.x] = 1;
      }
      queue<state> sq;
      sq.push((state){p.x, p.y, 0});
      done[p.y][p.x] = d;
      while (!sq.empty()) {
        state sp = sq.front(); sq.pop();
        for (int i = 0; i < 4; i++) {
          int nx = sp.x+dx[i];
          int ny = sp.y+dy[i];
          if (nx >= 0 && nx < w && ny >= 0 && ny < h &&
              !done[ny][nx] && a[ny][nx] == '#') {
            cost[ny][nx] = p.cost;
            done[ny][nx] = d;
            prevx[ny][nx] = prevx[p.y][p.x];
            prevy[ny][nx] = prevy[p.y][p.x];
            sq.push((state){nx, ny, 0});
            q.push((state){nx, ny, p.cost});
          }
        }
      }
      d += 1;
    }

    for (int i = 0; i < 4; i++) {
      int nx = p.x+dx[i];
      int ny = p.y+dy[i];
      if (nx >= 0 && nx < w && ny >= 0 && ny < h &&
          cost[ny][nx] > p.cost+1) {
        cost[ny][nx] = p.cost+1;
        prevx[ny][nx] = p.x;
        prevy[ny][nx] = p.y;
        q.push((state){nx, ny, p.cost+1});
      }
    }
  }

  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      printf("%c", i == 0 || a[i][j] == '#' || j%2 == 0 ? '#' : '.');
    }
    puts("");
  }

  puts("");

  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      printf("%c", i == h-1 || a[i][j] == '#' || j%2 == 1 ? '#' : '.');
    }
    puts("");
  }

  return 0;
}

