void solve() {
	cin >> H >> W;

	for(int i = 0; i < H; ++i) {
		string line;
		cin >> line;

		for(int j = 0; j < W; ++j) {
			P[i][j] = (line[j] == '#');
		}
	}

	for(int i = 0; i < H; ++i) {
		for(int j = 0; j < W; ++j) {
			if(i == 0 && j != 0) {
				enable(i, j, 0);
			} else if(i != 0 && j == 0) {
				enable(i, j, 1);
			} else {
				int t = max(i, j) & 1;
				t ^= 1;

				enable(i, j, t);
			}

			if(P[i][j]) {
				enable(i, j, 0);
				enable(i, j, 1);
			}
		}
	}

	for(int t = 0; t < 2; ++t) {
		cout << '\n';

		for(int i = 0; i < H; ++i) {
			for(int j = 0; j < W; ++j) {
