int board[555][555], r[555][555], b[555][555];

int main(){

    // 1. 入力情報.
    int H, W;
    scanf("%d %d", &H, &W);
    rep(i, H){
        char c[555];
        scanf("%s", c);
        rep(j, W) if(c[j] == '#') board[i][j] = 1; // 紫色.
    }

    // 2. 事前準備 および 紫色箇所を, 赤色, 青色 で 着色.
    rep(i, H){
        rep(j, W){
            // 1列目 … 赤色.
            if(j == 0)     r[i][j] = 1;

            // W列目 … 青色.
            if(j == W - 1) b[i][j] = 1;

            // それ以外 … 赤色 もしくは 青色.
            if(j > 0 && j < W - 1){
                if(i & 1){
                    b[i][j] = 1;
                    // 紫色あれば赤色も着色.
                    if(board[i][j]) r[i][j] = 1;
                }else{
                    r[i][j] = 1;
                    // 紫色あれば青色も着色.
                    if(board[i][j]) b[i][j] = 1;
                }
            }
        }
    }

    // 3. 出力.
    rep(i, H){
        rep(j, W) printf("%c", (r[i][j]) ? '#' : '.');
        puts("");
    }
    puts("");
    rep(i, H){
        rep(j, W) printf("%c", (b[i][j]) ? '#' : '.');
        puts("");
    }
    return 0;

}

