auto solve(ll h, ll w, const VS& v) {
  VVL ans(h, VL(w, -100));

  REP(i, h) REP(j, w) if (ans[i][j] == -100 && v[i][j] == '#') {
    queue<PAIR> q;
    q.emplace(i, j);
    ans[i][j] = 0;
    auto to = [&](ll y, ll x) {
      if (y < 0 || y >= h || x < 0 || x >= w) return;
      if (v[y][x] == '.') return;
      if (ans[y][x] > -1) return;
      ans[y][x] = 0;
      q.emplace(y, x);
    };
    while (!q.empty()) {
      auto p = q.front();
      auto y = p.first;
      auto x = p.second;
      q.pop();
      to(y + 1, x);
      to(y - 1, x);
      to(y, x + 1);
      to(y, x - 1);
    }
    {
      ll t = i - 1;
      while (t >= 0 && ans[t][j] == -100) {
	ans[t][j] = -1;
	--t;
      }
    }
    {
      ll t = j - 1;
      while (t >= 0 && ans[i][t] == -100) {
	ans[i][t] = 1;
	--t;
      }
    }
  }
  return ans;
}
signed main() {
  ll h, w;
  cin >> h >> w;
  VS v(h);
  cin >> v;

  auto ans = solve(h, w, v);

  REP(i, h) {
    REP(j, w) {
      cout << ((ans[i][j] == 0 || ans[i][j] == -1 || (i == 0 && j > 0)) ? '#'
									: '.');
    }
    BR();
  }
  BR();
  REP(i, h) {
    REP(j, w) {
      cout << ((ans[i][j] == 0 || ans[i][j] == 1 || j == 0) ? '#' : '.');
    }
    BR();
  }
  dump(ans);
}

#include <cstdio>
