using namespace std;
#define fst first
#define snd second
typedef pair<int,int> pii;
const int dx[4]={0,0,-1,1};
const int dy[4]={-1,1,0,0};
int h,w,id,n[505][505],sx,sy;
pii fa[505][505];
char a[505][505];
bool v[505][505],r[505][505],vis[505];
void dfs(int x,int y) {
    if (x<0||x>=h||y<0||y>=w||v[x][y]||a[x][y]!='#')
        return;
    v[x][y]=true;
    n[x][y]=id;
    for (int i=0;i<4;++i)
        dfs(x+dx[i],y+dy[i]);
}
queue<pii> que;
void bfs() {
    memset(v,0,sizeof v);
    memset(fa,-1,sizeof fa);
    que.push(pii(sx,sy));
    v[sx][sy]=true;
    while (!que.empty()) {
        int x=que.front().fst,y=que.front().snd;
        que.pop();
        for (int i=0;i<4;++i) {
            int tx=x+dx[i], ty=y+dy[i];
            if (tx<0||tx>=h||ty<0||ty>=w||v[tx][ty]||vis[n[tx][ty]])
                continue;
            v[tx][ty]=true;
            if (n[tx][ty])
                vis[n[tx][ty]]=true;
            fa[tx][ty]=pii(x,y);
            que.push(pii(tx,ty));
        }
    }
}
void pres(bool f) {
    for (int i=0;i<h;++i) {
        for (int j=0;j<w;++j)
            if (a[i][j]=='#')
                putchar('#');
            else
                putchar(r[i][j]==f?'#':'.');

        putchar('\n');
    }
}
int main()
{
    scanf("%d%d",&h,&w);
    for (int i=0;i<h;++i)
        scanf("%s",a[i]);
    for (int i=0;i<h;++i)
        for (int j=0;j<w;++j)
            if (!v[i][j]&&a[i][j]=='#') {
                ++id;
                dfs(i,j);
                sx=i;
                sy=j;
            }
    bfs();
    for (int i=0;i<h;++i)
        for (int j=0;j<w;++j)
            if (a[i][j]=='#'&&fa[i][j].fst!=-1) {
                int x=i,y=j,o;
                while (fa[x][y].fst!=-1) {
                    r[x][y]=true;
                    o=x;
                    x=fa[x][y].fst;
                    y=fa[o][y].snd;
                }
            }
    pres(false);
    putchar('\n');
    pres(true);
    return 0;
}

