void go(pii s, pii t) {
	while(true) {
		a[s.X][s.Y] = 2;
		if(s.X == t.X)
			break;
		s.X++;
	}
	while(true) {
		a[s.X][s.Y] = 2;
		if(s.Y == t.Y)
			break;
		if(s.Y < t.Y)
			s.Y++;
		else
			s.Y--;
	}
}

