void dfs(int x,int y)
{
	if(s[x][y] != '#' || chk[x][y]) return;
	chk[x][y] = 1;

	dfs(x+1, y);
	dfs(x-1, y);
	dfs(x, y+1);
	dfs(x, y-1);
}

