int dp[N][N], dp1[N][N];
int used[N][N];


void dfs(int dp[N][N], int i, int j, int c)
{
    if (i < 0 || j < 0 || i >= n || j >= m || dp[i][j] == 0)
        return;

    used[i][j] = 1;
    dfs(dp, i - 1, j, c);
    dfs(dp, i + 1, j, c);
    dfs(dp, i, j + 1, c);
    dfs(dp, i, j - 1, c);
}


bool conect(int dp[N][N])
{
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            used[i][j] = 0;


    int c = 1;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
        {
            if (!used[i][j])
                dfs(dp1, i, j, c++);
        }

    return c == 1;
}


