pii blo[N * N];

inline pii BFS(int x, int y) {
  queue <pii > Q;
  pii c;
  Q.push(make_pair(x, y));
  int U = x, D = x;
  while (!Q.empty()) {
    c = Q.front();
    Q.pop();
    U = min(U, c.first);
    D = max(D, c.first);
    rep(i, 0, 3) {
      x = c.first + dx[i];
      y = c.second + dy[i];
      if (G[x][y] == '#' && !vis[x][y]) {
	vis[x][y] = 1;
	Q.push(make_pair(x, y));
      }
    }
  }
  return make_pair(D, U);
}

int main() {
  int n, m, t = 0;
  scanf("%d%d", &n, &m);
  rep(i, 1, n) scanf("%s", G[i] + 1);
  rep(i, 1, n)
    rep(j, 1, m)
    if (G[i][j] == '#' && !vis[i][j]) blo[++ t] = BFS(i, j);
  sort(blo + 1, blo + t + 1);
  rep(i, 1, n) cho[i][1] = 1;
  for (int i = 1, k; i <= t;) {
    k = blo[i].first;
    int p = m;
    while (G[k][p] == '.') p --;
    rep(j, 1, p)
      if (G[k][j] == '.') cho[k][j] = 1;
    while (blo[i].second <= k && i <= t) i ++;
  }
  rep(i, 1, n) {
