    }
    putchar('\n');
  }
  putchar('\n');
  rep(i, 1, n) {
    rep(j, 1, m) {
      if (G[i][j] == '#' || !cho[i][j]) putchar('#');
      else putchar('.');
    }
    putchar('\n');
  }
  return 0;
}

