using namespace std;

constexpr int dx[] = {1, 0, -1, 0};
constexpr int dy[] = {0, 1, 0, -1};

int H, W;
string mas[505];
string ans[505];

void dfs(int y, int x)
{
        if ( y < 0 || x < 0 || y >= H || x >= W || mas[y][x] != '#' ) return;
        mas[y][x] = '.';
        for ( int i = 0; i < 4; i++ ) {
                dfs(y + dy[i], x + dx[i]);
        }
}

int main()
{
        cin >> H >> W;
        for ( int i = 0; i < H; i++ ) {
                cin >> mas[i];
                ans[i] = mas[i];
        }

        for ( int i = 0; i < W; i++ ) {
                ans[0][i] = 'R';
                ans[H - 1][i] = 'B';
        }
        for ( int i = 1; i < H - 1; i++ ) {
                ans[i][0] = 'R';
                ans[i][W - 1] = 'B';
        }

        for ( int i = 0; i < H; i++ ) {
                for ( int j = W - 1; j >= 0; j-- ) {
                        if ( mas[i][j] == '#' ) {
                                for ( int k = 0; k < i; k++ ) if ( ans[k][j] != '#' ) ans[k][j] = 'R';
                                for ( int k = 0; k < j; k++ ) if ( ans[i][k] != '#' ) ans[i][k] = 'R';
                                for ( int k = i + 1; k < H; k++ ) if ( ans[k][j] != '#' ) ans[k][j] = 'B';
                                for ( int k = j + 1; k < W; k++ ) if ( ans[i][k] != '#' ) ans[i][k] = 'B';
                                dfs(i, j);
                        }
                }
        }
        for ( int i = 0; i < H; i++ ) {
                for ( int j = 0; j < W; j++ ) {
                        if ( ans[i][j] == '#' || ans[i][j] == 'R' ) cout << '#';
                        else cout << '.';
                }
                cout << '\n';
        }
        cout << '\n';                           
        for ( int i = 0; i < H; i++ ) {
                for ( int j = 0; j < W; j++ ) {
                        if ( ans[i][j] == '#' || ans[i][j] == 'B' ) cout << '#';
                        else cout << '.';
                }
                cout << '\n';
        }

        return ( 0 );
}

