const int N = 505;

int n, m;
char s[N][N], b[N][N], c[N][N];

vector<vector<pair<int, int>>> sets;
int where[N][N];
set<int> existSets;

void unite(int x, int y) {
	//cerr << x << " unite " << y << endl;
	if (x == y) return;
	if (sets[x].size() > sets[y].size()) {
		swap(x, y);
	}
	for (auto p : sets[x]) {
		where[p.first][p.second] = y;
		sets[y].push_back(p);
	}
	sets[x].resize(0);
	existSets.erase(x);
}

const int dx[4] = {-1, 1, 0, 0};
const int dy[4] = {0, 0, 1, -1};

void activate(int x, int y) {
	if (where[x][y] == -1) {
		bool fnd = false;
		for (int dir = 0; dir < 4; dir++) {
			int nx = x + dx[dir], ny = y + dy[dir];
			if (where[nx][ny] != -1) {
				where[x][y] = where[nx][ny];
				sets[where[nx][ny]].push_back(make_pair(x, y));
				fnd = true;
			}
		}
		if (!fnd) {
			where[x][y] = (int)sets.size();
			existSets.insert(where[x][y]);
			sets.push_back({{x, y}});
		}
		for (int dir = 0; dir < 4; dir++) {
			int nx = x + dx[dir], ny = y + dy[dir];
			if (where[nx][ny] != -1) {
				unite(where[x][y], where[nx][ny]);
			}
		}
	}
}

void processSeq(const vector<pair<int, int>> & seq) {
	//cerr << seq << endl;
	for (auto p : seq) {
		activate(p.first, p.second);
	}
}

void goFromTo(int x, int y, int xx, int yy) {
	static vector<pair<int, int>> seq;
	seq.resize(0);
	while (x < xx) {
		seq.push_back({x, y});
		x++;
	}
	while (x > xx) {
		seq.push_back({x, y});
		x--;
	}
	while (y < yy) {
		seq.push_back({x, y});
		y++;
	}
	while (y > yy) {
		seq.push_back({x, y});
		y--;
	}
	seq.push_back({x, y});
	processSeq(seq);
}

int main() {
	srand(time(0));
#ifdef LOCAL 
	freopen("input.txt", "r", stdin);
#else
#endif

	memset(where, 255, sizeof(where));

	scanf("%d%d", &n, &m);

	for (int i = 0; i < n; i++) {
		scanf("%s", s[i]);
		fill(b[i], b[i] + m, '.');
		fill(c[i], c[i] + m, '.');
	}

	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			if (s[i][j] == '#') {
				activate(i, j);
			}
		}
	}


	while (existSets.size() > 1) {
		int x = *existSets.begin();
		int y = *(++existSets.begin());
		cerr << "x = " << sets[x] << ", y = " << sets[y] << endl;
		goFromTo(sets[x].begin()->first, sets[x].begin()->second, sets[y].begin()->first, sets[y].begin()->second);
	}

	int cur = *existSets.begin();

	for (auto p : sets[cur]) {
		b[p.first][p.second] = '#';
	}

	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			if (b[i][j] != '#' || s[i][j] == '#') c[i][j] = '#';
		}
	}

	for (int i = 0; i < n; i++) {
		puts(b[i]);
	}
	puts("");
	for (int i = 0; i < n; i++) {
		puts(c[i]);
	}
}

