const int UF_MAX = 1000000;

class UF{
	int x[UF_MAX];

public:

	void dft(){
		for(int i = 0 ; i < UF_MAX ; ++i) x[i] = -1;
	}

	int Boss(int a){
		int s = a;
		while(x[s] > -1) s = x[s];
		if(s != a) x[a] = s;
		return s;
	}

	void Union(int a , int b){
		int s = Boss(a);
		int t = Boss(b);
		if(s != t){
			if(x[s] < x[t]){
				x[s] += x[t];
				x[t] = s;
			} else {
				x[t] += x[s];
				x[s] = t;
			}
		}
	}

	bool Find(int a , int b){
		return Boss(a) == Boss(b);
	}

	int Count(int a){
		int b = 0;
		for(int i = 0 ; i < a ; ++i) if(x[i] < 0) ++b;
		return b;
	}
};

