#include <cstdio>
#include <algorithm>
using namespace std;

typedef pair <int, int> pii;

const int MAXN = 505;

const int dx[] = {-1, 0, 1, 0};
const int dy[] = {0, 1, 0, -1};

int N, M;
char mat[MAXN][MAXN];
bool bio[MAXN][MAXN];

void load() {
    scanf("%d%d", &N, &M);
    for (int i = 0; i < N; i++)
        scanf("%s", mat[i]);
}

bool ok(int x, int y) {
    return x >= 0 && x < N && y >= 0 && y < M && !bio[x][y];
}

pii dfs(int x, int y) {
    bio[x][y] = true;
    pii res(x, y);
    for (int i = 0; i < 4; i++) {
        int nx = x + dx[i];
        int ny = y + dy[i];
        if (ok(nx, ny) && mat[nx][ny] == '#')
            res = max(res, dfs(nx, ny));
    }
    return res;
}

bool check(pii pos) {
    for (int i = 1; i < 4; i++) {
        int nx = pos.first + dx[i];
        int ny = pos.second + dy[i];
        if (ok(nx, ny) && mat[nx][ny] != '.')
            return true;
    }
    return false;
}

void solve() {
    for (int i = 0; i < M; i++)
        mat[N - 1][i] = '*';

    for (int i = 0; i < N; i++)
        for (int j = 0; j < M; j++)
            if (ok(i, j) && mat[i][j] == '#') {
                pii mx = dfs(i, j);
                for (mx.first++; mx.first < N; mx.first++) {
                    mat[mx.first][mx.second] = '*';
                    if (check(mx)) break;
                }                    
            }    

    for (int i = 0; i < N; i++, puts(""))
        for (int j = 0; j < M; j++)
            printf("%c", mat[i][j] == '.' ? '.' : '#');
    puts("");
    for (int i = 0; i < N; i++, puts(""))
        for (int j = 0; j < M; j++)
            printf("%c", mat[i][j] == '*' ? '.' : '#');
}

int main() {
    load();
    solve();
    return 0;
}

