#include <iostream>
#include <stack>
using namespace std;
typedef pair<int,int> P;
char map[500][500];
int H,W;

bool isAdjRed(int x, int y){
    if(x>0){
        if(map[y][x-1]=='P'||map[y][x-1]=='R') return true;
    }
    if(y>0){
        if(map[y-1][x]=='P'||map[y-1][x]=='R') return true;
    }
    return false;
}

bool isAdjBlue(int x, int y){
    if(x<W-1){
        if(map[y][x+1]=='P'||map[y][x+1]=='B') return true;
    }
    if(y<H-1){
        if(map[y+1][x]=='P'||map[y+1][x]=='B') return true;
    }
    return false;
}

int main(){
    cin>>H>>W;
    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            cin>>map[i][j];
        }
    }
    stack<P> S;
    //RED
    map[0][0]='R';
    for(int w=0;w<W;w++){
        for(int h=0;h<W;h++){
            if(map[h][w]=='#'){
                map[h][w]='P';
                int x=w,y=h;
                while(true){
                    if(isAdjRed(x,y)) break;
                    //左へ進めるか？
                    if(x>0&&map[y][x-1]!='B'){
                        x--;
                        S.push(P(x,y));
                        continue;
                    }
                    //上へ進めるか？
                    if(y>0&&map[y-1][x]!='B'){
                        y--;
                        S.push(P(x,y));
                        continue;
                    }
                }
                while(!S.empty()){
                    P p = S.top(); S.pop();
                    map[p.second][p.first]='R';
                }
            }
        }
    }

    //BLUE
    map[H-1][W-1]='B';
    for(int h=H-1;h>=0;h--){
        for(int w=W-1;w>=0;w--){
            if(map[h][w]=='P'){
                int x=w,y=h;
                while(true){
                    if(isAdjBlue(x,y)) break;
                    //下へ進めるか？
                    if(y<H-1&&map[y+1][x]!='R'){
                        y++;
                        S.push(P(x,y));
                        continue;
                    }
                    //右へ進めるか？
                    if(x<W-1&&map[y][x+1]!='R'){
                        x++;
                        S.push(P(x,y));
                        continue;
                    }
                }
                while(!S.empty()){
                    P p = S.top(); S.pop();
                    map[p.second][p.first]='B';
                }
            }
        }
    }

    //Redを出力
    for(int h=0;h<H;h++){
        for(int w=0;w<W;w++){
            switch(map[h][w]){
                case '.':
                case 'B':
                    cout<<'.';
                    break;
                case 'P':
                case 'R':
                    cout<<'#';
                    break;
                default:
                    break;
            }
        }
        cout<<endl;
    }
    cout<<endl;
    //Blueを出力
    for(int h=0;h<H;h++){
        for(int w=0;w<W;w++){
            switch(map[h][w]){
                case '.':
                case 'R':
                    cout<<'.';
                    break;
                case 'P':
                case 'B':
                    cout<<'#';
                    break;
                default:
                    break;
            }
        }
        cout<<endl;
    }
    return 0;
}

