using namespace std;

int H, W;
vector<string> P, R, B;

void init_data(void) {
	string x(W - 1, '#');
	string y(W - 1, '.');
	R.resize(H);
	B.resize(H);
	string r0 = x + ".";
	string r1 = "#" + y;
	for (int j = 0; j < H; ++j) {
		if (j % 2 == 0)
			R[j] = r0;
		else
			R[j] = r1;
	}
	string b0 = y + "#";
	string b1 = "." + x;
	for (int j = 0; j < H; ++j) {
		if (j % 2 == 0)
			B[j] = b0;
		else
			B[j] = b1;
	}
}

void solve(void) {
	for (int j = 1; j < H - 1; j += 2) {
		for (int i = 1; i < W - 1; ++i) {
			if (P[j][i] == '#')
				R[j][i] = '#';
		}
	}
	for (int j = 2; j < H - 1; j += 2) {
		for (int i = 1; i < W - 1; ++i) {
			if (P[j][i] == '#')
				B[j][i] = '#';
		}
	}
}

int main(void) {
	cin >> H >> W;
	P.resize(H);
	for (int j = 0; j < H; ++j)
		cin >> P[j];

	init_data();
	solve();

	for (int j = 0; j < H; ++j)
		cout << R[j] << '\n';
	cout << '\n';
	for (int j = 0; j < H; ++j)
		cout << B[j] << '\n';

	return 0;
}

