						board1[j][nowy]='#';
					}
					flag = false;
					break;
				}
			}
			else{
				if(i==1){
					for(int j=nowy-1;j>0;j--){
						if(board1[nowx][j]=='#'){
							flag1 = false;
							break;
						}
					}
					if(flag1){
						for(int j=nowy-1;j>0;j--){
							board1[nowx][j]='#';
						}
						flag = false;
						break;
					}
				}
				else{
					if(i==2){
						for(int j=nowx+1;j<h-1;j++){
							if(board1[j][nowy]=='#'){
								flag1 = false;
								break;
							}
						}
						if(flag1){
							for(int j=nowx+1;j<h-1;j++){
								board1[j][nowy]='#';
							}
							flag = false;
							break;
						}
					}
					else{
						for(int j=nowy+1;j<w-1;j++){
							if(board1[nowx][j]=='#'){
								flag1 = false;
								break;
							}
						}
						if(flag1){
							for(int j=nowy+1;j<w-1;j++){
								board1[nowx][j]='#';
							}
							flag = false;
							break;
						}
					}
				}
			}
		}
		if(flag){
			for(int i=nowx-1;i>0;i--){
				board1[i][nowy]='#';
			}
		}
	}
	for(int i=0;i<h;i++){
		for(int j=0;j<w;j++){
			if(board1[i][j]=='#')board2[i][j]='.';
			else board2[i][j]='#';
