#include <bits/stdc++.h>

using namespace std;

const int N = 510;
int color[N][N];
char c[N][N];
int h, w;

void print(int flag) {
    for (int i = 1; i <= h; i++) {
        for (int j = 1; j <= w; j++) {
            cout << (c[i][j] == '#' ? "#" : color[i][j] == flag ? "#" : ".");
        }
        cout << "\n";
    }
}

int dx[] = {0, -1, 1, 0};
int dy[] = {-1, 0, 0, 1};

bool good(int x, int y) {
    return x >= 1 && x <= h && y >= 1 && y <= w;
}

queue<pair<int, int> > q;

int numberComponent[N][N];

void dfs(int x, int y, int num) {
    q.push({x, y});
    numberComponent[x][y] = num;
    color[x][y] = 1;
    for (int k = 0; k < 4; k++) {
        int nx = x + dx[k], ny = y + dy[k];
        if (good(nx, ny) && numberComponent[nx][ny] != num && c[nx][ny] == '#')
            dfs(nx, ny, num);
    }
}

int fromx[N][N], fromy[N][N];

void path(int x, int y) {
    cout << x << " " << y << endl;
    while (c[x][y] != '#') {
        color[x][y] = 1;
        int px = fromx[x][y], py = fromy[x][y];
        x = px, y = py;
    }
}

map<int, int> mp[N];

void solve() {
    cin >> h >> w;
    for (int i = 1; i <= h; i++) {
        for (int j = 1; j <= w; j++) {
            cin >> c[i][j];
            if (i == 1 || i == h || j == 1 || j == w)
                color[i][j] = 2;
        }
    }
    int num = 1;
    for (int i = 1; i <= h; i++) {
        for (int j = 1; j <= w; j++) {
            if (c[i][j] == '#' && !color[i][j]) {
                dfs(i, j, num++);
            }
        }
    }
    num -= 2;
    cout << q.size() << endl;
    while (!q.empty()) {
        if (!num)
            break;
        int x, y; tie(x, y) = q.front(); q.pop();
        for (int k = 0; k < 4 && num; k++) {
            int nx = x + dx[k], ny = y + dy[k];
            if (!good(nx, ny))
                continue;
            if (numberComponent[nx][ny] != numberComponent[x][y]) {
                if (mp[numberComponent[x][y]].count(numberComponent[nx][ny])) {
                    continue;
                }
                if (numberComponent[nx][ny]) { // fixed two new
                    path(x, y);
                    path(nx, ny);
                    num--;
                    mp[numberComponent[x][y]][numberComponent[nx][ny]] = 1;
                    mp[numberComponent[nx][ny]][numberComponent[x][y]] = 1;
                }
                fromx[nx][ny] = x, fromy[nx][ny] = y;
                numberComponent[nx][ny] = numberComponent[x][y];
                q.push({nx, ny});
            }
        }
    }
    print(1);
    cout << "\n";
    print(2);
}

int main() {
    ios::sync_with_stdio(NULL), cin.tie(0), cout.tie(0);
    cout.setf(ios::fixed), cout.precision(20);
    solve();
}

