using namespace std;

const int fx[4]={0,0,1,-1},fy[4]={1,-1,0,0};
int n,m,lst[510][510][2];
bool flag[510][510],ans[510][510];
char a[510][510];

void cover(int x,int y)
{
    for (int u,v; !ans[x][y]; ans[x][y]=1,x=u,y=v)
        u=lst[x][y][0],v=lst[x][y][1];
}

void bfs(int x,int y)
{
    static int q[250100][2],head,tail;
    flag[q[0][0]=x][q[0][1]=y]=1;
    for (; head<=tail; ++head)
    {
        x=q[head][0],y=q[head][1];
        if (a[x][y]=='#')
            cover(x,y);
        repu(i,0,3)
        {
            int u=x+fx[i],v=y+fy[i];
            if (u && u<=n && v && v<=m && !flag[u][v])
            {
                ++tail,flag[q[tail][0]=u][q[tail][1]=v]=1;
                lst[u][v][0]=x,lst[u][v][1]=y;
            }
        }
    }
}

