    return dsu[i];
}

void edge(int i, int j) {
    i = get(i), j = get(j);
    dsu[j] = i;
}

void solve() {
    int n, m;
    cin >> n >> m;
    forn(i, n) {
        forn(j, m) dsu[i * m + j] = i * m + j;
    }
    vs a(n);
    forn(i, n) cin >> a[i];
    vvi comp(n, vi(m, -1));
    int C = 0;
    vvb used(n, vb(m));
    forn(i, n) {
        forn(j, m) {
            if (a[i][j] == '.') continue;
            queue<pii> q;
            q.push({i, j});
            used[i][j] = 1;
            comp[i][j] = C;
            while (!q.empty()) {
                int x = q.front().F, y = q.front().S;
                q.pop();
                if (x > 0 && !used[x - 1][y] && a[x - 1][y] == '#') {
                    used[x - 1][y] = 1;
                    comp[x - 1][y] = C;
                    q.push({x - 1, y});
                }
                if (x + 1 < n && !used[x + 1][y] && a[x + 1][y] == '#') {
                    used[x + 1][y] = 1;
                    comp[x + 1][y] = C;
                    q.push({x + 1, y});
                }
                if (y > 0 && !used[x][y - 1] && a[x][y - 1] == '#') {
                    used[x][y - 1] = 1;
                    comp[x][y - 1] = C;
                    q.push({x, y - 1});
                }
                if (y + 1 < m && !used[x][y + 1] && a[x][y + 1] == '#') {
                    used[x][y + 1] = 1;
                    comp[x][y + 1] = C;
                    q.push({x, y + 1});
                }
            }
            C++;
        }
    }
    vvi I(C);
    forn(i, n){
        forn(j, m){
            if (a[i][j] == '#') I[comp[i][j]].pb(i * m + j);
        }
    }
    forn(i, C){
        forn1(j, I[i].size()) edge(I[i][j - 1], I[i][j]);
    }
    vs r(n), b(n);
    forn(i, n) {
        forn(j, m) {
            r[i] += ".";
            b[i] += ".";
            if (a[i][j] == '#') r[i][j] = b[i][j] = '#';
        }
    }
    queue<pii> q;
    vvb vis(n, vb(m));
    forn(i, n) {
        forn(j, m) {
