        }
        if (y + 1 < m && !vis[x][y + 1]) {
            vis[x][y + 1] = 1;
            q.push({x, y + 1});
        }
    }
    forn(i, n) cout << r[i] << '\n';
    cout << '\n';
    forn(i, n) cout << b[i] << '\n';
