void search(int x,int y){
  if(x<0||x>=W||y<0||y>=H) return;
  if(ansr.at(y).at(x)==true && S.at(y).at(x)=='.') return;//trueは#の証、Sも#なら紫でセーフ
  if(ansb.at(y).at(x)) return;

  ansb.at(y).at(x)=true;

  search(x+1,y);
  search(x,y+1);
  search(x-1,y);
  search(x,y-1);
}

