vector<string> genRoll(int H, int W){
	vector<string> res(H, string(W, '.'));
	int dx[] = {1, 0, -1, 0};
	int dy[] = {0, 1, 0, -1};
	int x[2] = {0, W-1};
	int y[2] = {0, H-1};
	int dir[2] = {0, 2};
	res[y[0]][x[0]] = 'R';
	res[y[1]][x[1]] = 'B';
	while(true){
		for(int i=0;i<2;i++){
			bool mark = false;
			for(int d=0;d<4;d++){
				int nx = x[i] + dx[(dir[i]+d)%4];
				int ny = y[i] + dy[(dir[i]+d)%4];
				if(nx < 0 || W <= nx || ny < 0 || H <= ny || res[ny][nx] != '.') continue;
				res[ny][nx] = "RB"[i];
				x[i] = nx;
				y[i] = ny;
				dir[i] = (dir[i]+d)%4;
				mark = true;
				break;
			}
			if(!mark) return res;
		}
	}
	return res;
}

int main(){
	int H, W;
