point inicial, ultimo, aux, dad[510][510];
queue<point> cola;

void BfsPainter(){
    cola.push(inicial);
    visited[inicial.first][inicial.second] = iter;
    while(!cola.empty()){
        aux = cola.front();
        cola.pop();
        if(!aux.first || !aux.second || aux.first > h || aux.second > w || (blue[aux.first][aux.second] && sum[aux.first][aux.second] != 'm'))
            continue;
        if(aux != inicial && red[aux.first][aux.second]){
            ultimo = aux;
            break;
        }
        ++aux.first;
        if(visited[aux.first][aux.second] != iter){
            dad[aux.first][aux.second] = point(-1, 0);
            visited[aux.first][aux.second] = iter;
            cola.push(point(aux.first, aux.second));
        }
        aux.first -= 2;
        if(visited[aux.first][aux.second] != iter){
            dad[aux.first][aux.second] = point(1, 0);
            visited[aux.first][aux.second] = iter;
            cola.push(point(aux.first, aux.second));
        }
        ++aux.first;
        ++aux.second;
        if(visited[aux.first][aux.second] != iter){
            dad[aux.first][aux.second] = point(0, -1);
            visited[aux.first][aux.second] = iter;
            cola.push(point(aux.first, aux.second));
        }
        aux.second -= 2;
        if(visited[aux.first][aux.second] != iter){
            dad[aux.first][aux.second] = point(0, 1);
            visited[aux.first][aux.second] = iter;
            cola.push(point(aux.first, aux.second));
        }
    }
    ++iter;
    while(!cola.empty())
        cola.pop();
    while(true){
        aux = point(aux.first + dad[aux.first][aux.second].first, aux.second + dad[aux.first][aux.second].second);
        if(aux == inicial) break;
        red[aux.first][aux.second] = true;
    }
    cola.push(inicial);
    visited[inicial.first][inicial.second] = iter;
    while(!cola.empty()){
        aux = cola.front();
        cola.pop();
        if(!aux.first || !aux.second || aux.first > h || aux.second > w || (red[aux.first][aux.second] && sum[aux.first][aux.second] != 'm'))
            continue;
        if(aux != inicial && blue[aux.first][aux.second])
            break;
        ++aux.first;
        if(visited[aux.first][aux.second] != iter){
            dad[aux.first][aux.second] = point(-1, 0);
            visited[aux.first][aux.second] = iter;
            cola.push(point(aux.first, aux.second));
        }
        aux.first -= 2;
        if(visited[aux.first][aux.second] != iter){
            dad[aux.first][aux.second] = point(1, 0);
            visited[aux.first][aux.second] = iter;
            cola.push(point(aux.first, aux.second));
        }
        ++aux.first;
        ++aux.second;
        if(visited[aux.first][aux.second] != iter){
            dad[aux.first][aux.second] = point(0, -1);
            visited[aux.first][aux.second] = iter;
            cola.push(point(aux.first, aux.second));
        }
        aux.second -= 2;
        if(visited[aux.first][aux.second] != iter){
            dad[aux.first][aux.second] = point(0, 1);
            visited[aux.first][aux.second] = iter;
            cola.push(point(aux.first, aux.second));
        }
    }
    ++iter;
    while(!cola.empty())
        cola.pop();
    while(true){
        aux = point( aux.first + dad[aux.first][aux.second].first, aux.second + dad[aux.first][aux.second].second);
