#include <bits/stdc++.h>

using namespace std;

const int N = 510;
int color[N][N];
char c[N][N];
int h, w;

int p[N * N];

int getp(int v) {
    return p[v] == v ? v : p[v] = getp(p[v]);
}

mt19937 rnd;

void print(int flag) {
    for (int i = 1; i <= h; i++) {
        for (int j = 1; j <= w; j++) {
            cout << (c[i][j] == '#' ? "#" : color[i][j] == flag ? "#" : ".");
        }
        cout << "\n";
    }
}

int dx[] = {0, -1, 1, 0};
int dy[] = {-1, 0, 0, 1};

bool good(int x, int y) {
    return x >= 1 && x <= h && y >= 1 && y <= w;
}

queue<pair<int, int> > q;

int ncmp[N][N];

void dfs(int x, int y, int num) {
    //cout << x << " " << y << " " << num << endl;
    q.push({x, y});
    ncmp[x][y] = num;
    color[x][y] = 1;
    for (int k = 0; k < 4; k++) {
        int nx = x + dx[k], ny = y + dy[k];
        if (good(nx, ny) && c[nx][ny] == '#' && !ncmp[nx][ny]) {
            int v = getp((x - 1) * w + y), u = getp((nx - 1) * w + ny);
            if (rnd() % 2)
                p[v] = u;
            else
                p[u] = v;
            dfs(nx, ny, num);
        }
    }
}

void dfs1(int x, int y) {
    color[x][y] = 2;
    for (int k = 0; k < 4; k++) {
        int nx = x + dx[k], ny = y + dy[k];
        if (good(nx, ny) && !color[x][y])
            dfs1(nx, ny);
    }
}

int fromx[N][N], fromy[N][N];

void path(int x, int y) {
    while (c[x][y] != '#') {
        color[x][y] = 1;
        int px = fromx[x][y], py = fromy[x][y];
        x = px, y = py;
    }
}

void solve() {
    cin >> h >> w;
    for (int i = 1; i <= h; i++) {
        for (int j = 1; j <= w; j++) {
            cin >> c[i][j];
            if (i == 1 || i == h || j == 1 || j == w)
                color[i][j] = 2;
        }
    }
    iota(p + 1, p + 1 + h * w, 1);
    int num = 1;
    for (int i = 1; i <= h; i++) {
        for (int j = 1; j <= w; j++) {
            if (c[i][j] == '#' && !color[i][j]) {
                dfs(i, j, num++);
            }
        }
    }
    num -= 2;
    while (!q.empty()) {
        if (!num)
            break;
        int x, y; tie(x, y) = q.front(); q.pop();
        for (int k = 0; k < 4 && num; k++) {
            int nx = x + dx[k], ny = y + dy[k];
            if (!good(nx, ny))
                continue;
            int v = getp((x - 1) * w + y), u = getp((nx - 1) * w + ny);
            if (v != u) {
                if (ncmp[nx][ny]) { // fixed two new
                    path(x, y);
                    path(nx, ny);
                    num--;
                }
                else {
                    fromx[nx][ny] = x, fromy[nx][ny] = y;
                    ncmp[nx][ny] = ncmp[x][y];
                    q.push({nx, ny});
                }
                if (rnd() % 2)
                    p[v] = u;
                else
                    p[u] = v;
            }
        }
    }
    while (!q.empty())
        q.pop();
    for (int i = 1; i <= h; i++) {
        for (int j = 1; j <= w; j++) {
            if (c[i][j] == '#') {
                q.push({i, j});
            }
        }
    }
    while (!q.empty()) {
        int x, y; tie(x, y) = q.front(); q.pop();
        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k], ny = y + dy[k];
            if (!good(nx, ny))
                continue;
            if (!color[nx][ny]) {
                color[nx][ny] = 2;
                q.push({nx, ny});
            }
        }
    }
    print(1);
    cout << "\n";
    print(2);
}

int main() {
    ios::sync_with_stdio(NULL), cin.tie(0), cout.tie(0);
    cout.setf(ios::fixed), cout.precision(20);
    solve();
}

