  if( field[r][c] != '#' ) return;
  field[r][c] = '@';
  for(int i = 0; i < 4; ++i) {
    dfsfill(field, r + dr[i], c + dc[i]);
  }
}

int main() {
  scanf("%d %d", &h, &w);
  for(int i = 0; i < h; ++i) {
    scanf("%s", field_purple[i]);
  }
  for(int i = 0; i < h; ++i) {
    for(int j = 0; j < w; ++j) {
      field_red[i][j] = field_blue[i][j] = field_purple[i][j];
    }
  }

  for(int rd = 0; rd < 4; ++rd) {
    for(int cd = 0; cd < 4; ++cd) {
      if( rd == cd ) continue;
      // step 1 : init
      for(int i = 0; i < h; ++i) {
        for(int j = 0; j < w; ++j) {
          field_red[i][j] = field_blue[i][j] = field_purple[i][j];
        }
      }
      // step 2 : red_line
      for(int r = 0; r < h; ++r) {
        for(int c = 0; c < w; ++c) {
          if( field_red[r][c] == '#' ) {
            int nr = r, nc = c;
            dfsfill(field_red, nr, nc);
            nr += dr[rd]; nc += dc[rd];
            while( 0 <= nr and nr < h and 0 <= nc and nc < w ) {
              field_red[nr][nc] = '!';
              nr += dr[rd]; nc += dc[rd];
            }
          }
        }
      }
      // step 3 : try blue
      bool success = true;
      for(int r = 0; r < h; ++r) {
        for(int c = 0; c < w; ++c) {
          if( field_blue[r][c] == '#' ) {
            int nr = r, nc = c;
            dfsfill(field_red, nr, nc);
            nr += dr[cd]; nc += dc[cd];
            while( 0 <= nr and nr < h and 0 <= nc and nc < w ) {
              if( field_purple[nr][nc] != '#' and (field_red[nr][nc] == '!' or field_red[nr][nc] == '@') ) {
                success = false;
                goto label_1;
              }
              field_blue[nr][nc] = '!';
              nr += dr[cd]; nc += dc[cd];
            }
          }
        }
      }
    label_1:;
      if( success ) {
        fix(field_red, rd);
        fix(field_blue, cd);
        printans();
        goto label_2;
      }
    }
  }
 label_2:;

  return 0;
}

