    int cnt=0,num[h][w]={};
    int dx[4] = {1,0,-1,0}, dy[4] = {0,1,0,-1};
    UnionFind uni(h*w);
    for(int i=1;i<h-1;i++){
        for(int j=1;j<w-1;j++){
            num[i][j] = cnt;
            cnt++;
            for(int k=0;k<4;k++){
                int nh = i+dy[k],nw = j+dx[k];
                if(s[i][j]=='#' && s[nh][nw]=='#'){
                    uni.unite(i*w+j,nh*w+nw);
                }
            }
        }
    }
    for(int i=0;i<h;i++){
        for(int j=0;j<w;j++){
            a[i][j]='.';
            b[i][j]='.';
        }
    }
    for(int i=0;i<w;i++){
        a[0][i]='#';
        uni.unite(0,i);
    }
