            while (a != c || b != d)
            {
                t[a][b] = 1;
                if (a < c)
                    ++a;
                else
                if (a > c)
                    --a;
                else
                if (b < d)
                    ++b;
                else
                    --b;
            }
            t[a][b] = 1;
        }
    auto conected = [&](auto c)
    {
        memset(was,0,sizeof(was));
        for (int i = 1;i <= n;++i)
            for (int j = 1;j <= m;++j)
                if (c[i][j] == '#')
