                    was[i][j] = 1;
                    while (!Q.empty())
                    {
                        pair < int , int > node = Q.front();
                        Q.pop();
                        for (int k = 0;k < 4;++k)
                        {
                            pair < int , int > Next = {node.x + dx[k],node.y + dy[k]};
                            if (ok(Next.x,Next.y) && c[Next.x][Next.y] == '#' && !was[Next.x][Next.y])
                                was[Next.x][Next.y] = 1,Q.push(Next);
                        }
                    }
                    break;
                }
        for (int i = 1;i <= n;++i)
            for (int j = 1;j <= m;++j)
                if (c[i][j] == '#' && !was[i][j])
                    return 0;
        return 1;
    };
    for (int i = 1;i <= n;++i)
        for (int j = 1;j <= m;++j)
            a[i][j] = (c[i][j] == '#' || t[i][j] ? '#' : '.');
    assert(conected(a));
