queue<pii> Q, Q1;

void check(int x, int y) {
	if (tab[x][y] == 1 && !used2[x][y]) {
		used2[x][y] = true;
		Q.push(pii(x,y));
		Q1.push(pii(x,y));
	}
}

void roz(int x, int y) {
	Q1.push(pii(x,y));
	used2[x][y] = true;
	while (!Q1.empty()) {
		pii p = Q1.front(); Q1.pop();
		int x = p.st; int y = p.nd;
		check(x + 1, y);
		check(x - 1, y);
		check(x, y + 1);
		check(x, y - 1);
	}
}

void check2(int x, int y, int a, int b) {
	if (!used[x][y] && x >= 1 && y >= 1 && x <= n && y <= m) {
		//cout<<"Tutaj\n";
		Q.push(pii(x,y));
		prev1[x][y] = pii(a, b);
	}
}

void BFS(pii p) {
	int x = p.st; int y = p.nd;
	Q.push(p);
	while (!Q.empty()) {
		pii p = Q.front(); Q.pop();
		//cout<<p.st<<" "<<p.nd<<endl;
		x = p.st; y = p.nd;
		if (tab[x][y] == 1 && !used2[x][y])
			roz(x, y);
		if (!used[x][y]) {
			//cout<<"Wchodze\n";
			used[x][y] = true;
			check2(x + 1, y, x, y);
			check2(x - 1, y, x, y);
			check2(x, y + 1, x, y);
			check2(x, y - 1, x, y);
		}
	}
}

