#include <bits/stdc++.h>

using namespace std;

const int NM_MAX = 502;

int n, m;

bool ma[NM_MAX][NM_MAX];

int cca[NM_MAX * NM_MAX], ccb[NM_MAX * NM_MAX];

int cc[NM_MAX][NM_MAX];
int cntcc;

bool inside (int a, int b)
{
    return (1 <= a && a <= n && 1 <= b && b <= m);
}

int dl[] = {-1, 0, 1, 0}, dc[] = {0, 1, 0, -1};

void dfs (int a, int b)
{
    cc[a][b] = cntcc;
    for(int d = 0; d < 4; d++)
    {
        int a1 = a + dl[d], b1 = b + dc[d];
        if(inside(a1, b1) && ma[a1][b1] == true && cc[a1][b1] == 0)
            dfs(a1, b1);
    }
}

bool blocked[NM_MAX][NM_MAX];

int parenta[NM_MAX][NM_MAX], parentb[NM_MAX][NM_MAX];

queue <pair <int, int> > q;

bool visited[NM_MAX][NM_MAX];

int fa, fb;

vector <pair <int, int> > v;

void bfs(int a, int b, bool ok)
{
    while(!q.empty())
        q.pop();
    while(!v.empty())
    {
        visited[v.back().first][v.back().second] = false;
        v.pop_back();
    }
    visited[a][b] = true;
    v.push_back(make_pair(a, b));
    q.push(make_pair(a, b));
    while(!q.empty())
    {
        pair <int, int> f = q.front();
        q.pop();
        int ccf = cc[f.first][f.second];
        if(ccf != 0 && cc[a][b] < ccf)
        {
            fa = f.first;
            fb = f.second;
            return;
        }
        for(int d = 0; d < 4; d++)
        {
            int a1 = f.first + dl[d], b1 = f.second + dc[d];
            if(inside(a1, b1) && (blocked[a1][b1] == false || ok == true) && visited[a1][b1] == false)
            {
                visited[a1][b1] = true;
                v.push_back(make_pair(a1, b1));
                parenta[a1][b1] = f.first;
                parentb[a1][b1] = f.second;
                q.push(make_pair(a1, b1));
            }
        }
    }
}

bool ans1[NM_MAX][NM_MAX], ans2[NM_MAX][NM_MAX];

