            if(ma[i][j] == true)
            {
                cntcc++;
                cca[cntcc] = i;
                ccb[cntcc] = j;
                dfs(i, j);
            }
    for(int i = 1; i < cntcc; i++)
    {
        bfs(cca[i], ccb[i], true);
        while(cc[fa][fb] != i)
        {
            ans1[fa][fb] = true;
            if(ma[fa][fb] == false)
                blocked[fa][fb] = true;
            int fa1 = parenta[fa][fb];
            int fb1 = parentb[fa][fb];
            fa = fa1;
            fb = fb1;
        }
    }
    for(int i = 1; i < cntcc; i++)
    {
        bfs(cca[i], ccb[i], false);
        while(cc[fa][fb] != i)
        {
            ans2[fa][fb] = true;
            int fa1 = parenta[fa][fb];
            int fb1 = parentb[fa][fb];
            fa = fa1;
            fb = fb1;
        }
    }
    for(int i = 1; i <= n; i++, cout << "\n")
        for(int j = 1; j <= m; j++)
