using namespace std;

int main() {

    //ifstream cin("testC.in");

    int n, m; cin >> n >> m;
    vector<string> V(n);
    for(int i = 0; i < n; ++i)
        cin >> V[i];

    vector<string> A(n), B(n);
    A = V, B = V;

    int dx[4] = {0, 0, -1, 1};
    int dy[4] = {1, -1, 0, 0};

    auto distToEdge = [&] (pair<int, int> A, int dir) {
        if(dx[dir] != 0) {
            if(dx[dir] < 0)
                return A.first;
            return n - 1 - A.first;
        } else {
            if(dy[dir] < 0)
                return A.second;
            return m - 1 - A.second;
        }
    };

    for(int i = 0; i < n; ++i) {
        for(int j = 0; j < m; ++j) {
            if(V[i][j] != '#')
                continue;
            int where = -1, minn = 5000;

            for(int d = 0; d < 4; ++d) {
                if(distToEdge({i, j}, d) < minn) {
                    minn = distToEdge({i, j}, d);
                    where = d;
                }
            }

            int x = i, y = j;
            while(x >= 0 && x < n && y >= 0 && y < m) {
                if(V[x][y] != '#')
                    A[x][y] = 'A';
                x += dx[where];
                y += dy[where];
            }
        }
    }

    for(int i = 0; i < n; ++i)
        for(int j = 0; j < m; ++j)
            if(i == 0 || i == n - 1 || j == 0 || j == m - 1)
                A[i][j] = 'A';

    for(int i = 0; i < n; ++i)
        for(int j = 0; j < m; ++j)
            if(B[i][j] == '.' && A[i][j] == '.')
                B[i][j] = '#';

    for(int i = 0; i < n; ++i)
        for(int j = 0; j < m; ++j)
            if(A[i][j] == 'A')
                A[i][j] = '#';

    vector<string> test = vector<string> (n, string(m, '.'));
    for(int i = 0; i < n; ++i)
        for(int j = 0; j < m; ++j)
            if(A[i][j] == '#' && B[i][j] == '#')
                test[i][j] = '#';

    assert(test == V);

    for(auto temp : A)
        cout << temp << "\n";

    cout << "\n";
    for(auto temp : B)
        cout << temp << "\n";
}

