int h[505]={};
bool b[505][505]={};
void dfs(int x, int y){
	chmax( h[x], y );
	ans[y][x] = '#';
	b[y][x] = true;
	rep(i,4){
		int nx = x + vx[i];
		int ny = y + vy[i];
		if( b[ny][nx] ) continue;
		if( mp[ny][nx] == '#' ){
			dfs( nx, ny );
		}
	}
}

