const int N = 505;

string s[N], r[N], b[N];
int L[N], R[N], U[N], D[N];

int main() {
  int n,m;
  S2(n,m);
  rep(i,0,n) {
    cin >> s[i];
    r[i] = b[i] = s[i];
  }

  rep(i,0,n) {
    L[i] = -1;
    R[i] = m;
  }

  rep(i,0,m) {
    U[i] = -1;
    D[i] = n;
  }
  rep(i,1,n-1) rep(j,1,m-1) if(s[i][j] == '#') {
    if(i <= n-i && i <= j && i <= m-j) U[j] = max(U[j], i);
    else if(n-i <= i && n-i <= j && n-j <= m-j) D[j] = min(D[j], i);
    else if(j <= i && j <= n-i && j <= m-j) L[i] = max(L[j], j);
    else R[i] = min(R[i], j);
  }

  rep(i,0,n) rep(j,0,m) {
    if(i == 0 || i == n-1 || j == 0 || j == m-1) {
      r[i][j] = '#';
      continue;
    }
    if(i > U[j] && i < D[j] && j > L[i] && j < R[i]) {
      r[i][j] = '.';
    } else {
      r[i][j] = '#';
    }
