int H, W;
char A[505][505];
char ans1[505][505], ans2[505][505];

int main(){
  scanf("%d%d", &H, &W);
  for (int i = 0; i < H; i++) {
    scanf("%s", A + i);
  }

  int nowi = 1, nowj = 1;
  while(true){
    for (int j = nowj; j < W - nowj; j++){
      ans1[nowi][j] = '#';
      ans1[H - 1 - nowi][j] = '#';
    }
    if (nowj + 2 >= W - nowj) break;

    for (int i = nowi; i < H - nowi; i++){
      ans1[i][W - nowj - 1] = '#';
    }
    if (nowi + 2 >= H - nowi) break;
    for (int i = nowi + 2; i < H - nowi; i++){
      ans1[i][nowj] = '#';
    }
