    nowi += 2; nowj += 2;
  }

  for (int i = 0; i < H; i++){
    for (int j = 0; j < W; j++){
      if (A[i][j] == '#'){
        ans1[i][j] = '#'; ans2[i][j] = '#';
        continue;
      }
      if (ans1[i][j] == '#'){
        ans2[i][j] = '.';
      }else{
        ans1[i][j] = '.'; ans2[i][j] = '#';
