#define x first
#define y second
#define mkp make_pair
#define pb push_back
typedef pair<int, int> pii;
const int MAXN = 510;
int dr[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
int n, m, pn, d[MAXN][MAXN], l, r;
char s[MAXN][MAXN], A[MAXN][MAXN], B[MAXN][MAXN];
bool vis[MAXN][MAXN];
vector<pii> p[260*250];
pii q[MAXN*MAXN], pre[MAXN][MAXN];

void dfs(int x, int y) {
	p[pn].pb(mkp(x, y));
	s[x][y] = '.';
	for(int i = 0; i < 4; i++) {
		int nx = x+dr[i][0], ny = y+dr[i][1];
		if(s[nx][ny] == '#') dfs(nx, ny);
	}
}

inline void BFS() {
	while(l < r) {
		pii u = q[++l];
		for(int i = 0; i < 4; i++) {
			int nx = u.x+dr[i][0], ny = u.y+dr[i][1];
			if(nx < 1 || ny < 1 || nx > n || ny > m) continue;
			if(vis[nx][ny]) continue;
			//printf("%d %d ->%d %d\n", u.x, u.y, nx, ny);
			vis[nx][ny] = true;
			d[nx][ny] = d[u.x][u.y]+1;
			q[++r] = mkp(nx, ny);
			pre[nx][ny] = u;
		}
	}
}

int main() {
	cin >> n >> m;

	for(int i = 1; i <= n; i++) {
		scanf("%s", s[i]+1);
		for(int j = 1; j <= m; j++)
			A[i][j] = B[i][j] = s[i][j];
	}
	for(int i = 1; i <= n; i++) {
		for(int j = 1; j <= m; j++) 
			if(s[i][j] == '#') {
				pn++;
				dfs(i, j);
			}
	}
	/*for(int i = 1; i <= pn; i++) {
		for(int j = 0; j < (int)p[i].size(); j++)
			printf("(%d, %d) ", p[i][j].x, p[i][j].y);
		printf("\n");
	}*/
	for(int i = 0; i < (int)p[1].size(); i++) {
		q[++r] = p[1][i];
		d[p[1][i].x][p[1][i].y] = 0;
		vis[p[1][i].x][p[1][i].y] = true;
	}

	BFS();

	memset(vis, false, sizeof(vis));
	for(int i = 2; i <= pn; i++) {
		pii u = p[i][0];
		for(int j = 1; j < (int)p[i].size(); j++) {
			pii x = p[i][j];
			if(d[x.x][x.y] < d[u.x][u.y]) u = x;
		}
		u = pre[u.x][u.y];
		while(d[u.x][u.y]) {
			if(B[u.x][u.y] != '#') vis[u.x][u.y] = true;
			A[u.x][u.y] = '#';
			u = pre[u.x][u.y];
		}
	}

	l = r = 0;
	for(int i = 0; i < (int)p[1].size(); i++) {
		q[++r] = p[1][i];
		d[p[1][i].x][p[1][i].y] = 0;
		vis[p[1][i].x][p[1][i].y] = true;
	}

	for(int i = 1; i <= n; i++)
		for(int j = 1; j <= m; j++)
			pre[i][j].x = pre[i][j].y = 0;
	//printf("%d\n", vis[4][2]);
	BFS();
	return 0;
	//printf("(%d, %d)\n", pre[4][2].x, pre[4][2].y);
	for(int i = 2; i <= pn; i++) {
		pii u = p[i][0];
		for(int j = 1; j < (int)p[i].size(); j++) {
			pii x = p[i][j];
			if(d[x.x][x.y] < d[u.x][u.y]) u = x;
		}
		u = pre[u.x][u.y];
		while(d[u.x][u.y]) {
			B[u.x][u.y] = '#';
			u = pre[u.x][u.y];
		}
	}

	for(int i = 1; i <= n; i++) {
		for(int j = 1; j <= m; j++) putchar(A[i][j]);
		printf("\n");
	}
	printf("\n");
	for(int i = 1; i <= n; i++) {
		for(int j = 1; j <= m; j++) putchar(B[i][j]);
		printf("\n");
	}
	return 0;
}

