  for(i=1;i<h;i++)   c[i][0]='#';
  for(j=0;j<w-1;j++) c[h-1][j]='#';

  typedef pair<int,int> P;
  queue<P> q;
  P p;
  int ax[]={1,-1,0,0};
  int ay[]={0,0,1,-1};
