    if(p.first<0||p.first>=h||p.second<0||p.second>=w) continue;
    if(uc[p.first][p.second]) continue;
    uc[p.first][p.second]=true;
    if(!ub[p.first][p.second]) c[p.first][p.second]='#'; 
    for(k=0;k<4;k++) q.push(P(p.first+ay[k],p.second+ax[k]));
  }


  for(i=0;i<h;i++){
    for(j=0;j<w;j++) cout << b[i][j];
    cout << endl;
  }
  cout << endl;
  for(i=0;i<h;i++){
    for(j=0;j<w;j++) cout << c[i][j];
    cout << endl;
  }
  return 0;
}

