void dfs(int x, int y, vector<vector<char> >& v, vector<vector<char> >& r, vector<vector<char> >& b)
{
  if (x < 0 || y < 0 || x == v.size() || y == v[0].size()) {
    return;
  }
  if (b[x][y] == '@') {
    return;
  }
  if (r[x][y] == '#' && v[x][y] == '.') {
    return;
  }
  b[x][y] = '@';
  dfs(x - 1, y, v, r, b);
  dfs(x + 1, y, v, r, b);
  dfs(x, y - 1, v, r, b);
  dfs(x, y + 1, v, r, b);
}

void dfs0(int x, int y, vector<vector<char> >& v, vector<pair<int, int> >& q, vector<vector<char> >& vis)
{
  if (x < 0 || y < 0 || x == v.size() || y == v[0].size()) {
    return;
  }
  if (v[x][y] != '#') {
    return;
  }
  if (vis[x][y] == 2) {
    return;
  }
  if (!vis[x][y]) {
    q.push_back({x, y});
  }
  vis[x][y] = 2;
  dfs0(x - 1, y, v, q, vis);
  dfs0(x + 1, y, v, q, vis);
  dfs0(x, y - 1, v, q, vis);
  dfs0(x, y + 1, v, q, vis);
}

