        pr[x][y - 1] = {x, y};
      }
      if (y < m - 1 && !vis[x][y + 1]) {
        vis[x][y + 1] = 1;
        q.push_back({x, y + 1});
        pr[x][y + 1] = {x, y};
      }
    }

