string hantei() {
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (x[i][j] != '#') {
				if (R[i][j] == '#' && B[i][j] == '#') {
					return "Wrong Answer";
				}
			}
			if (x[i][j] == '#') {
				if (R[i][j] != '#' || B[i][j] != '#') {
