		}
	}


	for(int i = 0; i < H; i++) {
		for(int j = 0; j < W; j++) {
			char c;
			cin >> c;
			if(c == '#') {
				r[i][j] = b[i][j] = '#';
			}
		}
	}

	for(int i = 0; i < H; i++) {
		for(int j = 0; j < W; j++) {
			cout << r[i][j];
		}
		cout << endl;
	}
	for(int i = 0; i < H; i++) {
		for(int j = 0; j < W; j++) {
			cout << b[i][j];
		}
		cout << endl;
	}
}

