VS solve( const VS &board, const int oe )
{
	const int H = SZ( board ), W = SZ( board[0] );
	VS res( H, string( W, '.' ) );

	REP( i, H )
	{
		REP( j, W )
		{
			if ( j == ( oe ? W - 1 : 0 ) || ( i % 2 == oe && j != ( oe ? 0 : W - 1 ) ) || board[i][j] == '#' )
			{
				res[i][j] = '#';
			}
		}
	}

	return move( res );
}

