{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	int H, W;
	cin >> H >> W;

	VS board( H );
	cin >> board;

	const VS res1 = solve( board, 0 ), res2 = solve( board, 1 );

	copy( ALL( res1 ), ostream_iterator< string >( cout, "\n" ) );
	cout << '\n';
	copy( ALL( res2 ), ostream_iterator< string >( cout, "\n" ) );
	cout << flush;

	return 0;
}

