int vis[505][505],n,m,cnt[505][505],k=0,dx[]={0,-1,0,1},dy[]={1,0,-1,0} ;
vector<pii>v[250000] ; set<pii>st ;
string s[600] ;
void dfs(int a , int b)
{
    if(vis[a][b]) return ;
    vis[a][b]=1 ; cnt[a][b]=k ;
    v[k].push_back({a,b}) ; st.insert({a,b}) ;
    for(int i = 0 ; i < 4 ; i++)
    {
        int x=a+dx[i] , y=b+dy[i] ;
        if(x>=0 && x<n && y>=0 && y<m && s[x][y]=='#') dfs(x,y) ;
    }
}
void serch(int x , int y , int a , int b)
{
    int d=abs(x-a),ic=1 ;
    if(x>a) ic=-1 ;
    for(int i = x ; i != a ; i+=ic) vis[i][y]=1 ;
    d=abs(y-b) , ic=1 ;
    if(y>b) ic=-1 ;
    for(int i = y ; i != b ; i+=ic) vis[a][i]=1 ;
}
void ndfs(int x , int y , int fx , int fy)
{
    if(vis[x][y])
    {
        if(s[x][y]!='#') return ;
    }
    if(!vis[x][y]) vis[x][y]=2 ;
    for(int i = 0 ; i < 4 ; i++)
    {
        int a=x+dx[i],b=y+dy[i] ;
        if(a>=0 && a<n && b>=0 && b<m && a!=fx && b!=fy && (!vis[a][b] || s[a][b]=='#')) ndfs(a,b,x,y) ;
    }
}
