            {
                k++ ;
                dfs(i,j) ;
            }
        }
    }
    for(int i = 1 ; i <= k-1 ; i++)
    {
        int x=v[i][0].F,y=v[i][0].S,a=v[i+1][0].F,b=v[i+1][0].S ;
        serch(x,y,a,b) ;
    }
