using namespace std;

inline int read(){
	int a = 0;
	char c = getchar();
	bool f = 0;
	while(!isdigit(c)){
		if(c == '-')
			f = 1;
		c = getchar();
	}
	while(isdigit(c)){
		a = (a << 3) + (a << 1) + (c ^ '0');
		c = getchar();
	}
	return f ? -a : a;
}

const int dir[4][2] = {0,1,0,-1,1,0,-1,0};
bool vis[520][520];
char tial[520][520];
int H , W;
queue < P > q;

inline char getc(){
	char c = getchar();
	while(c != '.' && c != '#')
		c = getchar();
	return c;
}

void bfs(int x , int y){
	q.push(P(x , y));
	vis[x][y] = 1;
	while(!q.empty()){
		P now = q.front();
		q.pop();
		for(int i = 0 ; i < 4 ; ++i)
			if(tial[now.first + dir[i][0]][now.second + dir[i][1]] == '#' && !vis[now.first + dir[i][0]][now.second + dir[i][1]]){
				vis[now.first + dir[i][0]][now.second + dir[i][1]] = 1;
				q.push(P(now.first + dir[i][0] , now.second + dir[i][1]));
			}
	}
}

int main(){
	H = read();
	W = read();
	for(int i = 1 ; i <= H ; ++i)
		for(int j = 1 ; j <= W ; ++j)
			tial[i][j] = getc();
	for(int i = 1 ; i <= W ; ++i)
		vis[H][i] = 1;
	for(int i = 2 ; i < W ; ++i)
		for(int j = H - 1 ; j > 1 ; --j)
			if(!vis[j][i] && tial[j][i] == '#'){
				bfs(j , i);
				int x = j , y = i;
				while(!vis[x][y - 1] && !vis[x + 1][y])
					vis[++x][y] = 1;
			}
	for(int i = 1 ; i <= H ; ++i){
		for(int j = 1 ; j <= W ; ++j)
			putchar(vis[i][j] ? '#' : '.');
		putchar('\n');
	}
	putchar('\n');
	for(int i = 1 ; i <= H ; ++i){
		for(int j = 1 ; j <= W ; ++j)
			putchar(vis[i][j] && tial[i][j] == '.' ? '.' : '#');
		putchar('\n');
	}
	return 0;
}

