	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) { cin >> x[i][j]; R[i][j] = '.'; B[i][j] = '.'; }
	}
	int counts = 0;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (used[i][j] == true || x[i][j] == '.')continue;
			queue<pair<int, int>>Q; Q.push(make_pair(i, j));
			vector<pair<int, int>>G; G.push_back(make_pair(i, j));
			int dx[4] = { 0,1,0,-1 }, dy[4] = { 1,0,-1,0 };
			while (!Q.empty()) {
				int a1 = Q.front().first, a2 = Q.front().second; Q.pop();
				for (int k = 0; k < 4; k++) {
					int cx = a1 + dx[k], cy = a2 + dy[k];
					if (x[cx][cy] == '.' || used[cx][cy] == true)continue;
					G.push_back(make_pair(cx, cy)); Q.push(make_pair(cx, cy)); used[cx][cy] = true;
				}
			}
			vec2[counts] = G; counts++;
		}
	}
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (i == 0 || i == H - 1 || j == 0 || j == W - 1)R[i][j] = '#';
