vector < pair < int, int > > steps = { {0, 1}, {1, 0}, {-1, 0}, {0, -1}};

void bfs_comp (int x, int y) {
	queue < pair < int , int > > q;
	q.push({x,y});
	used[x][y] = 1;
	while (q.size() != 0) {
		int vx = q.front().first;
		int vy = q.front().second;
		//cout << vx << " " << vy << endl;
		for (auto p: steps) {
			int nx = vx + p.first;
			int ny = vy + p.second;
			if (nx >= 0 && nx < n && ny >= 0 && ny < m && used[nx][ny] == 0 && gr[nx][ny] == '#') {
				used[nx][ny] = 1;
				q.push({nx,ny});
			}
		}
		q.pop();
	}
	return;
}

void bfs_find(int x, int y) {
	bfs_comp(x, y);
	queue < pair < int , int > > q;
	q.push({x,y});
	used[x][y] = 1;
	while (q.size() != 0) {
		int vx = q.front().first;
		int vy = q.front().second;
		//cout << vx << " " << vy << endl;
		random_shuffle(steps.begin(),steps.end());
		for (auto p: steps) {
			int nx = vx + p.first;
			int ny = vy + p.second;
			if (nx >= 0 && nx < n && ny >= 0 && ny < m && used[nx][ny] == 0 && gr[nx][ny] == '.') {
				used[nx][ny] = 1;
				pr[nx][ny] = {vx, vy};
				q.push({nx,ny});
			}
			if (nx >= 0 && nx < n && ny >= 0 && ny < m && used[nx][ny] == 0 && gr[nx][ny] == '#') {
				int cx = vx, cy = vy;
				while (gr[cx][cy] != '#') {
					//cout << cx << " " << cy << endl;
					blue[cx][cy] = '#';
					int tx = cx;
					cx = pr[tx][cy].first;
					cy = pr[tx][cy].second;
				}
				bfs_comp(nx, ny);
			}
		}
		q.pop();
	}
}

void bfs_find_red(int x, int y) {
	queue < pair < int , int > > q;
	q.push({x,y});
	used[x][y] = 1;
	while (q.size() != 0) {
		int vx = q.front().first;
		int vy = q.front().second;
		//cout << vx << " " << vy << endl;
		red[vx][vy] = '#';
		for (auto p: steps) {
			int nx = vx + p.first;
			int ny = vy + p.second;
			if (nx >= 0 && nx < n && ny >= 0 && ny < m && used[nx][ny] == 0) {
				used[nx][ny] = 1;
				q.push({nx,ny});
			}
		}
		q.pop();
	}
}

