const int dx[4] = {0, 1, 0, -1};
const int dy[4] = {1, 0, -1, 0};
void dfs(int x, int y) {
	vis[x][y] = 1;
	if(y < miny[cccnt]) miny[cccnt] = y, minx[cccnt] = x;
	for(int i = 0; i < 4; i++) {
		int tx = x + dx[i], ty = y + dy[i];
		if(tx >= 1 && ty >= 1 && tx <= H && ty <= W && G[tx][ty] && !vis[tx][ty])
