            while (y < v[i].second) path.pb(mp(x,++y));
            while (y > v[i].second) path.pb(mp(x,--y));
            for (j = 0; j < path.size(); j++) {
                if (find(v[i].first*W+v[i].second) == find(v[i-1].first*W+v[i-1].second)) break;
                ans2[path[j].first][path[j].second] = 1;
                int x = path[j].first,y = path[j].second;
                if ((x > 0) && ans2[x-1][y]) merge(x*W+y,(x-1)*W+y);
                if ((x < W-1) && ans2[x+1][y]) merge(x*W+y,(x+1)*W+y);
                if ((y > 0) && ans2[x][y-1]) merge(x*W+y,x*W+y-1);
                if ((y < H-1) && ans2[x][y+1]) merge(x*W+y,x*W+y+1);
            }
        }
