int maxn = 250005;

vvi dsu(2, vi(maxn));

int get(int i, int j) {
    if (dsu[j][i] != i) dsu[j][i] = get(dsu[j][i], j);
    return dsu[j][i];
}

void edge(int i, int j, int i0) {
    i = get(i, i0), j = get(j, i0);
    dsu[i0][j] = i;
}

void solve() {
    int n, m;
    cin >> n >> m;
    forn(i, n) {
        forn(j, m) dsu[0][i * m + j] = dsu[1][i * m + j] = i * m + j;
    }
    vs a(n);
    forn(i, n) cin >> a[i];
    vvi comp(n, vi(m, -1));
    int C = 0;
    vvb used(n, vb(m));
    forn(i, n) {
        forn(j, m) {
            if (a[i][j] == '.') continue;
            queue<pii> q;
            q.push({i, j});
            used[i][j] = 1;
            comp[i][j] = C;
            while (!q.empty()) {
                int x = q.front().F, y = q.front().S;
                q.pop();
                if (x > 0 && !used[x - 1][y] && a[x - 1][y] == '#') {
                    used[x - 1][y] = 1;
                    comp[x - 1][y] = C;
                    q.push({x - 1, y});
                }
                if (x + 1 < n && !used[x + 1][y] && a[x + 1][y] == '#') {
                    used[x + 1][y] = 1;
                    comp[x + 1][y] = C;
                    q.push({x + 1, y});
                }
                if (y > 0 && !used[x][y - 1] && a[x][y - 1] == '#') {
                    used[x][y - 1] = 1;
                    comp[x][y - 1] = C;
                    q.push({x, y - 1});
                }
                if (y + 1 < m && !used[x][y + 1] && a[x][y + 1] == '#') {
                    used[x][y + 1] = 1;
                    comp[x][y + 1] = C;
                    q.push({x, y + 1});
                }
            }
            C++;
        }
    }
    vvi I(C);
    forn(i, n) {
        forn(j, m) {
            if (a[i][j] == '#') I[comp[i][j]].pb(i * m + j);
        }
    }
    forn(i, C) {
        forn1(j, I[i].size()) {
            edge(I[i][j - 1], I[i][j], 0);
            edge(I[i][j - 1], I[i][j], 1);
        }
    }
    vs r(n), b(n);
    forn(i, n) {
        forn(j, m) {
            r[i] += ".";
            b[i] += ".";
            if (a[i][j] == '#') r[i][j] = b[i][j] = '#';
        }
    }
    queue<pii> q;
    vvb vis(n, vb(m));
    forn(i, n) {
        forn(j, m) {
            if (a[i][j] == '#') {
                q.push({i, j});
                vis[i][j] = 1;
            }
        }
    }
    while (!q.empty()) {
        int x = q.front().F, y = q.front().S;
        q.pop();
        vi ir, ib;
        for2(dx, -1, 1) {
            for2(dy, -1, 1) {
                if (dx * dy != 0 || (dx == 0 && dy == 0)) continue;
                int x1 = x + dx, y1 = y + dy;
                if (x1 >= 0 && y1 >= 0 && x1 < n && y1 < m) {
                    if (r[x1][y1] == '#') ir.pb(get(x1 * m + y1, 0));
                    if (b[x1][y1] == '#') ib.pb(get(x1 * m + y1, 1));
                }
            }
        }
        set<int> sr, sb;
        for (int i : ir) sr.insert(i);
        for (int i : ib) sb.insert(i);
        if (!ir.empty() && ir.size() == sr.size() && x > 0 && y > 0 && x + 1 < n && y + 1 < m) {
            r[x][y] = '#';
            for (int i : ir) edge(x * m + y, i, 0);
        } else if (!ib.empty() && ib.size() == sb.size()) {
            b[x][y] = '#';
            for (int i : ib) edge(x * m + y, i, 1);
        }
        if (x > 0 && !vis[x - 1][y]) {
            vis[x - 1][y] = 1;
            q.push({x - 1, y});
        }
        if (y > 0 && !vis[x][y - 1]) {
            vis[x][y - 1] = 1;
            q.push({x, y - 1});
        }
        if (x + 1 < n && !vis[x + 1][y]) {
            vis[x + 1][y] = 1;
            q.push({x + 1, y});
        }
        if (y + 1 < m && !vis[x][y + 1]) {
            vis[x][y + 1] = 1;
            q.push({x, y + 1});
        }
    }
    forn(i, n) cout << r[i] << '\n';
    cout << '\n';
    forn(i, n) cout << b[i] << '\n';
}

