vector<int> ans;
vector<UnionFind> uf;

// i_uf： UnionFindのid．これを使う
// qに含まれるクエリに対して，範囲[l+1 r]で二分探索
void dfs(int i_uf, int l , int r, vector<int> q) {

    //cout<<l<<","<<r<<endl;

    // 解を発見
    if(r-l <= 1) {
        for(int i=l+1; i<=r; i++) uf[i_uf].unite(edge[i].first, edge[i].second);

        for(int i: q) ans[i] = r;
        return;
    }

    int m = (l+r)/2;
    for(int i=l+1;i<=m;i++) uf[i_uf].unite(edge[i].first, edge[i].second);

    vector<int> L,R;
    for(int i : q){
        ll x = qs[i].x;
        ll y = qs[i].y;
        ll z = qs[i].z;
        if( (uf[i_uf].same(x,y) && uf[i_uf].size(x)>=z)
                || (!uf[i_uf].same(x,y) && uf[i_uf].size(x)+uf[i_uf].size(y)>=z)){
            L.push_back(i);
        }else{
            R.push_back(i);
        }
    }
    for(int i=m;i<=r;i++) uf[i_uf].unite(edge[i].first, edge[i].second);

    dfs(i_uf+1, l, m, L);
    dfs(i_uf+1, m, r, R);
}

