inline void bfs(int x, int y) {
	l = r = 0;
	s[x][y] = '.';
	q[++r] = mkp(x, y);
	while(l < r) {
		pii u = q[++l];
		p[pn].pb(u);
		for(int i = 0; i < 4; i++) {
			int nx = u.x+dr[i][0], ny = u.y+dr[i][1];
			if(s[nx][ny] != '#') continue;
			s[nx][ny] = '.';
			q[++r] = mkp(nx, ny);
		}
	}
}

inline void BFS() {
	while(l < r) {
		pii u = q[++l];
		for(int i = 0; i < 4; i++) {
			int nx = u.x+dr[i][0], ny = u.y+dr[i][1];
			if(nx < 1 || ny < 1 || nx > n || ny > m) continue;
			if(vis[nx][ny]) continue;
			//printf("%d %d ->%d %d\n", u.x, u.y, nx, ny);
			vis[nx][ny] = true;
			d[nx][ny] = d[u.x][u.y]+1;
			q[++r] = mkp(nx, ny);
			pre[nx][ny] = u;
		}
	}
}

