const int N = 505;

int n, m;
char s[N][N], b[N][N], c[N][N];

vector<vector<pair<int, int>>> sets;
int where[N][N];
set<int> existSets;

void unite(int x, int y) {
	//cerr << x << " unite " << y << endl;
	if (x == y) return;
	if (sets[x].size() > sets[y].size()) {
		swap(x, y);
	}
	for (auto p : sets[x]) {
		where[p.first][p.second] = y;
		sets[y].push_back(p);
	}
	sets[x].clear();
	existSets.erase(x);
}

void uniteCells(const pair<int, int> & a, const pair<int, int> & b) {
	if (where[a.first][a.second] == -1) {
		where[a.first][a.second] = (int)sets.size();
		existSets.insert((int)sets.size());
		sets.push_back({a});
	}
	if (where[b.first][b.second] == -1) {
		where[b.first][b.second] = (int)sets.size();
		existSets.insert((int)sets.size());
		sets.push_back({b});
	}
	unite(where[a.first][a.second], where[b.first][b.second]);
}

void processSeq(const vector<pair<int, int>> & seq) {
	//cerr << seq << endl;
	auto prv = seq[0];
	for (auto p : seq) {
		uniteCells(prv, p);
		prv = p;
	}
}

void goFromTo(int x, int y, int xx, int yy) {
	static vector<pair<int, int>> seq;
	seq.resize(0);
	while (x < xx) {
		seq.push_back({x, y});
		x++;
	}
	while (x > xx) {
		seq.push_back({x, y});
		x--;
	}
	while (y < yy) {
		seq.push_back({x, y});
		y++;
	}
	while (y > yy) {
		seq.push_back({x, y});
		y--;
	}
	seq.push_back({x, y});
	processSeq(seq);
}

