	scanf("%d%d", &n, &m);

	for (int i = 0; i < n; i++) {
		scanf("%s", s[i]);
		fill(b[i], b[i] + m, '.');
		fill(c[i], c[i] + m, '.');
	}

	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			if (s[i][j] == '#') {
				where[i][j] = (int)sets.size();
				existSets.insert((int)sets.size());
				sets.push_back({{i, j}});
			}
		}
	}


	while (existSets.size() > 1) {
		int x = *existSets.begin();
		int y = *(++existSets.begin());
		goFromTo(sets[x].begin()->first, sets[x].begin()->second, sets[y].begin()->first, sets[y].begin()->second);
	}

	int cur = *existSets.begin();

	for (auto p : sets[cur]) {
		b[p.first][p.second] = '#';
	}

	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
