            A[i][j] = inp[j - 1] == '1' ? 3 : 0;
        }
    }
}

void solve()
{
    for (int i = 1; i <= N; ++i) {
        A[i][1] = 1; A[i][M] = 2;
    }
    for (int i = 2; i < M; ++i) {
        A[1][i] = 1; A[M][i] = 2;
    }
    for (int i = 2; i < N; ++i) {
        for (int j = 2; j < M; ++j) {
            A[i][j] |= i & 1 ? 1 : 2;
        }
    }
    print(A);
}

