const int NMAX = 500;

int n, m;

bool red[NMAX+5][NMAX+5];
bool blue[NMAX+5][NMAX+5];

bool isRed(int r, int c){
	if(r == 0) return true;
	if(r == n-1) return false;
	return (c%2 == 0);
}

int main(){
	scanf("%d%d", &n, &m);

	char s[m+5];

	for (int i = 0; i < n; i++){
		scanf("%s", s);
		for (int j = 0; j < m; j++){
			if(s[j] == '#'){
				red[i][j] = true;
				blue[i][j] = true;
			}else if(isRed(i, j)){
				red[i][j] = true;
			}else{
				blue[i][j] = true;
			}
		}
	}

	for (int i = 0; i < n; i++){
		for (int j = 0; j < m; j++){
			if(red[i][j]) printf("#");
			else printf(".");
		}
		printf("\n");
	}

	printf("\n");

	for (int i = 0; i < n; i++){
		for (int j = 0; j < m; j++){
			if(blue[i][j]) printf("#");
			else printf(".");
		}
		printf("\n");
	}
}

