void rec(int xa, int ya, int xb, int yb, int col){
	if(xa == xb || xa + 1 == xb || ya == yb || ya + 1 == yb)
		return;
	for(int i = ya + 1; i < yb; ++i)
		if(c[xa + 1][i] == '#')
			a[col][xa + 1][i] = 1;
	for(int i = xa + 1; i < xb; ++i)
		if(c[i][ya + 1] == '#')
			a[col][i][ya + 1] = 1;
	for(int i = ya + 1; i < yb; ++i)
		if(c[xb - 1][i] == '#')
			a[3 - col][xb - 1][i] = 1;
	for(int i = xa + 1; i < xb; ++i)
		if(c[i][yb - 1] == '#')
			a[3 - col][i][yb - 1] = 1;
	if(xa + 2 == xb || ya + 2 == yb)
		return;
	colorit(0, xa + 1, ya + 1, yb - 1, 3 - col);
	colorit(1, ya + 1, xa + 1, xb - 2, 3 - col);	
	colorit(0, xb - 1, ya + 1, yb - 1, col);
	colorit(1, yb - 1, xa + 2, xb - 1, col);
	rec(xa + 1, ya + 1, xb - 1, yb - 1, 3 - col);
}

