std::pair<int, int> pre[555][555];
int mark[555][555];

std::pair<int, int> bfs(int x, int y) {
  std::queue<std::pair<int, int>> q;
  q.emplace(x, y);
  while (q.size()) {
    int x, y;
    std::tie(x, y) = q.front(); q.pop();
    for (int dx = -1; dx <= 1; dx++) {
      for (int dy = -1; dy <= 1; dy++) {
        if (dx | dy) {
          int tx = x + dx, ty = y + dy;
          if (mark[tx][ty] == 1) {
            return {x, y};
          }
          if (!mark[tx][ty]) {
            mark[tx][ty] = 1;
            pre[tx][ty] = {x, y};
            q.emplace(x, y);
          }
        }
      }
    }
  }
  return {-1, -1};
}

