				dfs(i,j,++cnt);
	for(int i=1;i<cnt;++i) bfs(i,i+1,cnt+1);
	for(int i=1;i<cnt;++i) bfs(i,i+1,cnt+2);
	for(int i=1;i<=h;++i,puts(""))
