using namespace std;
typedef long long Long;
typedef pair<int,int> PII;
struct DisjointSet
{
	vector<int> R , P;
	DisjointSet(int N)
	{
		R = vector<int>(N,0);
		P = vector<int>(N,-1);
	}
	int find(int x)
	{
		return P[x] == -1 ? x : (P[x] = find(P[x]));
	}
	bool join(int x,int y)
	{
		x = find(x); y = find(y);
		if(x == y)return false;
		if(R[x] > R[y]) P[y] = x;
		else P[x] = y;
		R[y] += R[x] == R[y];
		return true;
	}
};
string MAT[512];
int NR[512][512];
int D[512][512];
struct joint{
	int i1,j1,i2,j2,d,i,j;
	bool operator<(const joint &j)const{
		return d < j.d;
	}
};
struct state{
	int i,j,id;
};
int dx[] = {-1,0,0,1};
int dy[] = {0,-1,1,0};
void paint(int N,int M, char c){
	int SZ = 0;
	memset(NR,-1,sizeof(NR));
	memset(D,-1,sizeof(D));
	queue<state> Q;
	for(int i = 0; i < N; ++i){
		for(int j = 0; j < M; ++j){
			if(MAT[i][j] != '#')continue;
			state st = {i,j,SZ};
			D[i][j] = 0;
			NR[i][j] = SZ;
			Q.push(st);
			SZ++;
		}
	}
    while(Q.size()){
        state t = Q.front(); Q.pop();
        for(int k = 0; k < 4; ++k){
            state nt = {t.i+dx[k],t.j+dy[k],t.id};
            if(nt.i < 0 || nt.i >= N || nt.j < 0 || nt.j >= M)
                continue;
            if(MAT[nt.i][nt.j] == '#')continue;
            if(D[nt.i][nt.j] != -1)continue;
            D[nt.i][nt.j] = D[t.i][t.j]+1;
            NR[nt.i][nt.j] = nt.id;
            Q.push(nt);
        }
    }
	vector<joint> V;
	for(int i = 0; i < N; ++i){
        for(int j = 0; j < M; ++j){
            for(int k = 0; k < 4; ++k){
                int ni = i + dx[k], nj = j + dy[k];
                if(ni < 0 || ni >= N || nj < 0 || nj >= M)continue;
                if(NR[i][j] == NR[ni][nj])continue;
                joint J = {i,j,ni,nj,D[i][j] + D[ni][nj],NR[i][j],NR[ni][nj]};
                V.push_back(J);
            }

        }
    }
	sort(V.begin(),V.end());
    DisjointSet DS(SZ);
    for(int i = 0; i < V.size(); ++i){
        joint J = V[i];
        if(DS.join(J.i, J.j)){
        	{
        		int ni=J.i1,nj=J.j1;
        		while(D[ni][nj] != 0){
					for(int k = 0; k < 4; ++k){
						int nni = ni+dx[k], nnj = nj+dy[k];
						if(nni < 0 || nni >= N || nnj < 0 || nnj >= M)
							continue;
						if(NR[nni][nnj] != NR[ni][nj])continue;
						if(D[nni][nnj]+1 != D[ni][nj])continue;
						MAT[ni][nj] = c;
						ni = nni;
						nj = nnj;
					}
        		}
        	}
        	{
        		int ni=J.i2,nj=J.j2;
        		while(D[ni][nj] != 0){
					for(int k = 0; k < 4; ++k){
						int nni = ni+dx[k], nnj = nj+dy[k];
						if(nni < 0 || nni >= N || nnj < 0 || nnj >= M)
							continue;
						if(NR[nni][nnj] != NR[ni][nj])continue;
						if(D[nni][nnj]+1 != D[ni][nj])continue;
						MAT[ni][nj] = c;
						ni = nni;
						nj = nnj;
					}
        		}
        	}
        }
    }

}

int main(){
	int N,M;
	cin >> N >> M;
	for (int i = 0; i < N; ++i) {
		cin >> MAT[i];
	}
	paint(N,M,'R');
	for(int i = 0; i < N; ++i){
		string s = MAT[i];
		for(char &c : s){
			if(c == 'R')
				c = '#';
		}
