void solve(){
	int H,W;
	cin >> H >> W;
	vector< string > org(H),fldA(H),fldB(H);
	UnionFind uf(H*W);
	vector< bool > used(H*W,false);//代表値のみuf.find()
	for(int h=0;h<H;++h){
		cin >> org[h];
		fldA[h] = org[h];
		fldB[h] = org[h];
		for(int w=0;w<W;++w){
			if( org[h][w] != '#' ) continue;
			if( org[h-1][w] == '#' ){
				uf.add((h-1)*W + w,h*W + w);
			}
			if( org[h][w-1] == '#' ){
				uf.add(h*W + (w-1),h*W + w );
			}
		}
	}


	for(int w=1;w<W-1;++w){//端でない一番上を塗る。
		fldA[1][w] = '#';
		if( w > 1 ){//左と繋ぐ
			uf.add(W + w-1,W + w);
			int num = uf.find(W+w);
			used[num] = true;
		}
		if( 2 < H ){
			if( fldA[2][w] == '#' ){//下
				uf.add(1*W + w, 2*W + w);
				int num = uf.find(1*W+w);
				used[num] = true;
			}
		}
	}

	for(int h=0;h<H;++h){//全面塗る。
		for(int w=0;w<W;++w){
			fldB[h][w] = '#';
		}
		if( h==1 ){
			for(int w=1;w<W-1;++w){
				if( org[h][w] != '#' ){
					fldB[h][w] = '.';//fldAで塗っている
				}
			}
		}
	}

	for(int h=2;h<H-1;++h){
		for(int w=1;w<W-1;++w){
			if( org[h][w] != '#' ) continue;
			int num = h*W + w;
			num = uf.find( num );
			if( used[num] ) continue;
			used[num] = true;
			for(int hh = h-1; hh>=1;--hh){
				if( org[hh][w] == '#' ) break;
				fldA[hh][w] = '#';
				fldB[hh][w] = '.';
			}
		}
	}
	for(int h=0;h<H;++h){
		cout << fldA[h] << endl;
	}
	cout << endl;
	for(int h=0;h<H;++h){
		cout << fldB[h] << endl;
	}
}

