      cin >> y;
    }
  }

  auto r = v, b = v;
  int sx = -1, sy;
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < m; ++j) {
      if (v[i][j] == '#') {
        sx = i;
        sy = j;
      }
    }
  }
  if (sx == -1) {
    r[0][0] = '#';
    b[0][1] = '#';
  } else {
    vector<pair<int, int> > q;
    q.push_back({sx, sy});
    vector<vector<pair<int, int> > > pr(n, vector<pair<int, int> >(m));
    pr[sx][sy] = {sx, sy};
    vector<vector<char> > vis(n, vector<char>(m));
    vis[sx][sy] = 1;
    for (int i = 0; i < q.size(); ++i) {
      int x = q[i].first, y = q[i].second;
      if (v[x][y] == '#') {
        while (1) {
          int a = pr[x][y].first, b = pr[x][y].second;
          if (r[a][b] == '#') {
            break;
          }
          r[a][b] = '#';
        }
      }
      if (x > 0 && !vis[x - 1][y]) {
        vis[x - 1][y] = 1;
        q.push_back({x - 1, y});
        pr[x - 1][y] = {x, y};
      }
      if (x < n - 1 && !vis[x + 1][y]) {
        vis[x + 1][y] = 1;
        q.push_back({x + 1, y});
        pr[x + 1][y] = {x, y};
      }
      if (y > 0 && !vis[x][y - 1]) {
        vis[x][y - 1] = 1;
        q.push_back({x, y - 1});
        pr[x][y - 1] = {x, y};
      }
      if (y < m - 1 && !vis[x][y + 1]) {
        vis[x][y + 1] = 1;
        q.push_back({x, y + 1});
        pr[x][y + 1] = {x, y};
      }
    }

    dfs(sx, sy, v, r, b);
  }

  for (auto& x : r) {
    for (auto& y : x) {
      cout << y;
    }
    cout << '\n';
  }
  cout << '\n';
  for (auto& x : b) {
    for (auto& y : x) {
      cout << (y == '@' ? '#' : '.');
    }
    cout << '\n';
  }
  return 0;
}

