const int N = 500 + 100, B = 330, oo = 1e15 + 10, A = 26, M = 1e6 + 7, pw = 3;

int n, m;
int dp[N][N], dp1[N][N];
int used[N][N];


void dfs(int dp[N][N], int i, int j, int c)
{
    if (i < 0 || j < 0 || i >= n || j >= m || dp[i][j] == 0)
        return;

    used[i][j] = 1;
    dfs(dp, i - 1, j, c);
    dfs(dp, i + 1, j, c);
    dfs(dp, i, j + 1, c);
    dfs(dp, i, j - 1, c);
}


bool conect(int dp[N][N])
{
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            used[i][j] = 0;


    int c = 1;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
        {
            if (!used[i][j])
                dfs(dp1, i, j, c++);
        }

    return c == 1;
}


void smain()
{
    int n, m;
    cin >> n >> m;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            dp1[i][j] = 1;

    for (int i = 0; i < m; ++i)
        dp1[i][0] = 0,
        dp[i][0] = 1;

    for (int i = 0; i < n; ++i) {
        string s;
        cin >> s;
        for (int j = 0; j < m; ++j)
            if (s[j] == '#')
            {
                for (int z = 0; z <= j; ++z)
                    dp[i][z] = 1,
                    dp1[i][z] = 0;

            }

        for (int j = 0; j < m; ++j)
            if (s[j] == '#')
                dp1[i][j] = 1;
            else
            {
                assert(dp1[i][j] + dp[i][j] <= 1);
            }

    }

    assert(conect(dp));
    assert(conect(dp1));

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (dp[i][j])
                cout << '#';
            else
                cout << '.';
        }

        cout << '\n';
    }

    cout << '\n';

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (dp1[i][j])
                cout << '#';
            else
                cout << '.';
        }

        cout << '\n';
    }
}

