int h, w;

void bfs(vector<string> &bd, int x, int y)
{
    queue<pair<int, int>> q;
    q.push(make_pair(x, y));

    map<pair<int, int>, pair<int, int>> mm;

    while (!q.empty()) {
        auto cx = q.front().first;
        auto cy = q.front().second;
        q.pop();

        if (bd[cy][cx] == '#') {
            while (!(cx == x && cy == y)) {
                auto t = mm[make_pair(cx, cy)];
                cx = t.first;
                cy = t.second;
                bd[cy][cx] = '#';
            }
            return;
        }

        static const int v[4][2] = {
            {1, 0},
            {-1, 0},
            {0, 1},
            {0, -1},
        };

        // cout << cx << ", " << cy << endl;

        for (int d = 0; d < 4; d++) {
            int nx = cx + v[d][0];
            int ny = cy + v[d][1];

            if (!(nx >=1 && nx < w-1 && ny >= 1&& ny < h-1)) {
                continue;
            }

            if (mm.count(make_pair(nx, ny))) {
                continue;
            }

            mm[make_pair(nx, ny)] = make_pair(cx, cy);
            q.push(make_pair(nx, ny));
        }
    }
}

int main()
{
    cin >> h >> w;

    vector<string> bd(h);
    for (auto &row: bd) {
        cin >> row;
    }

    vector<string> cur(h, string(w, '.'));
    bool fst = true;

    for (int y = 1; y < h-1; y++) {
        for (int x = 1; x < w - 1; x++) {
            if (bd[y][x] == '#') {
                if (fst) {
                    cur[y][x] = '#';
                    fst = false;
                } else {
                    bfs(cur, x, y);
                }
            }
        }
    }

    for (auto &row: cur) {
        cout << row << endl;
    }
    cout << endl;

    vector<string> red(h, string(w, '.'));

    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            if (bd[y][x] == '#' || cur[y][x] == '.') {
                red[y][x] = '#';
            }
        }
    }

    for (auto &row: red) {
        cout << row << endl;
    }

    vector<string> ppr(h, string(w, '.'));
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            ppr[y][x] = (cur[y][x] == '#' && red[y][x] == '#') ? '#' : '.';
        }
    }

    // assert(bd == ppr);
    if (bd != ppr) {
        cout << endl;
        for (auto &row : ppr)
        {
            cout << row << endl;
        }
        abort();
    }

    return 0;
}

