            char c; cin >> c;
            if (i == 0 || i == h-1 || j == 0 || j == w-1) {
                red[i][j] = '#';
                blue[i][j] = '.';
            }
            else
                red[i][j] = c;
            purple[i][j] = (c == '#');
        }
    }
    for (int i=0; i<h; i++) {
        for (int j=0; j<w; j++) {
            if (visited[i][j] || !purple[i][j]) continue;
            P s = dfs(i, j);
            for (int k=s.second; k>=0; k--) {
                if (purple[s.first][k]) continue;
                red[s.first][k] = '#';
                blue[s.first][k] = '.';
            }
        }
    }
    for (auto r:red) cout << r << endl;
    cout << endl;
    for (auto b:blue) cout << b << endl;
    return 0;
}

