bool dfs(int y, int x, bool tmp_arr[500][500]) {
	if(!(x>0&&x<w-1&&y>0&&y<h-1)) return false;
	if(tmp_arr[y][x]) return false;
	tmp_arr[y][x] = true;
	if(mp[y][x]) return true;
	for(int i = 0; i < 4; i++) {
		int dx = x+dir[i][0];
		int dy = y+dir[i][1];
		bool flg = dfs(dy,dx,tmp_arr);
		if(flg) {
			arrived[y][x] = true;
			return true;
		}
	}
}

