 public:
  UnionFind(int size) : data(size, -1) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) { return root(x) == root(y); }
  int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
  int size(int x) { return -data[root(x)]; }
};

#define IJ(i,j) (i)*W+(j)


void solve(int H,int W,vs& m){
    vvi a(H,vi(W,1)), b(H,vi(W,0));
    rep(i,H) a[i][0] = a[i][W-1] = 0;
    rep(j,W) a[0][j] = a[H-1][j] = 0;
    rep(i,H) rep(j,W) if (m[i][j] == '#') b[i][j] = 1;

    rep(j,W) b[0][j] = 1;
    for (int j=1; j<W; j+=2) {
        for (int i=1; i<H-1; ++i) {
            if (m[i][j] == '.') a[i][j] = 0;
            b[i][j] = 1;
        }
    }


    rep(i,H){
        rep(j,W) putchar(".#"[a[i][j]]);
        putchar('\n');
    }
    putchar('\n');
    rep(i,H){
        rep(j,W) putchar(".#"[b[i][j]]);
        putchar('\n');
    }
}

int main() {
    int H, W; cin >> H >> W;
    vs a(H);
    rep(i,H) cin >> a[i];
    solve(H,W,a);
    return 0;
}

