void bfs(int xx,int yy)
{
	queue<int> qx,qy;
	qx.push(xx),qy.push(yy);vis[xx][yy]=1;
	while(qx.size())
	{
		int x=qx.front(),y=qy.front();qx.pop(),qy.pop();
		for(int i=0;i<4;i++) 
		{
			int ix=x+ax[i],iy=y+ay[i];
			if(ix>=0 and iy>=0 and vis[ix][iy]==0 and buf[ix][iy]=='#')
				vis[ix][iy]=1,qx.push(ix),qy.push(iy);
		}
	}
}
void connect(int x1,int y1,int x2,int y2)
{
//	cout<<x1<<" "<<y1<<"->"<<x2<<" "<<y2<<"\n";
	for(int i=min(y1,y2);i<=max(y1,y2);i++) tag[x1][i]=1;
	for(int i=min(x1,x2);i<=max(x1,x2);i++) tag[i][y2]=1;
}
int main()
{
	scanf("%d%d",&n,&m);
	for(int i=0;i<n;i++) scanf("%s",buf[i]);
	vector<int> px,py;
	for(int i=0;i<n;i++)
	{
		if(i%2==0)
			for(int j=0;j<m;j++)
			{
				if(vis[i][j] or buf[i][j]!='#') continue;
				px.push_back(i);py.push_back(j);
				bfs(i,j);
			}
		else
			for(int j=m-1;j>=0;j--)
			{
				if(vis[i][j] or buf[i][j]!='#') continue;
				px.push_back(i);py.push_back(j);
				bfs(i,j);
			}
	}
	for(int i=0;i<px.size()-1;i++)
		connect(px[i],py[i],px[i+1],py[i+1]);

	for(int i=0;i<n;i++)
	{
		for(int j=0;j<m;j++)
			if(tag[i][j] or buf[i][j]=='#') putchar('#');else putchar('.');
		puts("");
	}
	for(int i=0;i<n;i++)
	{
		for(int j=0;j<m;j++)
			if(!tag[i][j] or buf[i][j]=='#') putchar('#');else putchar('.');
		puts("");
	}
	return 0;
}

