	for (int i = 0; i < 4; i++)
	{
		int nx = x + dir[i][0];
		int ny = y + dir[i][1];
		if (vis[nx][ny])continue;
		if (val[nx][ny] == '#'&&dsu[nx][ny] == 0)
		{
			dfs(nx, ny, c);
		}
	}
}

bool dfs_1(int x, int y,int c)
{
	if (x == 1 || x == h || y == 1 || y == w)
	{
		return false;
	}
	vis[x][y] = 1;
	for (int i = 0; i < 4; i++)
	{
		int nx = x + dir[i][0];
		int ny = y + dir[i][1];
		if (vis[nx][ny])continue;
		if (val[nx][ny] == '#'&&dsu[nx][ny] < c)
		{
			return true;
		}
	}
	for (int i = 0; i < 4; i++)
	{
		int nx = x + dir[i][0];
		int ny = y + dir[i][1];
		if (vis[nx][ny])continue;
		if (val[nx][ny] == '.')
		{
			res1[nx][ny] = 1;
			if (dfs_1(nx, ny,c))
			{
				return true;
			}
			else
			{
				res1[nx][ny] = 0;
			}
		}
		if (val[nx][ny] == '#'&&dsu[nx][ny] < c)
		{
			return true;
		}
	}
	return false;
}

bool dfs_2(int x, int y, int c)
{
	if (x == 1 || x == h || y == 1 || y == w)
	{
		return true;
	}
	vis[x][y] = 1;
	for (int i = 0; i < 4; i++)
	{
		int nx = x + dir[i][0];
		int ny = y + dir[i][1];
		if (vis[nx][ny])continue;
		if (val[nx][ny] == '.'&&res1[nx][ny])continue;
		if (val[nx][ny] == '.')
		{
			res2[nx][ny] = 1;
			if (dfs_2(nx, ny, c))
			{
				return true;
			}
			else
			{
				res2[nx][ny] = 0;
			}
		}
		if (val[nx][ny] == '#'&&dsu[nx][ny] < c)
		{
			return true;
		}
	}
	return false;
}

void solve()
{
	scanf("%d%d", &h, &w);
	for (int i = 1; i <= h; i++)
	{
		scanf("%s", val[i] + 1);
		for (int j = 1; j <= w; j++)
		{
			if (val[i][j] == '#')
			{
				res1[i][j] = 1;
