			}
			if (i == 1 || i == h || j == 1 || j == w)
			{
				res2[i][j] = 1;
			}
		}
	}
	cnt = 0;
	memset(vis, 0, sizeof(vis));
	for (int i = 1; i <= h; i++)
	{
		for (int j = 1; j <= w; j++)
		{
			if (val[i][j] == '#'&&dsu[i][j] == 0)
			{
				cnt++;
				d[cnt].first = i;
				d[cnt].second = j;
				dfs(i, j, cnt);
			}
		}
	}
	memset(vis, 0, sizeof(vis));
	for (int k = 2; k <= cnt; k++)
	{
		dfs_1(d[k].first, d[k].second, dsu[d[k].first][d[k].second]);
	}
	memset(vis, 0, sizeof(vis));
	for (int k = 2; k <= cnt; k++)
	{
		dfs_2(d[k].first, d[k].second, dsu[d[k].first][d[k].second]);
	}
	for (int i = 1; i <= h; i++)
	{
