void dfs(int x, int y) {
    used[x][y] = true;
    c[x][y] = 1;
    for(int i = 0; i < 4; ++i) {
        int tox = dx[i] + x, toy = dy[i] + y;
        if(check(tox, toy) && !used[tox][toy] && (!b[tox][toy] || a[tox][toy])) {
            dfs(tox, toy);
        }
    }
}

