using namespace std;

#define rep_h(i) for(int i = 1;i <= h;i++)
#define rep_w(i) for(int i = 1;i <= w;i++)
#define range(i,j) ((1 <= i && i <= h && 1 <= j && j <= w))

int h;
int w;

int fie[510][510];
int red[510][510];
int blue[510][510];
int group[510][510];

typedef pair<int,int> P;

int dx[] = {1,-1,0,0};
int dy[] = {0,0,1,-1};

int main()
{
	cin >> h >> w;
	rep_h(i)
	{
		string s;
		cin >> s;
		rep_w(j)
		{
			if(s[j - 1] == '#')
			{
				fie[i][j] = 1;
			}
		}
	}
	rep_h(i) rep_w(j)
	{
		if(i == 1) i++;
		if(j == 1) j++;
		if(i == h || j == w) break;
		red[i][j] = 1;
	}
	int cou = 1;
	rep_h(i) rep_w(j)
	{
		if(fie[i][j] == 1)
		{
			queue<P> que;
			que.push(P(i,j));
			while(!que.empty())
			{
				int x = que.front().first;
				int y = que.front().second;
				que.pop();
				if(fie[x][y] == 0) continue;
				fie[x][y] = 0;
				group[x][y] = cou;

				for(int d = 0;d < 4;d++)
				{
					int nx = x + dx[d];
					int ny = y + dy[d];
					if(range(nx,ny) && fie[nx][ny] == 1)
					{
						que.push(P(nx,ny));
					}
				}
			}
			cou++;
		}
	}


	blue[1][1] = 1;

	for(int i = 1;i < cou;i++)
	{
		P from[510][510];

		from[1][1].first = -1;
		from[1][1].second = -1;

		int ex,ey;

		deque<P> que;
		que.push_back(P(1,1));
		while(!que.empty())
		{
			int x= que.front().first;
			int y = que.front().second;
			que.pop_front();

			blue[x][y] = 1;

			bool f = false;

			for(int d = 0;d < 4;d++)
			{
				int nx = x + dx[d];
				int ny = y + dy[d];
				if(range(nx,ny) && group[nx][ny] == 0 && from[nx][ny].first == 0)
				{
					from[nx][ny].first = x;
					from[nx][ny].second = y;
					if(nx == 0 || nx == h || ny == 0 || ny == w || blue[nx][ny] == 1)
					{
						que.push_front(P(nx,ny));
					}
					else
						que.push_back(P(nx,ny));
				}
				if(range(nx,ny) && group[nx][ny] == i)
				{
					from[nx][ny].first = x;
					from[nx][ny].second = y;

					ex = nx;
					ey = ny;
					f=true;
					break;
				}
			}
			if(f) break;
		}
		blue[ex][ey] = 1;
		while(from[ex][ey].first != -1)
		{
			int x = from[ex][ey].first;
			int y = from[ex][ey].second;
			blue[x][y] = 1;
			red[x][y] = 0;
			ex = x;
			ey = y;

		}

	}

	rep_h(i)
	{
		rep_w(j)
		{
			if(red[i][j] == 1)
			{
				cout << "#";
			}
			else
			{
				cout << ".";
			}
		}
		cout << endl;
	}
	cout << endl;
	rep_h(i)
	{
		rep_w(j)
		{
			if(blue[i][j] == 1 || group[i][j] != 0)
			{
				cout << "#";
			}
			else
			{
				cout << ".";
			}
		}
		cout << endl;
	}
	return 0;
}

