inline bool check(int x, int y, bool border = true) {
    if(border)
        return 1 < x && x < n && 1 < y && y < m;
    return 1 <= x && x <= n && 1 <= y && y <= m;
}

inline void bfs() {
    while(ql <= qr) {
        int x = q[ql].f, y = q[ql].se;
        ql++;
        for(int i = 0; i < 4; ++i) {
            int tox = dx[i] + x, toy = dy[i] + y;
            if(check(tox, toy) && d[tox][toy] == inf) {
                p[tox][toy] = {x, y};
                d[tox][toy] = d[x][y] + 1;
                q[++qr] = {tox, toy};
            }
        }
    }
}

inline void start_bfs() {
    memset(d, 0x3f, sizeof(d));
    q[ql = qr = 0] = *is.begin();
    d[is.begin()->f][is.begin()->se] = 0;
    bfs();
}

void dfs(int x, int y) {
    used[x][y] = true;
    c[x][y] = 1;
    for(int i = 0; i < 4; ++i) {
        int tox = dx[i] + x, toy = dy[i] + y;
        if(check(tox, toy, false) && !used[tox][toy] && (!b[tox][toy] || a[tox][toy])) {
            dfs(tox, toy);
        }
    }
}

