void dfs(int hs, int ws) {
	s[hs][ws] = 'B';
	FOR(k,4) {
		int hn = hs+px[k], wn = ws+py[k];
		if (hn<0 || hn>=h || wn<0 || wn>=w) continue;
		if (s[hn][wn]=='r' || s[hn][wn]=='B') continue;
		dfs(hn, wn);
	}
}

