    function<pair<int, int>(int, int)> dfs = [&](int x, int y) {
        painted[x][y] = true;
        constexpr int dx[]={0, -1, 1, 0}, dy[]={1, 0, 0, -1};
        int lx = x, ly = y;
        for (auto i = 0; i < 4; i++) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx >= 0 && nx < h && ny >= 0 && ny < w && board[nx][ny] == '#' && !painted[nx][ny]) {
                auto res = dfs(nx, ny);
                if (res.second < ly)
                    tie(lx, ly) = res;
            }
        }
        return make_pair(lx, ly);
    };
    for (auto i = 0; i < h; i++) {
        for (auto j = 0; j < w; j++) {
            if (board[i][j] == '#' && !painted[i][j]) {
                int x, y;
                tie(x, y) = dfs(i, j);
                for (auto k = 1; k <= y; k++)
                    result[x][k] = '#';
            }
        }
    }
    return result;
}

vector<string> paint_blue(vector<string> const& board, vector<string> const& red) {
    int h = board.size(),
        w = board[0].size();
    vector<string> result(h, string(w, '#'));
    for (auto i = 0; i < h; i++)
        for (auto j = 0; j < w; j++)
            if (board[i][j] != '#' && red[i][j] == '#')
                result[i][j] = '.';
    return result;
}

int main() {
    int h, w;
    cin >> h >> w;
    vector<string> board(h);
    for (auto& i : board) cin >> i;
    auto const& red = paint_red(board);
    auto const& blue = paint_blue(board, red);
    for (auto& i : red)
        cout << i << endl;
    cout << endl;
    for (auto& i : blue)
        cout << i << endl;
    return 0;
}

