int a[555][555];
string s[555], p[555], q[555];

void calc(int lx, int rx, int ly, int ry) {
	int sz = min(ry - ly + 1, rx - lx + 1);
	for(int i = lx; i <= rx; i++) {
		a[i][ly] = a[i][ry] = 1;
	}
	for(int j = ly; j <= ry; j++) {
		a[lx][j] = a[rx][j] = 1;
	}
	if(sz > 1) a[lx + 1][ly] = 0;
	if(sz > 4) {
		a[lx + 2][ly + 1] = 1;
		calc(lx + 2, rx - 2, ly + 2, ry - 2);
	}
}

