void dfs(int i, int j)
{
	if (i < 0 || j < 0 || i >= n || j >= m || used[i][j] || a[i][j] == '.')
		return;
	used[i][j] = 1;
	dfs(i - 1, j);
	dfs(i + 1, j);
	dfs(i, j - 1);
	dfs(i, j + 1);
}

