bool gogo1( int ni , int nj ){
  int sv = clr[ ni ][ nj ];
  clr[ ni ][ nj ] |= 1;
  for( int i = 0 ; i < 4 ; i ++ ){
    int nxti = ni + dn[ i ];
    int nxtj = nj + dm[ i ];
    if( in( nxti , nxtj ) ){
      if( c[ nxti ][ nxtj ] == '#' )
        return true;
      if( ( clr[ nxti ][ nxtj ] & 2 ) == 2 )
        continue;
      if( ( clr[ nxti ][ nxtj ] & 1 ) == 1 )
        return true;
      if( gogo1( nxti , nxtj ) )
        return true;
    }
  }
  clr[ ni ][ nj ] = sv;
  return false;
}
bool gogo2( int ni , int nj ){
  int sv = clr[ ni ][ nj ];
  clr[ ni ][ nj ] |= 2;
  for( int i = 3 ; i >= 0 ; i -- ){
    int nxti = ni + dn[ i ];
    int nxtj = nj + dm[ i ];
    if( in( nxti , nxtj ) ){
      if( c[ nxti ][ nxtj ] == '#' )
        return true;
      if( ( clr[ nxti ][ nxtj ] & 1 ) == 1 )
        continue;
      if( ( clr[ nxti ][ nxtj ] & 2 ) == 2 )
        return true;
      if( gogo2( nxti , nxtj ) )
        return true;
    }
  }
  clr[ ni ][ nj ] = sv;
  return false;
}
