inline int find(int x){return fa[x]==x?x:(fa[x]=find(fa[x]));}
inline void merge(int x,int y){
	x=find(x);y=find(y);
	fa[x]=y;
}
inline void add(int x,int y){
	for(int i=0;i<4;i++){
		int tx=x+u[i][0],ty=y+u[i][1];
		if(tx<=1||tx>=n||ty<=1||ty>=m||!vis[tx][ty]) continue;
		merge(num[x][y],num[tx][ty]);
	}
}
inline bool check(int x,int y){
	vi nei(0);
	for(int i=0;i<4;i++){
		int tx=x+u[i][0],ty=y+u[i][1];
		if(tx<=1||tx>=n||ty<=1||ty>=m) continue;
		nei.pb(find(num[tx][ty]));
	}
	sort(nei.begin(),nei.end());
	for(int i=0;i<SZ(nei)-1;i++)
		if(nei[i]==nei[i+1]) return 0;
	return 1;
}
inline void dfs(int x,int y){
	vis[x][y]=1;
	for(int i=0;i<4;i++){
		int tx=x+u[i][0],ty=y+u[i][1];
		if(tx<=1||tx>=n||ty<=1||ty>=m||vis[tx][ty]) continue;
		if(check(tx,ty)) add(tx,ty),dfs(tx,ty);
	}
}

