int fa[701*701];

int find(int x){
	if(!x) return 0;
	return (fa[x]==x?x:(fa[x]=find(fa[x])));
}
struct data{
	int x,y,k;
	bool operator < (const data & a) const{
		return k<a.k;
	}
};
int top,sta[MAXN+1]; 
int dis[5][2]={{0,1},{1,0},{0,-1},{-1,0}};
inline int Get_num(int i,int j){
	top=0; int num=0;
	for(int k=0;k<4;k++){
		int xx=i+dis[k][0];
		int yy=j+dis[k][1];
		if(xx<1||yy<1||xx>N||yy>M) continue;
		sta[++top]=find((xx-1)*M+yy);
		//cout<<sta[top]<<" ";
	} //cout<<"gg\n";
	sort(sta+1,sta+top+1);
	top=unique(sta+1,sta+top+1)-sta-1;
	for(int k=1;k<=top;k++){
		if(sta[k]) ++num;
	} return num;
}
inline data make_data(int x,int y,int k){
	data n; n.x=x; n.y=y; n.k=k; return n;
}
priority_queue<data> que;
bool fg[701][701]; int sz[MAXN+1];
bool vis[701][701];
void merge(int x,int y){
	if(x==y) return; fa[y]=x; sz[x]+=sz[y];
} void dfs(int x,int y){
	if(fg[x][y]) return; fg[x][y]=1;
	c[x][y]=1; for(int k=0;k<4;k++){
		int xx=x+dis[k][0];
		int yy=y+dis[k][1];
		if(xx<1||yy<1||xx>N||yy>M||vis[xx][yy]) continue;
		dfs(xx,yy);
	} return ;
}
int fx,fy;

int main(){
	//freopen(".in","r",stdin);
	//freopen(".out","w",stdout);
	N=read(),M=read(); int cnt;
