		scanf("%s",s+1);
		for(int j=1;j<=M;j++){
			c[i][j]=(s[j]=='#');
			if(c[i][j]) fa[(i-1)*M+j]=(i-1)*M+j,sz[(i-1)*M+j]=1,++cnt,fx=i,fy=j;
		}
	} for(int i=1;i<=N;i++){
		for(int j=1;j<=M;j++){
			if(!c[i][j]) {
				int x=Get_num(i,j); if(!x||x==1) continue;
				//for(int i=1;i<=top;i++) cout<<sta[i]<<" ";
				//cout<<endl;
				que.push(make_data(i,j,x));
			}
		}
	}
	while(!que.empty()&&sz[find((fx-1)*M+fy)]!=cnt){
		data k=que.top(); que.pop(); int tes=Get_num(k.x,k.y);
		if(tes<=1) continue; 
		if(tes<k.k) {k.k=tes; que.push(k); continue;}
		for(int i=2;i<=top;i++){
			if(sta[i-1]&&sta[i]) merge(sta[i-1],sta[i]);
		} vis[k.x][k.y]=1;
	} for(int i=1;i<=N;i++){
		for(int j=1;j<=M;j++){
			if(vis[i][j]||c[i][j]) printf("#");
			else printf(".");
		} printf("\n");
	} dfs(fx,fy); printf("\n");
	for(int i=1;i<=N;i++){
		for(int j=1;j<=M;j++){
			if(c[i][j]) printf("#");
			else printf(".");
		} printf("\n");
	}
	return 0;
}

