#include <bits/stdc++.h>
using namespace std;

typedef long long LL;
typedef pair<int, int> PII;

#define REP(i, n) for (int i = 0; i < int(n); ++i)
#define REPE(i, a, b) for (int i = (a); i <= int(b); ++i)
#define F first
#define S second

const int dx[] = {1, 0, -1, 0};
const int dy[] = {0, 1, 0, -1};

int a[550][550] = {{}};
int n, m;
char s[550];

int v[550][550] = {{}};

int no = 0;
void dfs(int i, int j) {
  if (i < 0 || j < 0 || i == n || j == m || v[i][j] || a[i][j] != 3) return ;
  v[i][j] = no;
  dfs(i + 1, j);
  dfs(i - 1, j);
  dfs(i, j + 1);
  dfs(i, j - 1);
}

int main() {
  scanf("%d%d", &n, &m);
  REP(i, n) {
    scanf("%s", s);
    REP(j, m) a[i][j] = s[j] == '#' ? 3 : 0;
  }
  no++;
  REPE(i, 1, n - 2) {
    a[i][0] = 1;
    v[i][0] = no;
  }
  REP(i, n) REP(j, m) {
    if (a[i][j] == 3 && !v[i][j]) {
      no++;
      dfs(i, j);
      int k = j;
      while (k > 0) {
        if (v[i][k] && v[i][k] != no) {
          break;
        }
        v[i][k] = no;
        a[i][k] |= 1;
        REP(d, 4) {
          int tx = i + dx[d];
          int ty = k + dy[d];
          if (v[tx][ty] && v[tx][ty] != no) {
            k = 0;
            break;
          }
        }
        k--;
      }
    }
  }
  REP(i, n) {
    REP(j, m) {
      putchar((a[i][j] & 1) ? '#' : '.');
    }
    puts("");
  }
  puts("");
  REP(i, n) {
    REP(j, m) {
      putchar((a[i][j] == 1) ? '.' : '#');
    }
    puts("");
  }
  return 0;
}

