						paint[tm][tn]=true;
						visited[tm][tn]=true;
						int ttm=parent[tm][tn].first;
						int ttn=parent[tm][tn].second;
						tm=ttm;
						tn=ttn;
					}
				}
			}
		}
		for(temp=0;temp<m;temp++)
		{
			for(temp2=0;temp2<n;temp2++)
			{
				if(paint[temp][temp2])
				{
					cout<<'#';
				}
				else
				{
					cout<<'.';
				}
				if(a[temp][temp2]=='#')
				{
					visited[temp][temp2]=false;
					if(q.empty())
					{
						q.push(troll(temp,temp2,-1,-1));
					}
				}
			}
			cout<<"\n";
