bool P[500][500];
bool R[500][500];

int H, W;

int main(int,char**) {
    ios_base::sync_with_stdio(false);

    cin >> H >> W;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            char c; cin >> c;
            R[i][j] = P[i][j] = c == '#';
        }
    }

    for (int i = 1; i < H-1; i++) {
        R[i][1] = true;
    }

    int prevlo = 1; 
    int prevhi = H-2;
    int prevcol = 1;
    for (int j = 2; j < W-1; j++) {
        int lo = H;
        int hi = 0;
        for (int i = 1; i < H-1; i++) {
            if (P[i][j]) {
                    int h = i;
                    if (R[i-1][j]) continue;
                    while (R[h][j]) ++h;
                    bool done = false;
                    for(int q = i; q < h; ++q) {
                        if (R[q][prevcol]) {
                            for (int k = prevcol+1; k < j; k++) R[i][k] = true;
                            done = true;
                            break;
                        }
                    }
                    if (!done && R[i-1][prevcol]) {
                        for (int k = prevcol+1; k < j; k++) R[i-1][k] = true;
                        R[i-1][j] = true;
                    } else if (!done && R[h][prevcol]) {
                        for (int k = prevcol+1; k < j; k++) R[h][k] = true;
                        R[h+1][j] = true;
                    } else if (!done) {
                        if (lo < i) {
                            for (int h = lo; h < i; h++) {
                                R[h][j] = true;
                            }
                        } else if (prevlo < i) {

                            for (int h = prevlo; h < i; h++) {
                                R[h][j] = true;
                            }

                        for (int k = prevcol+1; k < j; k++) R[prevlo][k] = true;
                        } else {
                            for (int h = i; h <= prevhi; h++) {
                                R[h][j] = true;
                            }

                        for (int k = prevcol+1; k < j; k++) R[prevhi][k] = true;
                        }
                    }

                    lo = min(lo,i);
                    hi = max(hi, h-1);
            }
        }

        if (lo != H) {
            prevlo = lo;
            prevhi = hi;
            prevcol = j;
        }
    }

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            cout << (R[i][j] ? '#' : '.');
        }
        cout << endl;
    }
    cout << endl;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            cout << ((P[i][j] || !R[i][j]) ? '#' : '.');
        }
        cout << endl;
    }

}

