	}
	for(int i = 1; i <= n; i++) {
		for(int j = 1; j <= m; j++) 
			if(s[i][j] == '#') {
				pn++;
				if(pn >= 260*250) return 0;
				bfs(i, j);
			}
	}
	return 0;
	/*for(int i = 1; i <= pn; i++) {
		for(int j = 0; j < (int)p[i].size(); j++)
			printf("(%d, %d) ", p[i][j].x, p[i][j].y);
		printf("\n");
	}*/
	l = r = 0;
	for(int i = 0; i < (int)p[1].size(); i++) {
		q[++r] = p[1][i];
		d[p[1][i].x][p[1][i].y] = 0;
		vis[p[1][i].x][p[1][i].y] = true;
	}

	BFS();

	memset(vis, false, sizeof(vis));
	for(int i = 2; i <= pn; i++) {
		pii u = p[i][0];
		for(int j = 1; j < (int)p[i].size(); j++) {
			pii x = p[i][j];
			if(d[x.x][x.y] < d[u.x][u.y]) u = x;
		}
		u = pre[u.x][u.y];
		while(d[u.x][u.y]) {
			if(B[u.x][u.y] != '#') vis[u.x][u.y] = true;
			A[u.x][u.y] = '#';
			u = pre[u.x][u.y];
		}
	}

	l = r = 0;
	for(int i = 0; i < (int)p[1].size(); i++) {
		q[++r] = p[1][i];
		d[p[1][i].x][p[1][i].y] = 0;
		vis[p[1][i].x][p[1][i].y] = true;
	}

	for(int i = 1; i <= n; i++)
		for(int j = 1; j <= m; j++)
			pre[i][j].x = pre[i][j].y = 0;
	//printf("%d\n", vis[4][2]);
	BFS();
	//printf("(%d, %d)\n", pre[4][2].x, pre[4][2].y);
	for(int i = 2; i <= pn; i++) {
		pii u = p[i][0];
		for(int j = 1; j < (int)p[i].size(); j++) {
			pii x = p[i][j];
			if(d[x.x][x.y] < d[u.x][u.y]) u = x;
		}
		u = pre[u.x][u.y];
		while(d[u.x][u.y]) {
			B[u.x][u.y] = '#';
			u = pre[u.x][u.y];
		}
