const int dx[] = { 0, 1, 0, -1 };
const int dy[] = { 1, 0, -1, 0 };

int H, W;

bool in_range( int x, int y ){
    return 0 <= x and x < H and 0 <= y and y < W;
}


int COL_ID;
void dfs( const vector< string > &G, vvi &vis, int x, int y ){
    vis[ x ][ y ] = COL_ID;
    for( int di = 0; di < 4; ++di ){
        int nx = x + dx[ di ];
        int ny = y + dy[ di ];
        if( not in_range( nx, ny ) ) continue;
        if( vis[ nx ][ ny ] ) continue;
        if( G[ nx ][ ny ] != '#' ) continue;
        dfs( G, vis, nx, ny );
    }
}

void solve(){
    cin >> H >> W;
    vector< string > G( H );
    for( int i = 0; i < H; ++i )
        cin >> G[ i ];
    vvi blue( H, vi( W ) ), red( H, vi( W ) );
    for( int i = 0; i < H; ++i )
        for( int j = 0; j < W; ++j )
            blue[ i ][ j ] = ( G[ i ][ j ] == '#' );
    for( int i = 1; i + 1 < H; ++i )
        for( int j = 1; j + 1 < W; ++j )
            red[ i ][ j ] = 1;
    vvi vis( H, vi( W ) );
    for( int i = 0; i < H; ++i )
        for( int j = 0; j < W; ++j )
            if( G[ i ][ j ] == '#' and not vis[ i ][ j ] )
                ++COL_ID,
                dfs( G, vis, i, j );
    vi vis2( COL_ID + 1 );
    for( int i = 0; i < H; ++i )
        for( int j = 0; j < W; ++j )
            if( vis[ i ][ j ] and not vis2[ vis[ i ][ j ] ] ){
                vis2[ vis[ i ][ j ] ] = 1;
                for( int k = i - 1; k >= 0; --k )
                    blue[ k ][ j ] = 1;
            }
    for( int i = 0; i < H; ++i )
        for( int j = 0; j < W; ++j )
            if( G[ i ][ j ] == '.' and blue[ i ][ j ] )
                red[ i ][ j ] = 0;
    for( int i = 0; i < H; ++i, cout << endl )
        for( int j = 0; j < W; ++j )
            cout << ".#"[ blue[ i ][ j ] ];
    cout << endl;
    for( int i = 0; i < H; ++i, cout << endl )
        for( int j = 0; j < W; ++j )
            cout << ".#"[ red[ i ][ j ] ];
}

int main(){
    ios::sync_with_stdio( false );
    solve();
    return 0;
}

