using namespace std;
#define MAX_N 600
char x[MAX_N][MAX_N]; int H, W; bool used[MAX_N][MAX_N], used2[MAX_N][MAX_N];
vector<pair<int, int>>vec2[MAX_N*MAX_N];
char R[MAX_N][MAX_N], B[MAX_N][MAX_N];

string hantei() {
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (x[i][j] != '#') {
				if (R[i][j] == '#' && B[i][j] == '#') {
					return "Wrong Answer";
				}
			}
			if (x[i][j] == '#') {
				if (R[i][j] != '#' || B[i][j] != '#') {
					return "Wrong Answer";
				}
			}
		}
	}
	return "Accepted";
}
int main() {
	cin >> H >> W;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) { cin >> x[i][j]; R[i][j] = '.'; B[i][j] = '.'; }
	}
	queue<pair<int, int>>T; T.push(make_pair(0, 0)); used[0][0] = true;
	while (!T.empty()) {
		int a1 = T.front().first, a2 = T.front().second; T.pop();
		int dx[4] = { 1,0,-1,0 }, dy[4] = { 0,1,0,-1 };
		for (int i = 0; i < 4; i++)
		{
			int cx = a1 + dx[i], cy = a2 + dy[i];
			if (cx < 0 || cy < 0 || cx >= H || cy >= W)continue;
			if (used2[cx][cy] == true || x[cx][cy] == '#')continue;

			used2[cx][cy] = true; T.push(make_pair(cx, cy));
		}
	}
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (used2[i][j] == false && x[i][j] != '#') { x[i][j] = '$'; R[i][j] = '#'; }
		}
	}
	int counts = 0;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (used[i][j] == true || x[i][j] == '.')continue;
			queue<pair<int, int>>Q; Q.push(make_pair(i, j));
			vector<pair<int, int>>G; G.push_back(make_pair(i, j));
			int dx[4] = { 0,1,0,-1 }, dy[4] = { 1,0,-1,0 };
			while (!Q.empty()) {
				int a1 = Q.front().first, a2 = Q.front().second; Q.pop();
				for (int k = 0; k < 4; k++)
				{
					int cx = a1 + dx[k], cy = a2 + dy[k];
					if (cx < 0 || cy < 0 || cx >= H || cy >= W)continue;
					if (x[cx][cy] == '.' || used[cx][cy] == true)continue;

					G.push_back(make_pair(cx, cy)); Q.push(make_pair(cx, cy)); used[cx][cy] = true;
				}
			}
			vec2[counts] = G; counts++;
		}
	}
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (i == 0 || i == H - 1 || j == 0 || j == W - 1)R[i][j] = '#';
		}
	}
	for (int i = 0; i < counts; i++) {
		int minx = MAX_N, minid = 0;
		for (int j = 0; j < vec2[i].size(); j++) {
			int D = min(abs(0 - vec2[i][j].second), abs((W - 1) - vec2[i][j].second));
			if (D < minx) { minx = D; minid = j; }
		}
		int C1 = abs(0 - vec2[i][minid].second);
		int C2 = abs((W - 1) - vec2[i][minid].second);
		if (C1 >= C2) {
			for (int j = 0; j < vec2[i][minid].second; j++) {
				R[vec2[i][minid].first][j] = '#';
			}
		}
		else {
			for (int j = W - 1; j > vec2[i][minid].second; j--) {
				R[vec2[i][minid].first][j] = '#';
			}
		}
	}
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (x[i][j] == '#') { R[i][j] = '#'; B[i][j] = '#'; }
			else if (R[i][j] != '#') { B[i][j] = '#'; }
		}
	}
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++)cout << R[i][j]; cout << endl;
	}
	cout << endl;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++)cout << B[i][j]; cout << endl;
	}
	cout << hantei() << endl;
	return 0;
}

