void solve() {
	int n = ::n, m = ::m;
	memset(s, 0, sizeof(s));
	DE(n, ' '), DE(m, '\n');
	auto corner = [&](int x, int y) {
		return (x==1&&y==m) || (x==n&&y==1) || (x==n&&y==m);
	};
	int x = 1, y = 1, dx = 1, dy = 0;
	do {
		DE(x, ' '), DE(y, '\n');
		s[x][y] = 1;
		if (corner(x, y) || s[ x+dx*2 ][ y+dy*2 ]) {
			if (dx) swap(dx, dy);
			else swap(dx, dy), dx *= -1;
		}
		//if (x < 0 || y < 0) DE(n, ' '), DE(m, '\n'), exit(0);
		x += dx, y += dy;
		if (s[x][y]) break;
	} while (!s[x+dx][y+dy]);
	for (int i = 2;i < n;++i)
		for (int j = 2;j < m;++j)
			if (s[i][j] == 0) s[i][j] = 2;
}
