const int maxn = 510;
int v[maxn][maxn], n, m, s[maxn][maxn];
void solve() {
	int n = ::n, m = ::m;
	--n |= 1, --m |= 1;
	DE(n, ' '), DE(m, '\n');
	auto corner = [&](int x, int y) {
		return (x==1&&y==m) || (x==n&&y==1) || (x==n&&y==m);
	};
	int x = 1, y = 1, dx = 1, dy = 0;
	do {
		s[x][y] = 1;
		if (corner(x, y) || s[ x+dx*2 ][ y+dy*2 ]) {
			if (dx) swap(dx, dy);
			else swap(dx, dy), dx *= -1;
		}
		x += dx, y += dy;
	} while (!s[x+dx][y+dy]);
	//n = ::n, m = ::m;
	for (int i = 1;i <= n;++i)
		for (int j = 1;j <= m;++j) {
			if (!s[i][j]) s[i][j] = 2;
			v[i][j] |= s[i][j];
			s[i][j]&=1;
		}
//	for (int i = 1;i <= n;++i)
//		debug(s[i]+1, s[i]+1+m);
}



