using namespace std;

const int MaxN = 500;
const int MaxM = 500;

int n, m;
char map[MaxN + 2][MaxM + 2];

inline bool is_red(int x, int y)
{
	return map[x][y] == '#' || y == 1 || (y != m && (x & 1));
}
inline bool is_blue(int x, int y)
{
	return map[x][y] == '#' || y == m || (y != 1 && (~x & 1));
}

int main()
{
	scanf("%d %d", &n, &m);
	for (int i = 1; i <= n; ++i)
		scanf("%s", map[i] + 1);

	for (int i = 1; i <= n; ++i)
	{
		for (int j = 1; j <= m; ++j)
			putchar(is_red(i, j) ? '#' : '.');
		putchar('\n');
	}

	putchar('\n');

	for (int i = 1; i <= n; ++i)
	{
		for (int j = 1; j <= m; ++j)
			putchar(is_blue(i, j) ? '#': '.');
		putchar('\n');
	}

	return 0;
}

