const int MAXN = 5e2 + 5;

int N, M;
int A[MAXN][MAXN];

void print(int a[][MAXN])
{
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= M; ++j) {
            putchar(a[i][j] & 1 ? '#' : '.');
        }
        putchar('\n');
    }
    putchar('\n');
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= M; ++j) {
            putchar(a[i][j] & 2 ? '#' : '.');
        }
        putchar('\n');
    }
}

void input()
{
    read(N); read(M);
    for (int i = 1; i <= N; ++i) {
        static char inp[MAXN];
        scanf("%s", inp);
        for (int j = 1; j <= M; ++j) {
            A[i][j] = inp[j - 1] == '#' ? 3 : 0;
        }
    }
}

void solve()
{
    for (int i = 1; i <= N; ++i) {
        A[i][1] = 1; A[i][M] = 2;
    }
    for (int i = 2; i < M; ++i) {
        A[1][i] = 1; A[N][i] = 2;
    }
    for (int i = 2; i < N; ++i) {
        for (int j = 2; j < M; ++j) {
            A[i][j] |= i & 1 ? 1 : 2;
        }
    }
    print(A);
}

int main()
{
#ifdef __DEBUG
    freopen("C.in", "r", stdin);
    freopen("C.out", "w", stdout);
#endif

    input();
    solve();

    return 0;
}

