void BFS(int x, int y)
{
	if(a[x][y] != '#' or Vis[x][y])
	{
		return;
	}
	b[x][y] = '#';
	Vis[x][y] = true;
	BFS(x + 1, y);
	BFS(x, y + 1);
	BFS(x - 1, y);
	BFS(x, y - 1);
}

void BFS2(int x, int y)
{
	if(b[x][y] == '#' and a[x][y] != '#')
	{
		return;
	}
	if(c[x][y] == '#' or x == 0 or y == 0 or x == h + 1 or y == w + 1)
	{
		return;
	}
	c[x][y] = '#';
	BFS2(x + 1, y);
	BFS2(x, y + 1);
	BFS2(x - 1, y);
	BFS2(x, y - 1);
}

