}

inline bool U(const int &x,const int &y)
{
	djx=F(x),djy=F(y);if(F(x)==F(y))return false;
	if(r[djx]<=r[djy]){f[djx]=djy;if(r[djx]==r[djy])r[djy]++;}else f[djy]=djx;return true;
