	udone[x][y]=false;
	U(clr[x][y],l);
	dfs(x-1,y,l);
	dfs(x+1,y,l);
	dfs(x,y-1,l);
	dfs(x,y+1,l);
}

inline void connect(Point s,Point t)
{
	if(s.x>t.x)swap(s,t);
	if(s.y<=t.y)
	{
		int dx=t.x-s.x,dy=t.y-s.y;
		while(dx|dy)
		{
			if(dx>dy)dx--;else dy--;
			red[s.x+dx][s.y+dy]=true;
		}
	}
	else
	{
		int dx=t.x-s.x,dy=s.y-t.y;
		while(dx|dy)
		{
			if(dx>dy)dx--;else dy--;
			red[s.x+dx][s.y-dy]=true;
		}
	}
}

