char grid[500][500];
int parent[250000];
int find(int n) {
    if (parent[n] != n) parent[n] = find(parent[n]);
    return parent[n];
}
int merge(int a,int b) {
    a = find(a),b = find(b);
    if (a != b) parent[a] = b;
    return 0;
}
vpii v;
int ans1[500][500];
int main() {
    int i,j;
    int H,W;
    scanf("%d %d",&H,&W);
    for (i = 0; i < H; i++) {
        for (j = 0; j < W; j++) scanf(" %c",&grid[i][j]);
    }

    for (i = 0; i < H*W; i++) parent[i] = i;
    for (i = 0; i < H; i++) {
        for (j = 0; j < W; j++) {
            if (grid[i][j] == '#') {
                v.pb(mp(i,j)),ans1[i][j] = 1;
                if (ans1[i-1][j]) merge(i*W+j,(i-1)*W+j);
                if (ans1[i][j-1]) merge(i*W+j,i*W+j-1);
            }
        }
    }
    random_shuffle(v.begin(),v.end());
    for (i = 1; i < v.size(); i++) {
        if (find(v[i].first*W+v[i].second) != find(v[i-1].first*W+v[i-1].second)) {
            vpii path;
            int x = v[i-1].first,y = v[i-1].second;
            while (x < v[i].first) path.pb(mp(++x,y));
            while (x > v[i].first) path.pb(mp(--x,y));
            while (y < v[i].second) path.pb(mp(x,++y));
            while (y > v[i].second) path.pb(mp(x,--y));
            for (j = 0; j < path.size(); j++) {
                if (find(v[i].first*W+v[i].second) == find(v[i-1].first*W+v[i-1].second)) break;
                ans1[path[j].first][path[j].second] = 1;
                int x = path[j].first,y = path[j].second;
                if (ans1[x-1][y]) merge(x*W+y,(x-1)*W+y);
                if (ans1[x+1][y]) merge(x*W+y,(x+1)*W+y);
                if (ans1[x][y-1]) merge(x*W+y,x*W+y-1);
                if (ans1[x][y+1]) merge(x*W+y,x*W+y+1);
            }
        }
    }
    for (i = 0; i < H; i++) {
        for (j = 0; j < W; j++) {
            if (ans1[i][j]) printf("#");
            else printf(".");
        }
        printf("\n");
    }
    printf("\n");
    for (i = 0; i < H; i++) {
        for (j = 0; j < W; j++) {
            if (!ans1[i][j] || (grid[i][j] == '#')) printf("#");
            else printf(".");
        }
        printf("\n");
    }

    return 0;
}

