#include<bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair<int, int> pii;

#define F first
#define S second

int H,W;
char A[505][505];
bool tach[505][505];
pii p1,p2;
int x[4]={0,0,-1,1};
int y[4]={-1,1,0,0};

bool Move(int x_s,int y_s,int x_d,int y_d)
{
    if(x_d<p1.F||x_d>p2.F||y_d<p1.S||y_d>p2.S) return false;
    else if(tach[x_d][y_d]) return false;///verificando si esta usado
    else if(A[x_d][y_d]=='#') return true;
    else
    {
        int total = 0;
        for(int i=0;i<4;i++)
        {
            if(x_d+x[i]>=p1.F-1 && x_d+x[i]<=p2.F+1 && y_d+y[i]>=p1.S-1 && y_d+y[i]<=p2.S+1 && A[x_d+x[i]][y_d+y[i]]=='R')
            {
                total++;
            }
        }
        if(total) return true;
        else return false;
    }
}

int main(){

    cin >> H >> W;
    for(int i=0;i<H;i++) cin >> A[i];
    p1={-1,-1};
    p2={-1,-1};
    for(int i=0;i<H;i++)
    {
        for(int j=0;j<W;j++)
        {
            tach[i][j]=false;
            if(A[i][j]!='#') A[i][j] = 'R';
            else
            {
                if(p1.F==-1&&p1.S==-1&&p2.F==-1&&p2.S==-1)
                {
                    p1={i,j};
                    p2={i,j};
                }
                else
                {
                    vector<int> X;
                    vector<int> Y;
                    X.push_back(p1.F);
                    X.push_back(p2.F);
                    X.push_back(i);
                    Y.push_back(p1.S);
                    Y.push_back(p2.S);
                    Y.push_back(j);
                    sort(X.begin(),X.end());
                    sort(Y.begin(),Y.end());
                    p1={X[0],Y[0]};
                    p2={X[2],Y[2]};
                }
            }
        }
    }

    for(int i=0;i<H;i++)
    {
        for(int j=0;j<W;j++)
        {
            if(A[i][j]!='#') A[i][j]='R';
        }
    }

    queue<pii> q;
    tach[p1.F][p1.S]=true;
    q.push({p1.F,p1.S});
    pii aux;
    while(!q.empty())
    {
        aux = q.front();
        q.pop();
        for(int i=0;i<4;i++)
        {
            int x_pos = aux.F+x[i];
            int y_pos = aux.S+y[i];
            if(Move(aux.F,aux.S,x_pos,y_pos))
            {
                tach[x_pos][y_pos] = true;
                if(A[x_pos][y_pos]=='R') A[x_pos][y_pos]='A';
                q.push({x_pos,y_pos});
            }
        }
    }

    ///Imprimir
    for(int i=0;i<H;i++) {
        for(int j=0;j<W;j++) {
            if(A[i][j]=='R'||A[i][j]=='#') cout << "#";
            else cout << ".";
        }
        cout << endl;
    }
    for(int i=0;i<H;i++) {
        for(int j=0;j<W;j++) {
            if(A[i][j]=='A'||A[i][j]=='#') cout << "#";
            else cout << ".";
        }
        cout << endl;
    }

    return 0;
}

