void dfs(int x, int y,int c)
{
	if (x == 1 || x == h || y == 1 || y == w)
	{
		return;
	}
	vis[x][y] = 1;
	dsu[x][y] = c;
	for (int i = 0; i < 4; i++)
	{
		int nx = x + dir[i][0];
		int ny = y + dir[i][1];
		if (vis[nx][ny])continue;
		if (val[nx][ny] == '#'&&dsu[nx][ny] == 0)
		{
			dfs(nx, ny, c);
		}
	}
}

bool dfs_1(int x, int y,int c)
{
	if (x == 1 || x == h || y == 1 || y == w)
	{
		return false;
	}
	vis[x][y] = 1;
	for (int i = 0; i < 4; i++)
	{
		int nx = x + dir[i][0];
		int ny = y + dir[i][1];
		if (vis[nx][ny])continue;
		if (res1[nx][ny]==2)
		{
			return true;
		}
		if (val[nx][ny] == '#'&&dsu[nx][ny] < c)
		{
			return true;
		}
	}
	for (int i = 0; i < 4; i++)
	{
		int nx = x + dir[i][0];
		int ny = y + dir[i][1];
		if (vis[nx][ny])continue;
		if (val[nx][ny] == '.')
		{
			if (dfs_1(nx, ny,c))
			{
				res1[nx][ny] = 2;
				return true;
			}
		}
	}
	return false;
}

bool dfs_2(int x, int y, int c)
{
	if (x == 1 || x == h || y == 1 || y == w)
	{
		return true;
	}
	vis[x][y] = 1;
	for (int i = 0; i < 4; i++)
	{
		int nx = x + dir[i][0];
		int ny = y + dir[i][1];
		if (vis[nx][ny])continue;
		if (res2[nx][ny]==2)
		{
			return true;
		}
		if (val[nx][ny] == '#'&&dsu[nx][ny] < c)
		{
			return true;
		}
	}

	for (int i = 0; i < 4; i++)
	{
		int nx = x + dir[i][0];
		int ny = y + dir[i][1];
		if (vis[nx][ny])continue;
		if (val[nx][ny] == '.'&&res1[nx][ny])continue;
		if (val[nx][ny] == '.')
		{
			if (dfs_2(nx, ny, c))
			{
				res2[nx][ny] = 2;
				return true;
			}
			else
			{
				res2[nx][ny] = 0;
			}
		}
	}
	return false;
}

void solve()
{
	scanf("%d%d", &h, &w);
	for (int i = 1; i <= h; i++)
	{
		scanf("%s", val[i] + 1);
		for (int j = 1; j <= w; j++)
		{
			if (val[i][j] == '#')
			{
				res1[i][j] = 1;
				res2[i][j] = 1;
			}
			if (i == 1 || i == h || j == 1 || j == w)
			{
				res2[i][j] = 1;
			}
		}
	}
	cnt = 0;
	memset(vis, 0, sizeof(vis));
	for (int i = 1; i <= h; i++)
	{
		for (int j = 1; j <= w; j++)
		{
			if (val[i][j] == '#'&&dsu[i][j] == 0)
			{
				cnt++;
				d[cnt].first = i;
				d[cnt].second = j;
				dfs(i, j, cnt);
			}
		}
	}
	memset(vis, 0, sizeof(vis));
	for (int k = 2; k <= cnt; k++)
	{
		dfs_1(d[k].first, d[k].second, dsu[d[k].first][d[k].second]);
	}
	memset(vis, 0, sizeof(vis));
	for (int k = 2; k <= cnt; k++)
	{
		dfs_2(d[k].first, d[k].second, dsu[d[k].first][d[k].second]);
	}
	for (int i = 1; i <= h; i++)
	{
		for (int j = 1; j <= w; j++)
		{
			if (res1[i][j])
			{
				printf("#");
			}
			else
			{
				printf(".");
			}
		}
		printf("\n");
	}

	printf("\n");
	for (int i = 1; i <= h; i++)
	{
		for (int j = 1; j <= w; j++)
		{
			if (res2[i][j])
			{
				printf("#");
			}
			else
			{
				printf(".");
			}
		}
		printf("\n");
	}
}

int main()
{
	solve();
	return 0;
}

