		q.pop();
		f(i, 0, 4) {
			int a = x + dx[i], b = y + dy[i];
			if (a == 0 || a > h || b == 0 || b > w || vis[a][b])continue;
			p[a][b] = i;
			if (m[a][b] == '#')vis[a][b] = 2; else vis[a][b] = 1;
			q.push(make_pair(a, b));
		}
	}
}

int dn = 1;
void dfs(int x = f[0].first, int y = f[0].second) {
	if (dn == f.size())return;
	f(i, 0, 4) {
		int a = x + dx[i], b = y + dy[i];
		if (a == 0 || a > h || b == 0 || b > w || vis[a][b] == 3)continue;
		p[a][b] = i;
		if (vis[a][b] == 4)++dn;
		vis[a][b] = 3;
		dfs(a, b);
	}
