template<int um> class UF {
	public:
	vector<int> par,rank;
	UF() {rank=vector<int>(um,0); for(int i=0;i<um;i++) par.push_back(i);}
	int operator[](int x) {return (par[x]==x)?(x):(par[x] = operator[](par[x]));}
	int operator()(int x,int y) {
		if((x=operator[](x))==(y=operator[](y))) return x;
		if(rank[x]>rank[y]) return par[x]=y;
		rank[x]+=rank[x]==rank[y]; return par[y]=x;
	}
};
UF<500000> uf;

int H,W;
string S[505];

void dfs(int y,int x) {
	if(y<0 || y>=H || x<0 || x>=W) return;
	if(S[y][x]!='.') return;
	S[y][x]='&';
	dfs(y-1,x);
	dfs(y+1,x);
	dfs(y,x-1);
	dfs(y,x+1);
}

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>H>>W;
	FOR(y,H) cin>>S[y];
	FOR(y,H) FOR(x,W-1) if(S[y][x]=='#' && S[y][x+1]=='#') uf(y*500+x,y*500+x+1);
	FOR(y,H-1) FOR(x,W) if(S[y][x]=='#' && S[y+1][x]=='#') uf(y*500+x,(y+1)*500+x);

	for(y=1;y<H-1;y++) for(x=1;x<W-1;x++) if(S[y][x]=='.') {
		int dy[4]={y,y,y+1,y-1},dx[4]={x+1,x-1,x,x};
		int ng=0;
		FOR(i,4) FOR(j,i) if(uf[dy[i]*500+dx[i]]==uf[dy[j]*500+dx[j]]) ng++;
		if(ng==0) {
			S[y][x]='$';
			if(S[y-1][x]!='.') uf(y*500+x,(y-1)*500+x);
			if(S[y+1][x]!='.') uf(y*500+x,(y+1)*500+x);
			if(S[y][x-1]!='.') uf(y*500+x,y*500+x-1);
			if(S[y][x+1]!='.') uf(y*500+x,y*500+x+1);
		}
	}

	dfs(0,0);

	FOR(y,H) {
		FOR(x,W) {
			if(S[y][x]=='#' || S[y][x]=='$') cout<<'#';
			else cout<<'.';
		}
		cout<<endl;
	}
	cout<<endl;
	FOR(y,H) {
		FOR(x,W) {
			if(S[y][x]=='#' || S[y][x]=='&') cout<<'#';
			else cout<<'.';
		}
		cout<<endl;
	}



}


