#include<map>
#include<utility>
template<typename T>
class UnionFind {
 public:
  void unite(const T& a, const T& b) {
    auto x = find(a), y = find(b);
    if(rank_[x] < rank_[y]) std::swap(x, y);
    parent_[y] = x;
    if(rank_[x] == rank_[y]) rank_[x] += 1;
  }
  T find(const T& x) {
    if(!parent_.count(x)) {
      rank_[x] = 1;
      return parent_[x] = x;
    }
    return (parent_[x] == x) ? x : (parent_[x] = find(parent_[x]));
  }
 private:
  std::map<T, T> parent_;
  std::map<T, int> rank_;
};

#include<bits/stdc++.h>
using namespace std;

using P = pair<int, int>;

int main() {
  int H, W;
  cin >> H >> W;
  vector<string> A(H);
  for(auto& i: A) cin >> i;

  auto valid = [&](auto y, auto x){return 0<=y && y<H && 0<=x && x<W;};
  auto next = [&](auto y, auto x) {
    vector<P> res;
    for(P nex: {P{y,x+1}, P{y,x-1}, P{y+1,x}, P{y-1,x}}) if(valid(nex.first, nex.second)) res.emplace_back(nex.first, nex.second);
    return res;
  };

  auto r = A, b = A;
  for(auto j=0; j<W; ++j) r[0][j] = '#';

  UnionFind<P> g;
  for(auto i=0; i<H; ++i) for(auto j=0; j<W; ++j) if(r[i][j] == '#') for(auto nex: next(i, j)) if(r[nex.first][nex.second] == '#') g.unite({i,j}, nex);

  for(auto i=0; i<H; ++i) for(auto j=0; j<W; ++j) if(r[i][j] == '#') {
    if(g.find({i,j}) == g.find({0,0})) continue;
    for(auto k=i; 0<=k; --k) {
      auto last = (g.find({k-1,j}) == g.find({0,0}));
      for(auto nex: next(k, j)) if(r[nex.first][nex.second] == '#') g.unite({k,j}, nex);
      r[k][j] = '#';
      if(last) break;
    }
  }
  for(auto i=0; i<H; ++i) for(auto j=0; j<W; ++j) if(r[i][j] == '.') b[i][j] = '#';
  for(auto i=0; i<H; ++i) cout << r[i] << endl;
  cout << endl;
  for(auto i=0; i<H; ++i) cout << b[i] << endl;

