#define inrange(x, y) (0 <= x && x < h && 0 <= y && y < w)

bool purple[510][510] = {{0}},
     visited[510][510] = {{0}};
int dir[4][2] = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
int h, w;

using P = pair<int, int>;

P dfs(int i, int j) {
    P best = {i, j};
    visited[i][j] = true;
    for (auto d:dir) {
        int x = i + d[0],
            y = j + d[1];
        if (inrange(x, y) && !visited[x][y] && purple[x][y]) {
            P res = dfs(x, y);
            best = min(best, res);
        }
    }
    return best;
}

int main() {
    cin >> h >> w;
    vector<string> red(h, string(w, '.')), blue(h, string(w, '#'));
