void dfs(int x,int y){
	if(vis[x][y] || p[x][y]!='#')return;
	if(x<up.fr)up=mk(x,y);
	if(x>dw.fr)dw=mk(x,y);

	vis[x][y]=1;
	rep(k,0,3)dfs(x+dx[k],y+dy[k]);
