bool G[MAXN][MAXN], GA[MAXN][MAXN], GB[MAXN][MAXN], vis[MAXN][MAXN];
int H, W, minx[MAXN * MAXN], miny[MAXN * MAXN], cccnt = 0;

const int dx[4] = {0, 1, 0, -1};
const int dy[4] = {1, 0, -1, 0};
void dfs(int x, int y) {
	vis[x][y] = 1;
	if( (y < miny[cccnt]) || (y == miny[cccnt] && x < minx[cccnt]) ) miny[cccnt] = y, minx[cccnt] = x;
	for(int i = 0; i < 4; i++) {
		int tx = x + dx[i], ty = y + dy[i];
		if(tx >= 1 && ty >= 1 && tx <= H && ty <= W && G[tx][ty] && !vis[tx][ty])
			dfs(tx, ty);
	}
}

char str[5];
int main() {
	int i, x, y;
	scanf("%d%d", &H, &W);
	for(x = 1; x <= H; x++) for(y = 1; y <= W; y++) scanf("%1s", str), G[x][y] = (str[0] == '#') ? 1 : 0;

	for(x = 1; x <= H; x++) for(y = 1; y <= W; y++) if(G[x][y] && !vis[x][y]) {
		cccnt++; minx[cccnt] = miny[cccnt] = INF; dfs(x, y);
	}

	memset(GB, 1, sizeof(GB));
	for(x = 2; x <= H - 1; x++) GA[x][1] = 1, GB[x][1] = 0;
	for(i = 1; i <= cccnt; i++) {
		for(y = 1; y <= miny[i]; y++) GA[ minx[i] ][ y ] = 1, GB[ minx[i] ][ y ] = 0;
	}

	for(x = 1; x <= H; x++) for(y = 1; y <= W; y++) {
		GA[x][y] |= G[x][y], GB[x][y] |= G[x][y];
	}

	for(x = 1; x <= H; x++) {
		for(y = 1; y <= W; y++) putchar(GA[x][y] ? '#' : '.');
		putchar('\n');
	}

	putchar('\n');
	for(x = 1; x <= H; x++) {
		for(y = 1; y <= W; y++) putchar(GB[x][y] ? '#' : '.');
		putchar('\n');
	}
	return 0;
}

