void solve() {
  cin >> r >> c;
  for(int i = 0; i < r; i++) {
    cin >> g[i];
    for(int j = 0; j < c; j++) {
      if(i%2 == 0 && j < c-1) red[i][j] = true;
      else if(i%2 == 1 && j == 0) red[i][j] = true;
      else blue[i][j] = true;
    }
    for(int j = 0; j < c; j++) {
      if(g[i][j] == '#') {
        red[i][j] = true;
        blue[i][j] = true;
