void find(int x,int y){
    int px,py,minn = 1000;
    rep(i,1,n)
        if(vis[i][y]!=0 && abs(i-x)-1 <= minn ){
            if(i == x && y == py) continue;
            minn = abs(i-y)-1;
            px = i,py = y;
        }
    rep(i,1,n)
        if(vis[i][y-1]!=0 && abs(i-x) <= minn){
            minn = abs(i-x);
            px = i, py = y-1;
        }
    int m1 = min(px,x), m2 = max(px,x);
    y = py;
    rep(i,m1,m2)
        if(!vis[i][y]) vis[i][y] = 2;
}

int dir[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};

void solve(){
    queue<pair<int,int> > q;
    while(q.size()) q.pop();
    rep(i,1,n){
        q.push(make_pair(i,1));
        vis[i][1] = 3;
    }
    while(q.size()){
        int x = q.front().first, y = q.front().second;
        vis[x][y] = 3;
        q.pop();
        rep(i,0,3){
            int tx = x+dir[i][0], ty = y+dir[i][1];
            if(tx < 1 || tx > n || ty < 1 || ty > m || vis[tx][ty] == 3 || vis[tx][ty] == 2){
                continue;
            }
            vis[tx][ty] = 3;
            q.push(make_pair(tx,ty));
        }
    }
}

