pi pr[505][505];

pi getParent(int x, int y) {
    if (pr[x][y] == mp(x, y))
        return mp(x, y);
    return pr[x][y] = getParent(pr[x][y].first, pr[x][y].second);
}

void Union(pi a, pi b) {
    a = getParent(a.f, a.s), b = getParent(b.f, b.s);
    if (a == b)
        return;
    pr[b.f][b.s] = a;
}



void color(pi f, pi s) {
    if (getParent(f.first, f.second) == getParent(s.first, s.second))
        return;
    assert(f.f <= s.f);
    pi orig = f;
    for (int i = f.f; i <= s.f; i++) {
        ans[0][i][f.s] = '#';
        Union(orig, mp(i, f.s));
    }
    for (int j = min(f.s, s.s); j <= max(f.s, s.s); j++) {
        ans[0][s.f][j] = '#';
        Union(orig, mp(s.f, j));
    }
}

