inline int read(){
    int x=0,f=1;char ch=getchar();
    while(ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=getchar();}
    while(ch>='0'&&ch<='9'){x=(x<<3)+(x<<1)+ch-'0';ch=getchar();}
    return x*f;
}
void dfs(int x,int y,int color){
	cx[color].push_back(x),cy[color].push_back(y);
	c[x][y]=color;
	int xx,yy; 
	for(int i=0;i<4;++i){
		xx=x+fx[i][0],yy=y+fx[i][1];
		if(xx>0&&yy>0&&xx<=h&&yy<=w&&s[xx][yy]=='#'&&c[xx][yy]==0) dfs(xx,yy,color);
	}
}
void bfs(int c1,int c2,int color){
	//puts("BFS:");
	int ux,uy,xx,yy;
	head=tail=0;
	memset(vis,0,sizeof vis);
	memset(fax,0,sizeof fax);
	memset(fay,0,sizeof fay);
	for(int i=0;i<cx[c1].size();++i) qx[++tail]=cx[c1][i],qy[tail]=cy[c1][i],vis[cx[c1][i]][cy[c1][i]]=1;
	//for(int i=0;i<cx[c1].size();++i) printf("%d %d\n",cx[c1][i],cy[c1][i]);
	while(head<=tail){
		ux=qx[++head],uy=qy[head];
		for(int i=0;i<4;++i){
			xx=ux+fx[i][0],yy=uy+fx[i][1];
			if(xx>0&&yy>0&&xx<=h&&yy<=w&&!vis[xx][yy]){
				fax[xx][yy]=ux,fay[xx][yy]=uy;
				//printf("%d %d %d %d %d %d\n",xx,yy,ux,uy,fax[xx][yy],fay[xx][yy]);
				if(c[xx][yy]==c2){
					//printf("%d %d %d %d\n",xx,yy,c[xx][yy],c2);
					//puts("!!!find!!!");
					int nx,ny;
					while(fax[xx][yy]!=0){
						nx=fax[xx][yy],ny=fay[xx][yy];
						xx=nx,yy=ny;
						//printf("%d %d\n",xx,yy);
						if(fax[xx][yy]!=0&&c[xx][yy]==0) c[xx][yy]=color;
					}
					//printf("%d %d????%d %d\n",xx,yy,fax[xx][yy],fay[xx][yy]); 
					return;
				}
				if(color==cnt+2&&c[xx][yy]==cnt+1) continue;
				qx[++tail]=xx,qy[tail]=yy; 
				vis[xx][yy]=1;
			}
		}
	}
}
