void dfs(int i, int j) {
  if (i < 0 || j < 0 || i == n || j == m || v[i][j] || a[i][j] != 3) return ;
  v[i][j] = true;
  dfs(i + 1, j);
  dfs(i - 1, j);
  dfs(i, j + 1);
  dfs(i, j - 1);
}

