void bfs(int q,int p)
{
	f[1][0]=q; f[1][1]=p; a[q][p]='.';
	c[++cnt].r=max(c[cnt].r,q);
	c[cnt].l=100000;
	c[cnt].l=min(c[cnt].l,q);
	int l=1,r=1;
	while (l<=r) 
	{
		for (int k=0;k<4;k++) {
			int i=f[l][0]+dx[k];
			int j=f[l][1]+dy[k];
			if (i<0||j<0||i>=n||j>=m) continue;
			if (a[i][j]=='#') {
				a[i][j]='.';
				f[++r][0]=i; f[r][1]=j; 
				c[cnt].l=min(c[cnt].l,i);
				c[cnt].r=max(c[cnt].r,i);
			} 
		}
		++l;
	}
//	cout << c[cnt].l << ' ' << c[cnt].r << endl;
}
bool cmp(node x,node y)
{
	return (x.l<y.l)||((x.l==y.l)&&(x.r<y.r));
}
