        }
        else
        {
            REP(j, w - 1)
            blue[i][j + 1] = '#';
        }
    }

    REP(i, h)
    {
        REP(j, w)
        {
            if (a[i][j] != '#')
                continue;

            if (i % 2)
                blue[i][j] = '#';
            else
                red[i][j] = '#';
        }
    }

