#define inrange(x, y) (0 <= x && x < h && 0 <= y && y < w)

bool purple[510][510] = {{0}},
     visited[510][510] = {{0}};
int dir[4][2] = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
int h, w;

using P = pair<int, int>;

P dfs(int i, int j) {
    P best = {i, j};
    visited[i][j] = true;
    for (auto d:dir) {
        int x = i + d[0],
            y = j + d[1];
        if (inrange(x, y) && !visited[x][y] && purple[x][y]) {
            P res = dfs(x, y);
            best = min(best, res);
        }
    }
    return best;
}

int main() {
    cin >> h >> w;
    vector<string> red(h, string(w, '.')), blue(h, string(w, '#'));
    for (int i=0; i<h; i++) {
        for (int j=0; j<w; j++) {
            char c; cin >> c;
            if (j == 0) {
                red[i][j] = '#';
                blue[i][j] = '.';
            }
            else
                red[i][j] = c;
            purple[i][j] = (c == '#');
        }
    }
    for (int i=0; i<h; i++) {
        for (int j=0; j<w; j++) {
            if (visited[i][j] || !purple[i][j]) continue;
            P s = dfs(i, j);
            for (int k=s.second; k>=0; k--) {
                if (purple[s.first][k]) continue;
