int h, w;

const int dc[4] = {1, 0, -1, 0};
const int dr[4] = {0, 1, 0, -1};

void printans() {
  for(int r = 0; r < h; ++r) {
    for(int c = 0; c < w; ++c) {
      putchar(field_red[r][c] != '.' ? '#' : '.'); 
    }
    putchar('\n');
  }
  putchar('\n');
  for(int r = 0; r < h; ++r) {
    for(int c = 0; c < w; ++c) {
      putchar(field_blue[r][c] != '.' ? '#' : '.'); 
    }
    putchar('\n');
  }
}

void fix(char field[512][512], int d) {
  switch( d ) {
  case 0 :
    for(int r = 1; r <= h - 2; ++r) {
      field[r][w-1] = '#';
    }
    break;
  case 1 :
    for(int c = 1; c <= w - 2; ++c) {
      field[h-1][c] = '#';
    }
    break;
  case 2 :
    for(int r = 1; r <= h - 2; ++r) {
      field[r][0] = '#';
    }
    break;
  case 3 :
    for(int c = 1; c <= w - 2; ++c) {
      field[0][c] = '#';
    }
    break;
  }       
}

void dfsfill(char field[512][512], int r, int c) {
  if( not ( 0 <= r and r < h and 0 <= c and c < w ) ) return;
  if( field[r][c] != '#' ) return;
  field[r][c] = '@';
  for(int i = 0; i < 4; ++i) {
    dfsfill(field, r + dr[i], c + dc[i]);
  }
}

int main() {
  scanf("%d %d", &h, &w);
  for(int i = 0; i < h; ++i) {
    scanf("%s", field_purple[i]);
  }
  for(int i = 0; i < h; ++i) {
    for(int j = 0; j < w; ++j) {
      field_red[i][j] = field_blue[i][j] = field_purple[i][j];
    }
  }

  for(int rd = 0; rd < 4; ++rd) {
    for(int cd = 0; cd < 4; ++cd) {
      if( rd == cd ) continue;
      // step 1 : init
      for(int i = 0; i < h; ++i) {
        for(int j = 0; j < w; ++j) {
          field_red[i][j] = field_blue[i][j] = field_purple[i][j];
        }
      }
      // step 2 : red_line
      for(int r = 0; r < h; ++r) {
        if( rd == 2 ) r = h - r - 1;
        for(int c = 0; c < w; ++c) {
          if( rd == 3 ) c = w - c - 1;
          if( field_red[r][c] == '#' ) {
            int nr = r, nc = c;
            dfsfill(field_red, nr, nc);
            nr += dr[rd]; nc += dc[rd];
            while( 0 <= nr and nr < h and 0 <= nc and nc < w ) {
              field_red[nr][nc] = '!';
              nr += dr[rd]; nc += dc[rd];
            }
          }
          if( rd == 3 ) c = w - c - 1;
        }
        if( rd == 2 ) r = h - r - 1;
      }
      // step 3 : try blue
      bool success = true;
      for(int r = 0; r < h; ++r) {
        if( cd == 2 ) r = h - r - 1;
        for(int c = 0; c < w; ++c) {
          if( cd == 3 ) c = w - c - 1;
          if( field_blue[r][c] == '#' ) {
            int nr = r, nc = c;
            dfsfill(field_red, nr, nc);
            nr += dr[cd]; nc += dc[cd];
            while( 0 <= nr and nr < h and 0 <= nc and nc < w ) {
              if( field_purple[nr][nc] != '#' and (field_red[nr][nc] == '!') ) {
                success = false;
                goto label_1;
              }
              field_blue[nr][nc] = '!';
              nr += dr[cd]; nc += dc[cd];
            }
          }
          if( cd == 3 ) c = w - c - 1;
        }
        if( cd == 2 ) r = h - r - 1;
      }
    label_1:;
      if( success ) {
        fix(field_red, rd);
        fix(field_blue, cd);
        printans();
        goto label_2;
      }
    }
  }
 label_2:;

  return 0;
}

