int main() {
    // freopen("input.txt", "r", stdin);

    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;
    a.assign(n, vector<int>(m, 0));

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            char c;
            cin >> c;

            if (c == OCCUP) {
                a[i][j] = (1 << 0) + (1 << 1);
            } else {
                a[i][j] = 0;
            }
        }
    }

    for (int j = 0; j < m; ++j) {
        a[0][j] = (1 << 0);
    }
    for (int i = 1; i < n; ++i) {
        a[i][0] = a[i][m - 1] = (1 << 0);
    }

    int len[2];
    len[1] = (m >> 1);
    len[0] = (m - 2 - len[1]);

    for (int j = 1; j < 1 + len[0]; ++j) {
        a[n - 1][j] = (1 << 0);
    }
    for (int j = 1 + len[0]; j < 1 + len[0] + len[1]; ++j) {
        a[n - 1][j] = (1 << 1);
    }

    bool left = true;
    for (int i = n - 2; i > 0; --i) {
        if (left) {
            for (int j = 1; j < 1 + len[1]; ++j) {
                a[i][j] |= (1 << 1);
            }
            for (int j = 1 + len[1]; j < 1 + len[1] + len[0]; ++j) {
                a[i][j] |= (1 << 0);
            }
        } else {
            for (int j = 1; j < 1 + len[0]; ++j) {
                a[i][j] |= (1 << 0);
            }
            for (int j = 1 + len[0]; j < 1 + len[0] + len[1]; ++j) {
                a[i][j] |= (1 << 1);
            }
        }
        left ^= true;
    }

    for (int b = 0; b < 2; ++b) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (GetBit(a[i][j], b)) {
                    cout << OCCUP;
                } else {
