  }
  rep(i,h) {
    if (i & 1) red.emplace_back(a);
    else red.emplace_back(b);
  }
  reverse(ALL(a));
  reverse(ALL(b));
  rep(i,h) {
    if (i & 1) blue.emplace_back(b);
