using namespace std;
const int N = 5e2+5;
int S[N][N], A[N][N], B[N][N], nmn = INT_MAX, nmx, mmn = INT_MAX, mmx, n, m;
char c[N];
void DFS(int i, int j){
    if(!B[i][j]) return;
    B[i][j] = 1;
    if(i-1>=nmn && S[i-1][j]) DFS(i-1, j);
    if(j-1>=mmn && S[i][j-1]) DFS(i, j-1);
    if(i+1>=nmx && S[i+1][j]) DFS(i+1, j);
    if(j+1>=mmx && S[i][j+1]) DFS(i, j+1);
}
int main(){
    scanf("%d %d", &n, &m);
    for(int i=0;i<n;i++){
        scanf("%s", c);
        for(int j=0;j<m;j++){
            if(c[j]=='#'){
                S[i][j] = 1;
                nmn = min(nmn, i);
                nmx = max(nmx, i);
                mmn = min(mmn, j);
                mmx = max(mmx, j);
            }
        }
    }
    for(int i=nmn-1;i<=nmx+1;i++) for(int j=mmn-1;j<=mmx+1;j++) A[i][j] = 1;
    for(int i=0;i<n;i++) for(int j=0;j<m;j++) if(S[i][j] && !B[i][j]){
        for(int k=nmn;k<=i;k++) if(!S[k][j]) A[k][j] = 0;
        DFS(i, j);
    }
    for(int i=0;i<n;i++){
        for(int j=0;j<m;j++){
            if(A[i][j]) printf("#");
            else printf(".");
        }
        puts("");
    }
    puts("");
    for(int i=0;i<n;i++){
        for(int j=0;j<m;j++){
            if(S[i][j]) printf("#");
            else printf(".");
        }
        puts("");
    }
}

