class UnionFindTree
{
private:
    const int n;
    int groupNum;       // グループの数
    vector<int> parent; // 親ノード
    vector<int> rank;   // 木の高さの上限
    vector<int> num;    // グループの要素数
    int find(int i){
        if(parent[i] == i)
            return i;
        return parent[i] = find(parent[i]);
    }
public:
    UnionFindTree(int n) : n(n){ // コンストラクタ
        groupNum = n;
        parent.resize(n);
        for(int i=0; i<n; ++i)
            parent[i] = i;
        rank.assign(n, 0);
        num.assign(n, 1);
    }
    void unite(int a, int b){ // aとbのグループを併合
        if((a = find(a)) != (b = find(b))){
            if(rank[a] < rank[b]){
                parent[a] = b;
                num[b] += num[a];
            }
            else{
                parent[b] = a;
                if(rank[a] == rank[b])
                    ++ rank[a];
                num[a] += num[b];
            }
            -- groupNum;
        }
    }
    bool same(int a, int b){ // aとbのグループが同じかを調べる
        return find(a) == find(b);
    }
    int getNum(){ // グループの数を返す
        return groupNum;
    }
    int getNum(int a){ // aのグループの要素数を返す
        return num[find(a)];
    }
    void getGroup(vector<vector<int> >& group){ // グループ構成を返す
        map<int, int> index;
        group.clear();
        for(int i=0; i<n; ++i){
            int a = find(i);
            if(index.find(a) == index.end()){
                index[a] = group.size();
                group.resize(group.size() + 1);
            }
            group[index[a]].push_back(i);
        }
    }
};

const int dy[] = {-1, 1, 0, 0};
const int dx[] = {0, 0, -1, 1};

int main()
{
    int h, w;
    cin >> h >> w;
    vector<string> s(h);
    for(int i=0; i<h; ++i)
        cin >> s[i];

    UnionFindTree uft(h*w);
    for(int y=1; y<h-1; ++y){
        for(int x=1; x<w-1; ++x){
            if(s[y][x] == '.')
                continue;
            for(int i=0; i<4; ++i){
                int y2 = y + dy[i];
                int x2 = x + dx[i];
                if(s[y2][x2] == '#')
                    uft.unite(y * w + x, y2 * w + x2);
            }
        }
    }

    vector<string> red = s;
    vector<string> blue(h, string(w, '#'));
    for(int y=1; y<h-1; ++y){
        for(int x=1; x<w-1; ++x){
            if(s[y][x] == '#')
                continue;

            vector<int> v;
            for(int i=0; i<4; ++i){
                int y2 = y + dy[i];
                int x2 = x + dx[i];
                if(red[y2][x2] == '#')
                    v.push_back(y2 * w + x2);
            }

            bool ok = true;
            for(unsigned i=0; i<v.size(); ++i){
                for(unsigned j=0; j<i; ++j){
                    if(uft.same(v[i], v[j]))
                        ok = false;
                }
            }
            if(ok){
                red[y][x] = '#';
                blue[y][x] = '.';
                for(unsigned i=0; i<v.size(); ++i)
                    uft.unite(v[i], y * w + x);
            }
        }
    }

    for(int i=0; i<h; ++i)
        cout << red[i] << endl;
    cout << endl;
    for(int i=0; i<h; ++i)
        cout << blue[i] << endl;

    return 0;
}

