int main(){
  int h,w,i,j,k;
  cin>>h>>w;
  char a[h][w],b[h][w],c[h][w];
  bool ub[h][w],uc[h][w];
  memset(a,'.',sizeof(a));
  memset(b,'.',sizeof(b));
  memset(c,'.',sizeof(c));
  memset(ub,0,sizeof(ub));
  memset(uc,0,sizeof(uc));
  for(i=0;i<h;i++){
    for(j=0;j<w;j++){
      cin >> a[i][j];
      if(a[i][j]=='#') b[i][j]=c[i][j]=a[i][j];
    }
  }
  for(j=1;j<w-1;j++) b[0][j]='#';
  for(i=0;i<h-1;i++) b[i][0]='#';
  for(i=1;i<h;i++) c[i][w-1]='#';
  for(j=1;j<w;j++) c[h-1][j]='#';

  typedef pair<int,int> P;
  queue<P> q;
  P p;
  int ax[]={1,-1,0,0};
  int ay[]={0,0,1,-1};
  q.push(P(0,0));
  while(!q.empty()){
    p=q.front();q.pop();
    if(p.first<0||p.first>=h||p.second<0||p.second>=w) continue;
    if(ub[p.first][p.second]||b[p.first][p.second]!='#') continue;
    ub[p.first][p.second]=true;
    for(k=0;k<4;k++) q.push(P(p.first+ay[k],p.second+ax[k]));
  }
  q.push(P(h-1,w-1));
  while(!q.empty()){
    p=q.front();q.pop();
    if(p.first<0||p.first>=h||p.second<0||p.second>=w) continue;
    if(uc[p.first][p.second]||c[p.first][p.second]!='#') continue;
    uc[p.first][p.second]=true;
    for(k=0;k<4;k++) q.push(P(p.first+ay[k],p.second+ax[k]));
  }

  for(j=1;j<w;j++){
    for(i=1;i<h;i++){
      if(ub[i][j]||b[i][j]!='#') continue;
      k=0;
      while((!ub[i-k-1][j])&&(!ub[i-k][j-1]))
	ub[i-k-1][j]=true,b[i-k-1][j]='#',k++;
      ub[i][j]=true;
    }
  }


  memset(uc,0,sizeof(uc));
  q.push(P(h-1,0));
  while(!q.empty()){
    p=q.front();q.pop();
    if(p.first<0||p.first>=h||p.second<0||p.second>=w) continue;
    if(uc[p.first][p.second]) continue;
    uc[p.first][p.second]=true;
    if(!ub[p.first][p.second]) c[p.first][p.second]='#'; 
    for(k=0;k<4;k++) q.push(P(p.first+ay[k],p.second+ax[k]));
  }


  for(i=0;i<h;i++){
    for(j=0;j<w;j++) cout << b[i][j];
    cout << endl;
  }
  cout << endl;
  for(i=0;i<h;i++){
    for(j=0;j<w;j++) cout << c[i][j];
    cout << endl;
  }
  return 0;
}

