constexpr array<int, 4> dx = {0, 1, 0, -1};
constexpr array<int, 4> dy = {1, 0, -1, 0};
class UFF {
    using Int = int;
    std::vector<Int> parent;
    std::vector<Int> rank;

public:
    explicit UFF(Int n) : parent(n, -1), rank(n, 0) {}

    Int find(Int x) {
        auto &px = parent[x];
        if (px < 0) {
            return x;
        } else {
            return px = find(px);
        }
    }

    bool unite(Int a, Int b) {
        const auto pa = find(a);
        const auto pb = find(b);
        if (pa == pb) return false;

        if (rank[pa] > rank[pb]) {
            parent[pa] += parent[pb];
            parent[pb] = pa;
        } else {
            parent[pb] += parent[pa];
            parent[pa] = pb;

            if (rank[pa] == rank[pb]) {
                rank[pb]++;
            }
        }
        return true;
    };

    Int size(Int x) {
        const auto px = find(x);
        return -parent[px];
    }

    bool is_same(Int a, Int b) {
        const auto pa = find(a);
        const auto pb = find(b);
        return pa == pb;
    }

    vector<Int> get_all_dset() {
        unordered_set<Int> dset;
        for (Int i = 0; i < parent.size(); ++i) {
            dset.insert(find(i));
        } // end i
        vector<Int> v(dset.size());
        Int i = 0;
        for (auto &&d : dset) {
            v[i++] = d;
        } // end d
//        sort(v.begin(), v.end());
        return v;
    }
};


class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}
    ll H, W;
    void run();
    vector<vector<char>> pur = make_mdvector(H, W, '.');
    vector<vector<int>> vis;
    int C = 0;
    vector<set<pair<int, int>>> vset;

    set<pair<int, int>> neighbor(int x, int y){
        C++;
        set<pair<int, int>> ans;
        queue<pair<int, int>> q;
        q.emplace(x, y);
        vis[x][y] = C;
        while(!q.empty()){
            int nx, ny;
            tie(nx, ny) = q.front();
            q.pop();
            for (int i = 0; i < 4; ++i) {
                int px, py;
                px = nx + dx[i]; py = ny + dy[i];
                if(isout(px, py)) continue;
                if(pur[px][py] == '#') {
                    if(vis[px][py] == 0) {
                        vis[px][py] = C;
                        q.emplace(px, py);
                    }
                }
                else {
                    ans.emplace(px, py);
                }
            } // end i
        }

        return ans;
    }

    vector<vector<char>> makecon(const vector<vector<char>>& wall){

        auto parent = make_mdvector(H, W, make_pair(-1, -1));
        auto col = vis;
        auto red = pur;
        queue<pair<int, int>> q;
        UFF uft(vset.size() + 1);
        for (int i = 0; i < vset.size(); ++i) {
            for (auto &&pxy : vset[i]) {
                if(wall[pxy.first][pxy.second] == '#') continue;
                auto&& ncol = col[pxy.first][pxy.second];
                if (ncol== 0){
                    ncol = i+1;
                    q.push(pxy);
                }
                else{
                    if(ncol != i+1 and !uft.is_same(i+1, ncol)) {
                        red[pxy.first][pxy.second] = '#';
                        uft.unite(i+1, ncol);
                    }
                }
            } // end pxy
        } // end i

        while(uft.size(1) < C) {
            auto nxy = q.front();
            q.pop();
            auto ncol = col[nxy.first][nxy.second];

            for (int i = 0; i < 4; ++i) {
                int px = nxy.first + dx[i], py = nxy.second + dy[i];
                if(isout(px, py)) continue;
                if(wall[px][py] == '#') continue;
                auto &&pcol = col[px][py];

                if (pcol == 0) {
                    pcol = ncol;
                    parent[px][py] = nxy;
                    q.emplace(px, py);
                } else if (pcol != ncol and !uft.is_same(pcol, ncol)) {
                    red[px][py] = '#';
                    auto p = parent[px][py];
                    while (p != make_pair(-1, -1)) {
                        red[p.first][p.second] = '#';
                        p = parent[p.first][p.second];
                    }
                    p = nxy;
                    while (p != make_pair(-1, -1)) {
                        red[p.first][p.second] = '#';
                        p = parent[p.first][p.second];
                    }
                    uft.unite(pcol, ncol);
                }
            } // end i
        }

        return red;
    }

    bool isout(int x, int y){
        return x < 0 or H <= x or y < 0 or W <= y;
    }
};


