void solver::run(){
    is >> H >> W;
    if(!is) return;
    pur = make_mdvector(H, W, '.');
    is >> pur;
    vis = make_mdvector(H, W, 0);
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if(pur[i][j] == '#' and !vis[i][j]){
                vset.push_back(neighbor(i, j));
            }
        } // end j
    } // end i

    auto red = makecon(pur);
    auto blue = makecon(red);
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            os << red[i][j];
        } // end j
        os << '\n';
    } // end i
    os << '\n';
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            os << blue[i][j];
        } // end j
        os << '\n';
    } // end i


}

