	FOR(i,1,max(m,n)+10)maxx[i]=0;
	int minx=max(m,n)+10;
	FOR(i,1,n)FOR(j,1,m){
		if (map[i][j]=='#'){
			mark[j]=true;
			maxx[j]=max(i,maxx[j]);
			minx=min(minx,i);
		}
	}
	FOR(i,1,n)FOR(j,1,m){
		if (i<=maxx[j] && i>=minx){
			vis[i][j]=true;
		}else{
			vis[i][j]=false;
		}
	}
	//FOR(i,1,n)FOR(j,1,m)if (map[i][j]=='#')vis[i][j]=false;
	int miny=m+10,maxy=0;
	FOR(j,1,m){
		if (map[minx][j]=='#'){
			miny=min(miny,j);
			maxy=max(maxy,j);
		}
	}
	FOR(j,miny,maxy){
		vis[minx][j]=true;
	}
	FOR(i,1,n){
		FOR(j,1,m){
			if (vis[i][j]/* || map[i][j]=='#'*/){
				cout<<"#";
			}else{
				cout<<".";
			}
		}cout<<endl;
	}cout<<endl;
	FOR(i,1,n){
		FOR(j,1,m){
			if (!vis[i][j] || map[i][j]=='#')	cout<<"#";
			else cout<<".";
		}cout<<endl;
	}
	return 0;
}

