#include <bits/stdc++.h>
#define rep(i,a,b) for(int i = a; i <= b; i++)
using namespace std;

int n,m,vis[510][510];
char s[510][510];

void find(int x,int y){
//    printf("%d %d\n",x,y);
    int px,py,minn = 1000;
    rep(i,1,n)
        if(vis[i][y]!=0 && abs(i-x)-1 <= minn ){
            if(i == x && y == py) continue;
            minn = abs(i-y)-1;
            px = i,py = y;
        }
    rep(i,1,n)
        if(vis[i][y-1]!=0 && abs(i-x) < minn){
            minn = abs(i-x);
            px = i, py = y-1;
        }
    int m1 = min(px,x), m2 = max(px,x);
//    printf("%d %d\n",m1,m2);
    rep(i,m1,m2)
        if(!vis[i][y]) vis[i][y] = 2;
}

int dir[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};

void solve(){
    queue<pair<int,int> > q;
    while(q.size()) q.pop();
    rep(i,1,n){
        q.push(make_pair(i,1));
        vis[i][1] = 3;
    }
    while(q.size()){
        int x = q.front().first, y = q.front().second;
//        printf("%d %d %d\n",x,y,vis[x][y]);
        vis[x][y] = 3;
        q.pop();
        rep(i,0,3){
            int tx = x+dir[i][0], ty = y+dir[i][1];
            if(tx < 1 || tx > n || ty < 1 || ty > m || vis[tx][ty] == 3 || vis[tx][ty] == 2){
                continue;
            }
//            printf("%d %d %d\n",tx,ty,vis[tx][ty]);
            vis[tx][ty] = 3;
            q.push(make_pair(tx,ty));
        }
    }
}

int main(){
    scanf("%d%d",&n,&m);
    rep(i,1,n) scanf("%s",s[i]+1);
    rep(j,2,n) vis[1][j] = 2;
    rep(i,1,n)
        rep(j,1,m)
            if(s[i][j] == '#') vis[i][j] = 1;
    rep(j,1,m){
        rep(i,1,n){
            if(vis[i][j] == 1) find(i,j);
        }
    }
    rep(i,1,n){
        rep(j,1,m) {
            if(vis[i][j] == 1 || vis[i][j] == 2) printf("#");
            else printf(".");
        }
        printf("\n");
    }
//    rep(i,1,n){
//        rep(j,1,m)
//            printf("%d ",vis[i][j]);
//        printf("\n");
//    }
    solve();
    printf("\n");
    rep(i,1,n){
        rep(j,1,m)
            if(vis[i][j] == 1 || vis[i][j] == 3) printf("#");
            else printf(".");
        printf("\n");
    }
    return 0;
}

