using namespace std;

int n, m, tab[1010][1010], l;
char znak;
bool met[1010][1010], met2[1010][1010], jest[1010][1010];

void dfs( int x, int y )
{
	met[x][y] = 1;
	if( tab[x+1][y] && !met[x+1][y] )dfs( x+1, y );
	if( tab[x-1][y] && !met[x-1][y] )dfs( x-1, y );
	if( tab[x][y+1] && !met[x][y+1] )dfs( x, y+1 );
	if( tab[x][y-1] && !met[x][y-1] )dfs( x, y-1 );
}
void dfs2( int x, int y )
{
//	cout<<x<<" "<<y<<endl;
	met2[x][y] = 1;
	if( !jest[x+1][y] && !met2[x+1][y])dfs2( x+1, y );
	if( !jest[x-1][y] && !met2[x][y-1])dfs2( x-1, y );
	if( !jest[x][y+1] && !met2[x][y-1])dfs2( x, y+1 );
	if( !jest[x][y-1] && !met2[x][y-1])dfs2( x, y-1 );	
}
int main()
{
	ios_base::sync_with_stdio( 0 );
	cin.tie( 0 );
	cin>>n>>m;
	for( int a = 0; a <= n+1; a++ )jest[a][0] = 1, jest[a][m+1] = 1;

	for( int a = 0; a <= m+1; a++ )
	{
	jest[0][a] = 1; jest[n+1][a] = 1;
}
	for( int a = 1; a <= n; a++ )
	{
		for( int b = 1; b <= m; b++ )
		{
			cin>>znak;
			if( znak == '#' )tab[a][b] = 1;
		}
	}
	for( int b = 1; b <= m; b++ )
	{
		l = 1;
		for( int a = 1; a <= n; a++ )
		{
			if( tab[a][b] && !met[a][b] )
			{
				dfs( a, b );
				l = a;	
			}
		}
		for( int a = 1; a <= l; a++ )
		{	
			if( !tab[a][b] )
			{	
			jest[a][b] = 1;
				met[a][b] = 1;
			}
		}
	}
	dfs2( n, m );
//	cout<<"ok"<<endl;
	for( int a = 1; a <= n; a++ )
	{
		for( int b = 1; b <= m; b++ )if( met[a][b] )cout<<'#';
		else cout<<'.';
		cout<<endl;
	}
	cout<<endl;
	for( int a = 1; a <= n; a++ )
	{
		for( int b = 1; b <= m; b++ )if( met2[a][b] )cout<<'#';
		else cout<<'.';
		cout<<endl;
	}	
	return 0;	
}

