	InputStream is;

	int __t__ = 1;
	int __f__ = 0;
	int __FILE_DEBUG_FLAG__ = __f__;
	String __DEBUG_FILE_NAME__ = "src/C1";

	FastScanner in;
	PrintWriter out;

	boolean[][] visited;
	boolean[][] isPainted;

	int[][] prevX, prevY;
	char[][] blue, red;

	boolean inside(int x, int y, int M, int N) {
		return x >= 0 && y >= 0 && x < M && y < N;
	}

	void restorePath(int curX, int curY, char[][] map) {
		{
			map[curY][curX] = '#';
			int nextY = prevY[curY][curX];
			int nextX = prevX[curY][curX];
			curX = nextX; curY = nextY;
		}

		while (curY != -1 && prevY[curY][curX] != -1 && map[curY][curX] != '#') {
			isPainted[curY][curX] = true;
			map[curY][curX] = '#';
			int nextY = prevY[curY][curX];
			int nextX = prevX[curY][curX];
			curX = nextX; curY = nextY;
		}
	}

	int[] vx = {-1, 0, 1, 0};
	int[] vy = {0, -1, 0, 1};
	void bfs(char[][] map, char[][] original) {
		int H = map.length, W = map[0].length;
		Queue<Point> q = new LinkedList<>(); 
		for (int i = 0; i < H; i++) {
			Arrays.fill(visited[i], false);
			for (int j = 0; j < W; j++) {
				prevX[i][j] = -1;
				prevY[i][j] = -1;
				if (map[i][j] == '#') q.add(new Point(j, i));
			}
		}

		while (!q.isEmpty()) {
			Point p = q.poll();
			if (original[p.y][p.x] == '#') {
				restorePath(p.x, p.y, map);
			}
			for (int d = 0; d < vx.length; d++) {
				int nx = p.x + vx[d];
				int ny = p.y + vy[d];

				if (inside(nx, ny, W, H) && !visited[ny][nx] && !isPainted[ny][nx]) {
					prevX[ny][nx] = p.x;
					prevY[ny][nx] = p.y;
					visited[ny][nx] = true;
					q.add(new Point(nx, ny));
				}
			}
		}
	}

	public void solve() {
		int H = in.nextInt(), W = in.nextInt();
		char[][] a = new char[H][];
		for (int i = 0; i < H; i++) {
			a[i] = in.next().toCharArray();
		}

		isPainted = new boolean[H][W];
		for (int i = 0; i < H; i++) {
			Arrays.fill(isPainted[i], false);
		}

		visited = new boolean[H][W];
		prevX = new int[H][W];
		prevY = new int[H][W];

		blue = new char[H][W];
		red = new char[H][W];
		for (int i = 0; i < H; i++) {
			Arrays.fill(blue[i], '.');
			Arrays.fill(red[i], '.');
			for (int j = 0; j < W; j++) {
				if (i == 0 || j == 0) {
					red[i][j] = '#';
					isPainted[i][j] = true;
				} else if (i == H - 1 || j == W - 1) {
					blue[i][j] = '#';
					isPainted[i][j] = true;
				}
			}
		}

		bfs(blue, a);
		bfs(red, a);

		for (int i = 0; i < H; i++) {
			out.println(String.valueOf(red[i]));
		}
		out.println();
		for (int i = 0; i < H; i++) {
			out.println(String.valueOf(blue[i]));
		}
		out.close();
	}

