public class Main {
  private static class Task {
    void solve(FastScanner in, PrintWriter out) {
      int H = in.nextInt();
      int W = in.nextInt();
      char[][] map = new char[H][];
      for (int i = 0; i < H; i++) {
        map[i] = in.next().toCharArray();
      }

      boolean[][] red = new boolean[H][W];
      boolean[][] blue = new boolean[H][W];
      for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
          if (j == 0) red[i][j] = true;
          else if (j == W - 1) blue[i][j] = true;
          else if (i % 2 == 0) red[i][j] = true;
          else blue[i][j] = true;
        }
      }

      for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
          if (map[i][j] == '.') continue;
          blue[i][j] = true;
          red[i][j] = true;
        }
      }

      for (int i = 0; i < H; i++) {
