class FastScanner {
	public static String debug = null;

	private final InputStream in = System.in;
	private int ptr = 0;
	private int buflen = 0;
	private byte[] buffer = new byte[1024];
	private boolean eos = false;

	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				if (debug != null) {
					buflen = debug.length();
					buffer = debug.getBytes();
					debug = "";
					eos = true;
				} else {
					buflen = in.read(buffer);
				}
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen < 0) {
				eos = true;
				return false;
			} else if (buflen == 0) {
				return false;
			}
		}
		return true;
	}

	private int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}

	private void skipUnprintable() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr]))
			ptr++;
	}

	public boolean isEOS() {
		return this.eos;
	}

	public boolean hasNext() {
		skipUnprintable();
		return hasNextByte();
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	public long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}

	public int nextInt() {
		return (int) nextLong();
	}

	public long[] nextLongList(int n) {
		return nextLongTable(1, n)[0];
	}

	public int[] nextIntList(int n) {
		return nextIntTable(1, n)[0];
	}

	public long[][] nextLongTable(int n, int m) {
		long[][] ret = new long[n][m];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				ret[i][j] = nextLong();
			}
		}
		return ret;
	}

	public int[][] nextIntTable(int n, int m) {
		int[][] ret = new int[n][m];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				ret[i][j] = nextInt();
			}
		}
		return ret;
	}
}

import java.util.*;

public class Main {

    int H, W;
    boolean[][] board;
    G[][] gd;
    List<G> gl = new ArrayList<>();

    void run() {
        Scanner sc = new Scanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        gd = new G[H + 2][W + 2];

        for (int h = 1; h <= H; h++) {
            String l = sc.next();
            for (int w = 1; w <= W; w++) {
                if (l.charAt(w - 1) == '#') {
                    gl.add(new G(w, h));
                }
            }
        }

        init();
        G s = gl.get(0);

        bfs(s.x, s.y);
        init();
        rbfs(s.x, s.y);

        printBoard();
        System.out.println();

        gd = new G[H + 2][W + 2];

        for (G g: gl) board[g.y][g.x] = false;

        bfs(s.x, s.y);
        init();

//        debug(gl);
//        for (int i = 1; i <= H + 1; i++) debug(gd[i]);

        rbfs(s.x, s.y);

        printBoard();
    }

    void init() {
        board = new boolean[H + 2][W + 2];
        Arrays.fill(board[0], true);
        Arrays.fill(board[H + 1], true);
        for (int i = 0; i < H + 2; i++) board[i][0] = board[i][W + 1] = true;
    }

    int[] dx = {-1,0,1,0};
    int[] dy = {0,-1,0,1};
    void bfs(int x, int y) {
        LinkedList<G> q = new LinkedList<>();
        q.add(new G(x, y));
        board[y][x] = true;
        while (!q.isEmpty()) {
            G cur = q.removeFirst();
            for (int i = 0; i < 4; i++) if (!board[cur.y + dy[i]][cur.x + dx[i]]) {
                board[cur.y + dy[i]][cur.x + dx[i]] = true;
                gd[cur.y + dy[i]][cur.x + dx[i]] = new G(cur.x, cur.y);
                q.addLast(new G(cur.x + dx[i], cur.y + dy[i]));
            }
        }
    }

    void rbfs(int x, int y) {
        for (G g: gl) {
            while (g.x != x || g.y != y) {
                board[g.y][g.x] = true;
                g = gd[g.y][g.x];
            }
        }
        board[y][x] = true;
    }

    void printBoard() {
        for (int h = 1; h <= H; h++) {
            for (int w = 1; w <= W; w++) {
                System.out.print(board[h][w] ? '#' : '.');
            }
            System.out.println();
        }
    }

    class G {
        int x, y;
        G(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return String.format("(x: %d, y: %d)", x, y);
        }
    }

    void debug(Object...os) {
        System.err.println(Arrays.deepToString(os));
    }

    public static void main(String[] args) {
        new Main().run();
    }
}

