public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int h = sc.nextInt();
		int w = sc.nextInt();

		char[][] a = new char[h][];
		for (int i = 0; i < h; i++) {
			a[i] = sc.next().toCharArray();
		}

