		char[][] blue = new char[h][w];
		for (int i = 0; i < h; i++) {
			Arrays.fill(red[i], '.');
			Arrays.fill(blue[i], '.');
		}

		for (int i = 1; i < w; i++) {
			red[0][i] = '#';
			blue[h - 1][i - 1] = '#';
		}
		for (int i = 1; i < h; i++) {
			red[i][w - 1] = '#';
			blue[i - 1][0] = '#';
		}

		if (h > 3 && w > 3) {
			for (int j = 1; j < w - 1; j++) {
				for (int i = 1; i < h - 1; i++) {
					if (j % 2 == 1) {
						red[i][j] = '#';
					} else {
						blue[i][j] = '#';
					}
				}
			}
		}

		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (a[i][j] == '#') {
					red[i][j] = '#';
					blue[i][j] = '#';
				}
			}
		}

		for (int i = 0; i < h; i++) {
