                x[j][i % 2 == 0 ? 0 : w - 1] = true;
                for (int k = 1; k < w - 1; ++k) {
                    if (j % 2 == i || a[j][k]) {
                        x[j][k] = true;
                    }
                }
            }
            print(x);
        }
