				int ny0 = y0 + DY[dir];
				if (nx0 < 0 || nx0 >= h || ny0 < 0 || ny0 >= w || a[nx0][ny0] != 0) {
					dir = (dir + 1) % 4;
					continue;
				}
				x0 = nx0;
				y0 = ny0;

				x1 += DX[dir ^ 2];
				y1 += DY[dir ^ 2];
				break;
			}
		}

