using System;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Numerics;
using System.Text;
using Problem = Tmp.Problem;
namespace Tmp
{
	//using GeometryLong;
	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const long Mod = 1000000007;
		RandomSFMT rand = Program.rand;
		int Y, X;
		bool[,] map;
		void Read()
		{
			sc.Read(out Y, out X);
			map = sc.Board<bool>(X, Y, (c, x, y) => c == '#');
		}
		List<Tuple<int, int>>[] es;
		void AddEdge(int f, int t, int e)
		{
			es[f].Add(new Tuple<int, int>(t, e));
			es[t].Add(new Tuple<int, int>(f, e));
		}
		void SolveOne()
		{
			var V = X * Y;
			es = new List<Tuple<int, int>>[V];
			for (var i = 0; i < V; i++) es[i] = new List<Tuple<int, int>>();
			var ps = new List<int>();
			var uf = new UnionFindTree(V);
			for (var x = 0; x < X; x++)
				for (var y = 0; y < Y; y++)
				{
					var p = x * Y + y;
					if (x < X - 1) { AddEdge(p, p + Y, map[x, y] || map[x + 1, y] ? 1 : 0); if (map[x, y] && map[x + 1, y]) uf.UniteCategory(p, p + Y); }
					if (y < Y - 1) { AddEdge(p, p + 1, map[x, y] || map[x, y + 1] ? 1 : 0); if (map[x, y] && map[x, y + 1]) uf.UniteCategory(p, p + 1); }
					if (map[x, y]) ps.Add(p);
				}
			var s = ps[0];
			int[] d, prev;
			{
				d = new int[V];
				prev = new int[V];
				for (var i = 0; i < V; i++) { d[i] = Func.Inf; prev[i] = -1; }
				var queue = new PriorityQueue<Tuple<int, int, int>>((x, y) => x.Item2.CompareTo(y.Item2));
				d[s] = 0; prev[s] = -1;
				queue.Enqueue(new Tuple<int, int, int>(s, 0, -1));
				while (!queue.IsEmpty)
				{
					var p = queue.Dequeue();
					var v = p.Item1;
					if (d[v] < p.Item2) continue;
					foreach (var e in es[v])
					{
						int tmp = d[v] + e.Item2, u = e.Item1;
						if (d[u] > tmp) queue.Enqueue(new Tuple<int, int, int>(u, d[u] = tmp, prev[u] = v));
					}
				}
			}
			var ans = new bool[X, Y];
			for (var i = ps.Count - 1; i >= 0; i--)
			{
				var p = ps[i];
				if (uf.IsSameCategory(s, p)) continue;
				uf.UniteCategory(s, p);
				while (p != s && !ans[p / Y, p % Y])
				{
					ans[p / Y, p % Y] = true;
					p = prev[p];
				}
			}
			foreach (var p in ps) ans[p / Y, p % Y] = true;
			for (var y = 0; y < Y; y++)
			{
				for (var x = 0; x < X; x++) pr.Write(ans[x, y] ? '#' : '.');
				pr.WriteLine();
			}
			pr.WriteLine();
			for (var y = 0; y < Y; y++) for (var x = 0; x < X; x++) ans[x, y] = map[x, y] || !ans[x, y];
			uf = new UnionFindTree(V);
			for (var x = 0; x < X; x++)
				for (var y = 0; y < Y; y++)
				{
					var p = x * Y + y;
					if (x < X - 1 && ans[x, y] && ans[x + 1, y]) uf.UniteCategory(p, p + Y);
					if (y < Y - 1 && ans[x, y] && ans[x, y + 1]) uf.UniteCategory(p, p + 1);
				}
			for (var y = 0; y < Y; y++)
			{
				for (var x = 0; x < X; x++) pr.Write(uf.IsSameCategory(s, x * Y + y) ? '#' : '.');
				pr.WriteLine();
			}
		}
	}
}
