	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const long Mod = 1000000007;
		RandomSFMT rand = Program.rand;
		int Y, X;
		bool[,] map;
		void Read()
		{
			sc.Read(out Y, out X);
			map = sc.Board<bool>(X, Y, (c, x, y) => c == '#');
		}
		void SolveOne()
		{
			var g = new UndirectedGraph<object, bool>(X * Y);
			var ps = new List<int>();
			var uf = new UnionFindTree(X * Y);
			for (var x = 0; x < X; x++)
				for (var y = 0; y < Y; y++)
				{
					var p = x * Y + y;
					if (x < X - 1) { g.AddEdge(p, p + Y, map[x, y] || map[x + 1, y]); if (map[x, y] && map[x + 1, y]) uf.UniteCategory(p, p + Y); }
					if (y < Y - 1) { g.AddEdge(p, p + 1, map[x, y] || map[x, y + 1]); if (map[x, y] && map[x, y + 1]) uf.UniteCategory(p, p + 1); }
					if (map[x, y]) ps.Add(p);
				}
			var s = ps[0];
			var d = g.DijkstraFromL(s, b => b ? 1 : 0);
			/*for (var y = 0; y < Y; y++)
			{
				for (var x = 0; x < X; x++) Console.Write(d[x * Y + y].First + " ");
				Console.WriteLine();
			}
			for (var y = 0; y < Y; y++)
			{
				for (var x = 0; x < X; x++)
				{
					if (d[x * Y + y].Second < 0) Console.Write("   ");
					else
					{
						var a = d[x * Y + y].Second - x * Y - y;
						char c = ' ';
						if (a == 1) c = '↓';
						else if (a == -1) c = '↑';
						else if (a > 0) c = '→';
						else c = '←';
						Console.Write("{0} ", c);
					}
				}
				Console.WriteLine();
			}*/
			var N = ps.Count;
			var ans = new bool[X, Y];
			ans[s / Y, s % Y] = true;
			while (uf.GetSize(s) < N)
			{
				var p = ps[ps.Count - 1];
				ps.RemoveAt(ps.Count - 1);
				if (uf.IsSameCategory(s, p)) continue;
				uf.UniteCategory(s, p);
				while (p != s)
				{
					ans[p / Y, p % Y] = true;
					p = d[p].Second;
				}
			}
			for (var y = 0; y < Y; y++)
			{
				for (var x = 0; x < X; x++) pr.Write(map[x,y] || ans[x, y] ? '#' : '.');
				pr.WriteLine();
			}
			pr.WriteLine();
			for (var y = 0; y < Y; y++)
			{
				for (var x = 0; x < X; x++) pr.Write(map[x, y] || !ans[x, y] ? '#' : '.');
				pr.WriteLine();
			}
		}
	}
