using System;
using System.Collections.Generic;
class Solve{
    public int h;
    public int w;
    public bool[][] a;
    bool[][] watched;
    bool[][] blue;
    public Solve(){}
    public static int Main(){
        new Solve().Calc();
        return 0;
    }
    void dfs(int i,int j){
        watched[i][j] = true;
        blue[i][j] = true;
        if(i != h-1 && !watched[i+1][j] && a[i+1][j]){
            dfs(i+1,j);
        }
        if(i != 0 && !watched[i-1][j] && a[i-1][j]){
            dfs(i-1,j);
        }
        if(j != w-1 && !watched[i][j+1] && a[i][j+1]){
            dfs(i,j+1);
        }
        if(j != 0 && !watched[i][j-1] && a[i][j-1]){
            dfs(i,j-1);
        }
    }
    void Calc(){
        getinput();
        watched = new bool[h][];
        blue = new bool[h][];
        for(int i = 0;i < h;i++){
            watched[i] = new bool[w];
            blue[i] = new bool[w];
            for(int j = 0;j < w;j++){
                watched[i][j] = false;
                if(i == 0){
                    blue[i][j] = true;
                }
                else{
                    blue[i][j] = false;
                }
            }
        }
        for(int i = 1;i < h-1;i++){
            for(int j = 1;j < w-1;j++){
                if(a[i][j] && !watched[i][j]){
                    int k = 1;
                    while(true){
                        if(blue[i-k][j]){
                            break;
                        }
                        else{
                            blue[i-k][j] = true;
                            k++;
                        }
                    }
                    dfs(i,j);
                }
            }
        }
        for(int i = 0;i < h;i++){
            for(int j = 0;j < w;j++){
                if(!blue[i][j] || a[i][j]){
                    Console.Write("#");
                }
                else{
                    Console.Write(".");
                }
                if(j == w-1){
                    Console.WriteLine("");
                }
            }
        }
        Console.WriteLine("");
        for(int i = 0;i < h;i++){
            for(int j = 0;j < w;j++){
                if(blue[i][j]){
                    Console.Write("#");
                }
                else{
                    Console.Write(".");
                }
                if(j == w-1){
                    Console.WriteLine("");
                }
            }
        }
    }
    void getinput(){
        string[] str = Console.ReadLine().Split(' ');
        h = int.Parse(str[0]);
        w = int.Parse(str[1]);
        a = new bool[h][];
        for(int i = 0;i < h;i++){
            string s = Console.ReadLine();
            a[i] = new bool[w];
            for(int j = 0;j < w;j++){
                if(s[j] == '#'){
                    a[i][j] = true;
                }
                else{
                    a[i][j] = false;
                }
            }
        }
    }    
}

