    {
        var sb = new StringBuilder();
        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                bool a = j == W - 1;
                bool b = (i % 2 == 1) && (j != 0);
                bool c = A[i][j] == '#';
                if (a || b || c)
                {
                    sb.Append('#');
                }
                else
                {
                    sb.Append('.');
                }
            }
            sb.AppendLine();
        }
        Console.Write(sb.ToString());
    }

    public void Solve()
