public class Solver
{
    public void Solve()
    {
        int n = ReadInt();
        int m = ReadInt();
        var a = ReadLines(n);

        var b = new char[n][];
        var w = new char[n][];
        for (int i = 0; i < n; i++)
        {
            b[i] = Enumerable.Repeat('.', m).ToArray();
            w[i] = Enumerable.Repeat('.', m).ToArray();
        }

        for (int i = 0; i < m; i++)
            b[0][i] = b[n - 1][i] = '#';
        for (int i = 1; i < n - 1; i++)
        {
            for (int j = 2; j < m; j += 2)
                b[i][0] = b[i][j] = b[i][m - 1] = '#';
            for (int j = 1; j < m - 1; j += 2)
                w[i][j] = '#';
        }

        for (int i = 1; i < m - 1; i += 2)
            for (int j = 1; j < n - 1; j++)
                if (a[j][i] == '#')
                    b[j][i] = '#';

        for (int i = 2; i < m - 1; i += 2)
        {
            bool f = true;
            for (int j = 1; j < n - 1; j++)
                if (a[j][i] == '#')
                {
                    f = false;
                    w[j][i] = '#';
                }
            if (f)
            {
                b[1][i] = '.';
                w[1][i] = '#';
            }
        }

        for (int i = 0; i < n; i++)
            Write(new string(b[i]));
        Write();
        for (int i = 0; i < n; i++)
            Write(new string(w[i]));
    }

