				{
					row += DRow[dir];
					col += DCol[dir];
					if (col >= 0)
					{
						res[row][col] = '#';
					}
				}
				dir = (dir + 1) & (Dirs - 1);
				s[b] -= 2;
				if (s[b] < 0)
				{
					break;
				}
				b ^= 1;
			}
			return res;
		}

		char [] [] b = build (0, -2, [w + 1, h - 1]);
