            que.push_back((x, y));
        });
    }
    for i in 0..h {
        println!(
            "{}",
            (0..w)
                .map(|j| if r[i][j] || a[i][j] == '#' { '#' } else { '.' })
                .collect::<String>()
        );
    }
    println!("");
    for i in 0..h {
        println!(
            "{}",
            (0..w)
                .map(|j| if b[i][j] || a[i][j] == '#' { '#' } else { '.' })
                .collect::<String>()
        );
    }
}

