use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        h: usize,
        w: usize,
        field: [chars; h],
    }
    let mut res1 = vec![String::new(); h];
    let mut res2 = vec![String::new(); h];
    for y in 0..h {
        for x in 0..w {
            if y != h - 1 && (y == 0 || x % 2 == 0 || field[y][x] == '#') {
                res1[y].push('#');
            } else {
                res1[y].push('.');
            }
        }
    }
    for y in 0..h {
        for x in 0..w {
            if y != 0 && (y == h - 1 || x % 2 == 1 || field[y][x] == '#') {
                res2[y].push('#');
            } else {
                res2[y].push('.');
            }
        }
    }
    for s in &res1 {
        writeln!(buf, "{}", s);
    }
    writeln!(buf, "");
    for s in &res2 {
        writeln!(buf, "{}", s);
    }
    buf
}

