    pub fn len_adjacency(&self, x: usize, y: usize) -> usize {
        (x + 1 < self.height) as usize
            + (y + 1 < self.width) as usize
            + (x > 0) as usize
            + (y > 0) as usize
    }
    pub fn for_each_adjacency<F: FnMut(usize, usize)>(&self, x: usize, y: usize, mut f: F) {
        if x + 1 < self.height {
            f(x + 1, y);
        }
        if y + 1 < self.width {
            f(x, y + 1);
        }
        if x > 0 {
            f(x - 1, y);
        }
        if y > 0 {
            f(x, y - 1);
        }
    }
}
fn main() {
    input!(h, w, a: [chars; h]);
    let mut cnt = 0;
    let gg = GridGraph::new(h, w);
    let mut g = vec![vec![0; w]; h];
    let mut vis = vec![vec![false; w]; h];
    let mut que = std::collections::VecDeque::new();
    let mut p = (0, 0);
    for i in 0..h {
        for j in 0..w {
            if !vis[i][j] && a[i][j] == '#' {
                p = (i, j);
                cnt += 1;
                vis[i][j] = true;
                que.push_back((i, j));
                while let Some((i, j)) = que.pop_front() {
                    g[i][j] = cnt;
                    gg.for_each_adjacency(i, j, |x, y| {
                        if !vis[x][y] && a[x][y] == '#' {
                            vis[x][y] = true;
                            que.push_back((x, y));
                        }
                    });
                }
            }
        }
    }
    let mut r = vec![vec![false; w]; h];
    let mut b = vec![vec![false; w]; h];
    let mut par = vec![vec![None; w]; h];
    let mut connected = std::collections::HashSet::new();
    connected.insert(cnt);
    que.push_back(p);
    while let Some((i, j)) = que.pop_front() {
        gg.for_each_adjacency(i, j, |x, y| {
            if par[x][y].is_some() || r[x][y] {
                return;
            }
            let prevl = connected.len();
            par[x][y] = Some((i, j));
            gg.for_each_adjacency(x, y, |nx, ny| {
                if (i, j) != (nx, ny) {
                    if g[nx][ny] > 0 && !connected.contains(&g[nx][ny]) {
                        connected.insert(g[nx][ny]);
                    }
                }
            });
            if prevl < connected.len() {
                r[x][y] = true;
                let (mut x, mut y) = (x, y);
                while let Some((px, py)) = par[x][y] {
                    x = px;
                    y = py;
                    r[x][y] = true;
                }
            }
            que.push_back((x, y));
        });
        if connected.len() >= cnt {
            que.clear();
        }
    }
    que.push_back(p);
    while let Some((i, j)) = que.pop_front() {
        gg.for_each_adjacency(i, j, |x, y| {
            if r[x][y] || b[x][y] {
                return;
            }
            b[x][y] = true;
            que.push_back((x, y));
        });
    }
    for i in 0..h {
        println!(
            "{}",
            (0..w)
                .map(|j| if r[i][j] || a[i][j] == '#' { '#' } else { '.' })
                .collect::<String>()
        );
    }
    println!("");
    for i in 0..h {
        println!(
            "{}",
            (0..w)
                .map(|j| if b[i][j] || a[i][j] == '#' { '#' } else { '.' })
                .collect::<String>()
        );
    }
}

