    fn print_board(board: &Vec<Vec<u8>>) {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        for line in board {
            lock.write(line).unwrap();
            lock.write(&[b'\n']).unwrap();
        }
        lock.flush().unwrap();
    }

    print_board(&blue);
    println!("");
    print_board(&red);

